quests[14186] = { id = 14186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Riding Trainer Advertisement (60)" }
quests[14187] = { id = 14187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Riding Trainer Advertisement (70)" }
quests[14188] = { id = 14188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rächt Furien!", description = "Das darf nicht sein!\n\nMein geliebter Bruder – vernichtet vom Abschaum der Allianz!\n\nSie sollen leiden, {race}! Findet eine Möglichkeit, ihnen Schmerzen zu bereiten! Ich werde nicht ruhen, bis das erledigt ist...\n\nFurien hat vor seinem Tod uralte Artefakte in den östlichen Regionen untersucht. Sprecht mit Sorrem. Vielleicht kann er Euch die Spuren meines Bruders weisen.", sourceObjective = "Cerelia will, dass Ihr mit Sorrem in Furions Posten sprecht.", completion = "Furiens Dahinscheiden ist... bedauerlich.\n\nIch werde alles tun, was ich kann, um Euch bei dabei zu helfen, seinen Tod zu rächen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14189] = { id = 14189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Übersetzung", description = "Es stimmt, dass Furien seine letzten Tage einem besonderen Forschungsprojekt gewidmet hat. Worum es dabei genau ging, wollte er mir nicht sagen.\n\nGlücklicherweise war ich in der Lage, sein Tagebuch in meinen Besitz zu bringen, aber es ist in einem Code geschrieben, den ich nicht entschlüsseln kann.\n\nVielleicht gibt es einen Dekodierungsschlüssel für seine Übersetzung in der Region im Osten, wo er viel Zeit verbracht hat.\n\nNehmt das Tagebuch, {class}, und sprecht mit Narimar, wenn Ihr bereit seid, dieses Geheimnis zu untersuchen.", sourceObjective = "Sorrem will, dass Ihr die uralten Schrifttafeln findet.\n\nSprecht mit Narimar in Furions Posten, um dorthin zu reiten, wo Furien seine Nachforschungen betrieben hat.\n\nBereitgestellter Gegenstand:", completion = "Beim Vergleich der Buchstaben der uralten Schrifttafel mit denen in Furiens Tagebuch fällt auf, dass es deutliche Entsprechungen gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14190] = { id = 14190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das perfekte Prisma", description = "Es muss eine Möglichkeit geben, die Versteinerung durch die Basilisken wieder rückgängig zu machen. Diese lästigen Saboteure der Nachtelfen, die schon länger um meine Mine schleichen, müssen etwas wissen, was uns entgeht. Sie scheinen gegen den Blick der Bestien immun zu sein!\n\nIch will, dass Ihr ihr Geheimnis herausfindet, {name}. Greift Euch ein paar der Saboteure der Talrendisspitze, die im hinteren Teil des Tagebaus herumschleichen, und holt Euch eine Probe des Zaubers oder Schnickschnacks oder was auch immer ihnen ihre Immunität verleiht. Funkt mich vom Hauptgebäude der Schmiede aus an, sobald Ihr Erfolg hattet.", sourceObjective = "Gelangt in den Besitz eines Kristallanhängers von einem Saboteur der Talrendisspitze im Tagebau am Gebirgsfuß.", progress = "<Skurrile Goblinlautsprecher rauschen und knacksen.>", completion = "<Zignibbels Stimme quäkt über die Lautsprecher.>\n\n{name}, seid Ihr das? Seid Ihr noch am Leben? Ihr vergeudet doch nicht meine Sprengstoffvorräte, oder?\n\nHmmm... Ihr sagt, ihr hättet einen Kristallanhänger gefunden. Das ergibt Sinn. Ein perfektes Prisma würde den Blick des Basilisken brechen. Vielleicht können wir das zu unserem Vorteil ausnutzen. Zeit für ein wenig Wissenschaft!", sourceObjectiveStatus = "unverified-source-field" }
quests[14191] = { id = 14191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf Furiens Spuren", description = "Ihr könnt die Einzelteile des Textes entschlüsseln, aber es wird ausführlicher Studien bedürfen, bevor Furiens Arbeit einen Sinn ergeben wird.\n\nJetzt seht Ihr in den Nordosten und glaubt, dass Ihr ein paar Ruinen ausmachen könnt, die in dem Tagebuch abgebildet sind.\n\nSofern Ihr das beurteilen könnt, scheinen diese Ruinen für Furiens Forschungen eine Rolle gespielt zu haben.", sourceObjective = "Die uralten Schrifttafeln am Schrein von Elune haben Euch den Weg zu dreien der markanten Ruinen in Sargeron gewiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14192] = { id = 14192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tausche Linse gegen Prisma", description = "Wenn Euer Prisma darauf eingestellt ist, den Blick des Basilisken zu brechen, können wir die Eigenschaften des Kristalls dazu verwenden, den Verwandlungsprozess umzukehren. Alles, was wir brauchen, ist eine Energiequelle.\n\nIn der Waffenkiste zu Eurer Rechten findet Ihr den Prototyp eines Laser-Bergbaubohrers. Ich liebe das Teil, aber es wurden fast täglich Leute damit zerstückelt. Das fing irgendwann an zu nerven. Schnappt Euch den Laserbohrer und tauscht seine Linse gegen Euren Kristall aus...", sourceObjective = "Bringt den Kristallanhänger zur Waffenkiste im Hauptquartier des Tagebaus am Gebirgsfuß.", progress = "<Die Waffenkiste ist vollgestopft mit grässlichen und kaputten Experimentalgeräten. An einigen von ihnen hängen noch Gliedmaßen von Goblins. Ihr entdeckt den Laserbohrer, der liebevoll in einen samtgefütterten Holzkasten gebettet wurde.>", completion = "<Ihr löst das Linsenelement und lasst den Kristall an seinen Platz rutschen. Die Waffe summt unheilvoll.>", sourceObjectiveStatus = "unverified-source-field" }
quests[14193] = { id = 14193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts, was ein paar Melonen nicht richten können", description = "Die Markierungen auf den Ruinen hier machen eine Sache deutlich: Mit dem uralten Brunnen im Heiligtum von Elune scheint es etwas Besonderes auf sich zu haben.\n\nEs scheint, dass er demjenigen besondere Kräfte verleiht, der sein Gesicht in seinem Wasser wäscht. Als erstes muss es im uralten Brunnen natürlich etwas geben, mit dem man sich waschen kann.\n\nWährend Ihr über dieses Problem nachdenkt, bemerkt Ihr eine Melone an den Wurzeln eines Baumes...", sourceObjective = "Sammelt 8 Melonenfrüchte.", sourceObjectiveStatus = "unverified-source-field" }
quests[14194] = { id = 14194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederverfleischlichung", description = "<Das nahegelegene Funkgerät ruft Euch etwas zu.>\n\nHey {name}, habt Ihr den Laser? Gut! Schaut niemals direkt hinein.\n\nZielt mit dem Schätzchen auf meine versteinerten Arbeiter und das gebrochene Licht sollte den Versteinerungsprozess umkehren. Oder er schmilzt sie. Auch egal. Sorgt dafür, dass meine Arbeiter mir wieder Profit bringen! Und falls der Wiederverfleischlichungsprozess dafür sorgt, dass sie irre werden, solltet Ihr sie töten. Wegen der Versicherung. Horzak ENDE!", sourceObjective = "Verwendet den Wiederverfleischlicher, um acht Bergfußminenarbeiter im Tagebau am Gebirgsfuß wieder zu entsteinern.", progress = "Na sieh mal einer an. Alle Eure Gliedmaßen sind in Ordnung.", completion = "Ah, gut. Jetzt können sich diese Faulpelze wieder an die Arbeit machen. Ihr habt Euch einen Teil des Gewinns verdient – abzüglich der üblichen Gebühren für die Gesellschaft. Wählt!", sourceObjectiveStatus = "unverified-source-field" }
quests[14195] = { id = 14195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schleier lichtet sich", description = "Irgendetwas ist anders... Vielleicht eine Nebenwirkung von Elunes Reinigungsrituals.\n\nWährend Ihr noch weit davon entfernt seid, die uralte Sprache perfekt zu verstehen, haben sich Eure Kenntnisse jedoch deutlich verbessert.\n\nFuriens Enthusiasmus scheint sich vor allem auf die Ruinen in den nördlichen Bergen von Sargeron zu beziehen. Er hatte das Gefühl, dort sei irgendetwas, das ihm helfen würde, die Allianz aus dieser Region zu vertreiben.\n\nIhr klappt das Tagebuch zu und seid fest entschlossen, diese Ruinen zu finden und ihnen ihre Geheimnisse zu entlocken.", sourceObjective = "Furiens Tagebuch hat Euch angewiesen, die Ruinen des Palastes von Elune im Norden Sargeron zu suchen.", completion = "Nun ist es Euch klar, warum Ihr hierher geführt wurdet.\n\nIhr erkennt diesen uralten Runenstein aus Furiens letztem Tagebucheintrag: \n\n\"Die Uralten verehrten die Edelsteine, die von diesem mystischen Objekt erschaffen wurden und sie behaupteten, dass es Geschenke der Göttin selbst seien. Sie glaubten, es handele sich um Waffen, die in der Lage sind, sie von jedem Feind zu erlösen.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[14196] = { id = 14196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerteufel", description = "Ihr seid nun in der Lage, den Text aus dem Tagebuch zu verstehen.\n\nAuf den Runensteinen steht geschrieben, dass den Edelsteinen des Monuments die Macht innewohnt, einen Feuersturm zu entfesseln.\n\nDer Sturm könnte zu einer mächtigen Waffe werden, indem Elune ausdauernd gehuldigt würde oder indem man ihn mit der spirituellen Energie der Gefallenen auflädt.\n\nIhr betrachtet die kürzlich aufgetauchten Geister von Elunes Jüngerinnen und kommt zu dem Schluss, dass Ihr weder die Zeit noch die Neigung dazu habt, der Göttin Eures Feindes zu huldigen...", sourceObjective = "Ihr müsst einen tobenden Vortex erzeugen, indem Ihr 7 Jüngerinnen von Elune mit Eurem Feuersturm vernichtet.\n\nSolltet Ihr Euren Vortexedelstein verlieren, erhaltet Ihr einen weiteren aus dem uralten Vortexrunenstein.", completion = "Es ist vollbracht! Furiens ausdauernde Forschung war nicht vergebens.\n\nDer tobende Vortex steht endlich bereit und kann auf Eure Feinde losgelassen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[14197] = { id = 14197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein zu erfüllendes Pensum", description = "Gebirgsfußeisen ist eine spröde Legierung, aber es erfüllt die Sicherheitsstandards der Goblins – wenn man die richtigen Leute schmiert. Zignibbel hat Schwierigkeiten bei der Produktion, aber das ändert nichts an meinen Fristen. Ich habe ein Pensum zu erfüllen!\n\nBegebt Euch in den Tagebau am Gebirgsfuß und sammelt so viel Barren Gebirgsfußeisen, wie Ihr finden könnt. Sie sollten dort stapelweise herumliegen und bereit zum Transport sein.", sourceObjective = "Sammelt 20 Barren Gebirgsfußeisen aus dem Tagebau am Gebirgsfuß in Azshara.", progress = "Habt Ihr die Lieferung?", completion = "Gute Arbeit! Wenn es um Eisen geht, ist mir die Quantität immer wichtiger als die Qualität.", sourceObjectiveStatus = "unverified-source-field" }
quests[14198] = { id = 14198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vortex der Vergeltung", description = "Ihr könnt Euch eines Anflugs von Stolz nicht erwehren, dass Ihr dieses lang verlorene Geheimnis der uralten Verehrer von Elune aufgedeckt habt.\n\nIhr besitzt nun die Macht, Eurem Feind großen Schaden zuzufügen.\n\nDa nur Furiens unermüdliche Arbeit dies ermöglicht hat, scheint es nur gerecht, dass diese Waffe auf diejenigen losgelassen werden sollte, die für seinen Tod verantwortlich sind.\n\nDer Abschaum der Allianz auf der Nijelspitze soll für den Angriff auf die Horde bezahlen!", sourceObjective = "Setzt den Edelstein des tobenden Vortexes gegen die Ruine der Nijelspitze ein. Während ihr den Feuersturm befehligt, tötet 40 Verteidiger der Nijelspitze und verbrennt 15 Händler der Nijelspitze.\n\nSolltet Ihr Euren Vortexedelstein verlieren, erhaltet Ihr einen weiteren aus dem uralten Vortexrunenstein.", completion = "Äußerst beeindruckend, {class}.\n\nIhr habt Furiens Arbeit abgeschlossen und Rache auf seine Mörder herabregnen lassen.\n\nIhr habt der Seele meines Bruders Frieden gebracht und meinem Geist ebenfalls. Bitte nehmt dieses Geschenk zum Dank für Euren Einsatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[14199] = { id = 14199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesbeweis: Der Schwarze Ritter", description = "Mein Berufsgenosse, Erzmagier Timear hat mich gebeten, Euch vor etwas Schrecklichem zu warnen. Bald werdet Ihr an der Prüfung der Champions im Argentumkolosseum in Eiskrone teilnehmen. Nehmt Euch in Acht, denn es wird sich jemand einmischen, den sie den Schwarzen Ritter nennen.\n\nBringt mir ein Fragment seiner Seele, damit die Kirin Tor wissen, dass er erledigt ist. Mir wurde gesagt, dass, solltet Ihr versagen, dies Euer eigenes Verderben sei.", sourceObjective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr ihm ein Seelenfragment des Schwarzen Ritters bringt.\n\nDiese Aufgabe kann nur auf dem Schwierigkeitsgrad \"Heroisch\" abgeschlossen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14200] = { id = 14200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kickoff Mail Marker" }
quests[14201] = { id = 14201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tausende Geschichten im Sand", description = "Die Ruinen um den Mennarsee im Osten erzählen eine Geschichte. Die niedrigeren Völker – wie diese plumpen Zwerge – würden mit Hacken und Schaufeln nach der Wahrheit suchen. <Malynea rümpft ihre Nase.> Wir werden ein wenig elegantere Verfahren einsetzen.\n\nMeine Wahrsagemagie ist ein wenig eingerostet, aber mit dem richtigen Schmuckstück sollte ich in der Lage sein, durch den Vorhang der Zeit zu sehen. Die Gebeine meiner Vorväter sind längst zu Staub zerfallen, aber ein paar ihrer persönlichen Schätze könnten noch existieren. Bringt sie mir.", sourceObjective = "Sammelt 5 geborgene Artefakte aus den Ruinen um den Mennarsee in Azshara.", progress = "Habt Ihr Euch für mich die Hände schmutzig gemacht?", completion = "<Malynea zieht die Augenbrauen zusammen und besieht die Artefakte, die Ihr ihr gebracht habt.>\n\nDie Geister der Toten gehen also noch immer in diesen alten Gemäuern um, wie? Nun, {name}, ich zähle auf ihre Hilfe. Hören wir uns an, was die Toten zu sagen haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[14202] = { id = 14202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspiziert das Seeufer", description = "All diese verflixten uralten Ruinen müssen dem Erdboden gleichgemacht werden, wenn wir jemals Azsharas ganzes Potenzial sehen wollen. Werft einen Blick auf meine Karte hier. Seht Ihr den Mennarsee im Osten? Ich kann Euch sagen, was ich dort sehe: ein zukünftiges Lager für Raketentreibstoff!\n\nAber der Boden muss eine ganz besondere Beschaffenheit haben, bevor wir ihn abmähen, planieren, aufschütten und den See ebnen können. Meine Landvermesser wurden bisher alle von dem gespenstischen Spuk in der Region vergrault. Begleitet einen meiner Nachwuchsfeldmesser in das Gebiet und sorgt dafür, dass er die Ergebnisse der Messausrüstung ablesen kann, die dort aufgestellt wurden.", sourceObjective = "Begleitet den Goblinfeldmesser zu den drei Feldmessgeräten, die um den Mennarsee herum aufgestellt sind. Verteidigt ihn, während er die Geräte abliest. Ein weiterer Feldmesser kann stets über das Feldmesssignal herbeigerufen werden.", progress = "Ein Rudel toter Elfen kann den Fortschritt doch nicht aufhalten. Nicht solange ich noch was zu sagen habe!", completion = "Wundervolle Arbeit! Jetzt, wo wir die Region besser kennen, können wir uns des Sees annehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14203] = { id = 14203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchnässtes Rezept", description = "Dies scheinen die Überreste eines Rezepts für starken Wein zu sein. Vielleicht wäre der Eigentümer von Noch ein Gläschen in Dalaran daran interessiert...", sourceObjective = "Bringt das durchnässte Rezept zu Christi Stockton nach Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[14204] = { id = 14204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den Schatten", description = "Er hat sich in einen von ihnen verwandelt... nicht wahr? Wie sollen wir uns nur gegen einen Gegner behaupten, der etwas Derartiges anrichten kann?\n\nDas Arsenal meines Vaters ist bestimmt ein guter Anfang, denke ich.\n\nWorgen verbergen sich in den umliegenden Gassen. Nehmt einen meiner Mastiffs mit, um sie leichter finden zu können.\n\nWir müssen den Weg freiräumen, wenn wir diese Kanonen über Land bewegen wollen.", sourceObjective = "Besiegt 6 Blutfanglauerer.", completion = "Hervorragend. Ich werde ein paar Leute zusammentrommeln, um diese Kanonen in Position zu bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14209] = { id = 14209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Motorschaden", description = "Diese uralten Ruinen haben zehntausend Jahre Wind und Wetter überstanden. Also habe ich meine größte und beste Planierraupe dorthin geschickt, um sie dem Erdboden gleichzumachen. Ich nenne sie 'Margene'.\n\nAber meine Raupe lässt mich neuerdings im Stich, {name}. In dem Augenblick, als ich mit ihr in diese verwunschenen Wälder gefahren bin, hat Ihr Motor mit einem markerschütternden Heulen den Geist aufgegeben. Jetzt sagen mir meine Ingenieure, dass irgendetwas ihre Ventile verstopft. Geht dorthin und untersucht Margenes Motorblock und bringt mir eine Probe von dem, was auch immer ihn blockiert.", sourceObjective = "Untersucht Clubniks Planierraupe und sammelt eine Probe des Ektospritzers ein, der den Motor verklebt.", progress = "Margene ist eine Höllenmaschine, nicht wahr?", completion = "Ich glaub, mein Kugellager knirscht! Seht Euch dieses Zeug an – igitt, RIECHT mal an diesem Zeug – meine arme, arme Raupe!\n\n{name}, ich halte mich selbst für einen Klebstoffspezialisten. Ich behaupte, dieses Klebzeug ist nicht natürlichen Ursprungs. Es ist übernatürlich. Das ist Geisterklebstoff. Dafür brauchen wir mehr als nur einen Mechaniker...", sourceObjectiveStatus = "unverified-source-field" }
quests[14212] = { id = 14212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufopferung", description = "Ihr müsst das nicht tun, {name}. Ihr habt bereits mehr als genug getan.\n\nAber wenn Ihr Euch entschließen solltet, zu bleiben... Ich wäre ein Narr, Euch abzuweisen.\n\nMeine Mannen haben ihre Position in der Kathedrale befestigt und sind bereit für alles, was da kommen mag.\n\nIch werde mich nun auch dorthin aufmachen und so viele von diesen flohzersetzten Teufeln mit mir nehmen, wie ich nur kann. Seid willkommen, wenn Ihr mich zu diesem Tanz begleiten wollt.", sourceObjective = "Reitet mit Lord Darius Crowley und treibt 30 Blutfangpirscher zusammen.", completion = "Macht Euch bereit, {name}.\n\nHier kommen sie!", sourceObjectiveStatus = "unverified-source-field" }
quests[14213] = { id = 14213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Pfund Fleisch", description = "Furiens Tagebuch nach zu urteilen, wurde dieses uralte Kohlenbecken hier aufgestellt, um Opferrituale durchzuführen.\n\nSoweit Ihr das vom Eingang aus erkennen könnt, wird derjenige gesegnet, der das Fleisch von Elunes Feinden auf die brennenden Glutspäne im Kohlenbecken legt.\n\nIhr seht Euch um und beschließt, dass die Satyrn, welche die Region derzeit beherrschen, sicherlich als Feinde bezeichnet werden könnten.", sourceObjective = "Ihr müsst 10 Stücke Satyrfleisch von den zahlreichen Satyrn in Sargeron beschaffen und sie in Elunes Kohlenbecken legen.", progress = "Das Becken erwartet still eine Opfergabe.", completion = "Das göttliche Becken versieht Euch unhinterfragt mit einem Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14214] = { id = 14214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht für Graumähne", description = "Es ist so weit, {name}. Ab hier übernehmen wir.\n\nSagt König Graumähne, dass er über das Arsenal meines Vaters verfügen kann. Es beherbergt ausreichend Feuerkraft, die Worgen von hier bis zum Nordmeer zu schießen.", sourceObjective = "Sprecht mit König Graumähne im Militärviertel.", completion = "Ich wusste, dass Crowley uns helfen würde. Seine Waffen werden uns äußerst nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[14215] = { id = 14215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Erinnerung der Toten", description = "Die Runen auf diesem Ring, den Ihr gefunden habt, sind noch immer lesbar. Er wurde einer 'Kalytha' überreicht, als sie in die Akademie aufgenommen wurde. Mit ein oder zwei richtigen Zaubersprüchen ist dies das Tor zu ihrer Seele.\n\nBringt den Ring zurück zum Mennarsee. Kalythas Geist sollte jetzt für Euch sichtbar sein, wenn Ihr am Ufer des Sees steht. Berührt sie und der Ring wird es Euch ermöglichen, die Welt so zu sehen, wie sie ihr erscheint, und Ihr könnt ihre letzten Stunden miterleben. Durchforstet ihren Geist, {name}! Sprecht mit den anderen und löst das Geheimnis des Mennarsees...", sourceObjective = "Bringt Kalythas Ring zum Ufer des Mennarsees. Berührt den Geist von Kalytha, um ihre Erinnerungen noch einmal zu erleben. Sprecht mit den anderen Geistern, bis Ihr das Geheimnis des Mennarsees gelüftet habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14216] = { id = 14216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Geheimnis des Sarsensteins", description = "Bevor sie starb, bekam Kalytha die Aufgabe, etwas auf dem Grunde des Sees zu vergraben: ein mächtiges Artefakt, das die Erzmagier von Mennar in ihren letzten Minuten erschufen. Zweifelsohne wird Malynea Himmelshäscher dieses Artefakt sehen wollen, vorausgesetzt es existiert noch. Ihr beschließt den Grund des Mennarsees nach dem Sarsenstein abzusuchen.", sourceObjective = "Holt den Sarsenstein vom Grund des Mennarsees herauf.", progress = "Habt Ihr am See etwas entdeckt? Ihr seid klitschnass.", completion = "Ein Sarsenstein? Die sind eine Legende – zeigt mal her!\n\n{name}, Sarsensteine wurden verwendet, um die magischen Energien der Leylinien umzulenken. Ist Euch eigentlich klar, was das bedeutet? Die Magier von Mennar blieben nicht aus fehlgeleiteter Loyalität zurück. Sie haben Ihr Leben geopfert, um dieses Artefakt zu erschaffen. Sie versuchten damit, dem Portal Energie zu entziehen, durch das die Dämonen nach Azeroth strömten. Sie haben Zeit gewonnen, damit der Rest der Welt zurückschlagen konnte! Ihre Tat fand in den Geschichtsberichten niemals Erwähnung. Was für eine Entdeckung!", sourceObjectiveStatus = "unverified-source-field" }
quests[14217] = { id = 14217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Satyrisches Opfer", description = "Es erheitert Euch, dass dieses uralte Relikt Euch mit einem Segen ausgestattet hat, der eigentlich für Eure Feinde gedacht war.\n\nIhr seid entschlossen, so viel Nutzen wie möglich aus dieser unbeabsichtigten Gabe zu ziehen.", sourceObjective = "Ihr müsst 10 Stücke Satyrfleisch von den zahlreichen Satyrn in Sargeron beschaffen und sie in Elunes Kohlenbecken legen.", progress = "Still erwartet das Becken eine Opfergabe.", completion = "Das göttliche Becken versieht Euch unhinterfragt mit einem Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14218] = { id = 14218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit Blut und Asche", description = "Der Augenblick ist gekommen, {name}. Wenn wir ihre Zahl signifikant reduzieren wollen, müssen wir jetzt handeln.\n\nWir verfügen über die richtige Position.\n\nWir verfügen über die nötige Feuerkraft.\n\nAlles, was noch fehlt, ist der Beweis, dass wir über ausreichend Mut verfügen... und ich bin mir sicher, dass ich keinen Feigling vor mir stehen sehe.", sourceObjective = "Tötet 80 Blutfangpirscher mit den Kanonen der Rebellen.", completion = "Ihr habt Euch wohl geschlagen, {name}. Ihr habt mehr für uns getan, als von jedem Gilneer verlangt werden könnte.\n\nDie Munition geht uns aus. Wir müssen uns drinnen neu formieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[14219] = { id = 14219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen!", description = "Ihr erkennt diese Statue sofort aus den Skizzen in Furiens Tagebuch.\n\nObwohl Euch der mit dem Eintrag verbunden Text nicht gegenwärtig ist, scheint diese Zeichnung selbsterklärend zu sein. Nach der Schlacht sollten die Waffen der Feinde dem Becken dargereicht werden, um im Austausch dafür ein göttliches Geschenk zu erhalten.\n\nAls Ihr über das Ritual nachdenkt, bemerkt Ihr das Funkeln von Stahl in einem nahegelegenen Waffenregal...", sourceObjective = "Ihr sollt Euch 20 Satyrsäbel aus den Waffenregalen und von den Satyrn aus der Gegend besorgen. Dann legt sie auf die Statue von Elunes Dienstmaid.", progress = "Die Statue steht erwartungsvoll da.", completion = "Als Ihr das Ritual abgeschlossen habt, erwartet Euch eine göttliche Gabe.\n\nIhr fragt Euch unwillkürlich, was Elune davon halten würde, dass jemand wie Ihr eines ihrer Geschenke entgegennimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14220] = { id = 14220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dies ist das Ende" }
quests[14221] = { id = 14221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemals aufgeben, nur manchmal zurückziehen", description = "Wir hatten genug Munition, um den Bürgerkrieg einen weiteren Monat fortführen zu können. Aber es gibt mittlerweile derart viele Worgen, dass unsere Vorräte fast aufgebraucht sind.\n\nWir können nicht riskieren, dass dies passiert, während wir hier draußen schutzlos sind. Zieht Euch in die Kathedrale zurück und berichtet dem Boss. Bin mir sicher, der alte Crowley weiß, was wir als Nächstes tun sollten.", sourceObjective = "Sprecht mit Darius Crowley in der Kathedrale des Erwachenden Lichts.", completion = "Wir haben ihnen alles entgegengeworfen, was wir haben... aber sie kommen noch immer. Sorgt Euch nicht, {name}, wir werden noch viel mehr von ihnen über den Jordan schicken, bevor der Tag vorbei ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[14222] = { id = 14222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Gefecht", description = "Das hier ist ein perfekter Engpass, {name}. Sprecht ruhig ein Gebet, wenn dergleichen Euch liegt.\n\nNehmt Euren Mut zusammen und dann lasst uns diese Köter vernichten!", sourceObjective = "Tötet 8 rasende Pirscher.", progress = "Wir können es schaffen, {name}.", completion = "Es... Es kommen keine weiteren.\n\nNein, {name}. Das verheißt nichts Gutes.", sourceObjectiveStatus = "unverified-source-field" }
quests[14223] = { id = 14223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenfrieden", description = "Unser Lager hat die Aufgabe, mögliche Widersacher zu beobachten. Sobald die Horde ihren Desolace-Feldzug startet, wird unsere Arbeit hier uns vor bösen Überraschungen schützen.\n\nKürzlich wurde einer unserer Späher gefangen genommen und von der Brennenden Klinge in ihrem Stützpunkt im Osten geopfert. Seitdem werden wir von einem Schuft der Brennenden Klinge bedroht und gepiesackt. Sein Name ist Kohor.\n\nIhre Tage sind gezählt, aber ich werde denjenigen großzügig belohnen, der ihn jetzt zum Schweigen bringt!", sourceObjective = "Sorrem in Furions Posten will, dass Ihr Kohor tötet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14225] = { id = 14225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr erkennt es, wenn Ihr es seht", description = "Mit seinen letzten Atemzügen erwähnte Kohor die Beschwörung eines Dämons, der das gesamte Gebiet bedrohen könnte.\n\nVielleicht war das ein Täuschungsversuch, aber das Risiko kann nicht eingegangen werden.\n\nDies kann nicht bis zum Einfall der Horde in Desolace warten. Ihr müsst die Festung Donneraxt nach Hinweisen durchsuchen und dieser möglichen Gefahr ein Ende setzen.", sourceObjective = "Sorrem in Furions Posten will, dass Ihr das uralte Beschwörungsritual in Festung Donneraxt findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14226] = { id = 14226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger unter den Füßen", description = "Seht Euch an. Ihr unternehmt Botengänge. Sehr verantwortungsvoll von Euch. Ihr steigt hinauf, Ihr steigt auf... auf, auf!\n\nDämonen voraus! Viele, unerfreuliche Dämonen. Dämonen, denen Eure Innereien wohl gefallen würden! Legashidämonen in südöstlicher Richtung! Aber seid unbesorgt. Nein, nein. Es gibt keinen Grund zur Sorge, denn ich werde Euch einen Begleiter zur Seite stellen!\n\nSpitz, grausam, zerquetschend. Zielt, verkäfert, zerquetscht! Sehr leistungsfähig. Und auch sehr schmutzig... aber noch einmal: Seid unbesorgt. Nein, nein. Seid unbesorgt. Denn wir müssen zum Glück anschließend nicht saubermachen!", sourceObjective = "Verwendet Euren persönlichen arkanen Assistenten, um 12 Legashidämonen in Insekten zu verwandeln und sie zu zerquetschen.", completion = "<Erzmagier Xylem scheint eine Art Tanz aufzuführen, als er sich Euch zuwendet.>\n\nMacht Euch keine Sorgen und achtet darauf, dass der Käfersaft nicht antrocknet, oder Ihr werdet es bereuen. Eure Stiefel würden ziemlich stinken! Es würde heute nicht gut riechen und morgen würde es noch weniger gut riechen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14227] = { id = 14227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Köpfe zusammenstecken", description = "Es stimmt also...\n\nDas Pergament, das Ihr in der Festung Donneraxt gefunden habt, beschreibt ein mächtiges Beschwörungsritual. Eines das stärker ist als alle anderen, von denen wir wissen, dass die Brennende Klinge sie besitzt.\n\nDieses Ritual muss selbstverständlich unterbrochen werden, koste es, was es wolle!\n\nWenn diese Dämonen vorzeitig beschworen würden, könnte die Krise abgewendet werden.", sourceObjective = "Sammelt 100 gebleichte Schädel aus der Festung Donneraxt, stapelt sie auf dem Beschwörungszirkel der Brennenden Klinge auf und tötet dann Nazargen.", completion = "Ihr habt eine schlimme Krise abwenden können, {class}.\n\nWenn diese Beschwörung noch ein wenig länger hinausgezögert worden wäre, wäre der Dämon viel zu mächtig für unsere kleine Streitmacht geworden.\n\nBitte nehmt dieses Geschenk zum Dank für Eure Dienste an.", sourceObjectiveStatus = "unverified-source-field" }
quests[14230] = { id = 14230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handbucharbeit", description = "Die hiesigen Dämonen scheinen Spaß daran zu haben, all unsere arkanen Handbücher zu stehlen. Ich möchte doch stark bezweifeln, dass die meisten von ihnen überhaupt lesen können, also tun sie dies nur aus reiner Bosheit.\n\nDie meisten dieser Bücher interessieren mich herzlich wenig, aber sie haben ein Bannzaubererhandbuch gestohlen, das ich auf alle Fälle brauchen werde, wenn ich Lehrlinge wie Euch während Xylems 'Prüfungen' am Leben erhalten will. Findet die Dämonen im Lager der Legashi im Südosten und gelangt in den Besitz des Handbuchs des Abschwörers.\n\nDas ist alles. Schwirrt ab.", sourceObjective = "Besorgt Euch das Handbuch des Abschwörers aus dem Lager der Legashi.", progress = "Da seid Ihr ja... schon wieder... und sprecht mit mir. Ich nehme an, das bedeutet, Ihr habt mein Buch?", completion = "Spitze! Na, dann zurück an die Arbeit.\n\nDanke, Schätzchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14231] = { id = 14231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Useless quest record" }
quests[14232] = { id = 14232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Satz heiße Ohren", description = "Sorrem hat kein Geheimnis aus seiner Verachtung gegenüber der Brennenden Klinge in Festung Donneraxt gemacht.\n\nSicherlich würde ein Beweis ihres Dahinscheidens für ihn von großem Wert sein.", sourceObjective = "Bringt die Ohren von 25 Brennenden Klingen zu Sorrem in Furions Posten.", progress = "Was habt Ihr da, {class}?", completion = "Ohren der Brennenden Klinge?\n\n<Sorrem lächelt.>\n\nGute Arbeit, {class}. Dies ist nur eine Vorahnung von dem, was aus dem gesamten, ekelhaften Kult wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[14233] = { id = 14233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orcs können schreiben?", description = "Ihr durchwühlt die Habseligkeiten des toten Orcs und findet ein Feldtagebuch. Obwohl es vom Wasser schwer beschädigt wurde, ist die Schrift noch lesbar, wenn auch nur schlecht.\n\nIhr blättert durch die Seiten und entdeckt eine interessante Geschichte. Was für ein Glück, dass Ihr Orcisch beherrscht!\n\nWie die Yacht des Handelsprinzen wurden auch die Orcs von Kriegsschiffen der Allianz angegriffen. Ihr erinnert Euch, dass Ihr ein orcisches Kriegsschiff habt vorbeiziehen sehen, kurz bevor die Allianz das Feuer eröffnet hat. Vielleicht haben sie ja auf die Orcs statt auf Euch geschossen?\n\nDumme Orcs! Wegen ihnen seid Ihr untergegangen!", sourceObjective = "Bringt das Feldtagebuch zu Sassy Hartzang an der Schiffbruchküste auf den Verlorenen Inseln zurück.", progress = "{name}, konntet Ihr etwas Interessantes in der Höhle finden?", completion = "Orcs?! Sie wurden auch versenkt und sind gestrandet? Und jetzt ist die Allianz auf der Insel? Meint Ihr, sie werden uns töten?\n\n<Sassy sieht nachdenklich aus.>\n\nIch glaube, wir sollten uns mal mit diesen Orcs unterhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14234] = { id = 14234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind meines Feindes", description = "Ich schäme mich, das von Euch zu verlangen, aber ich schätze, dafür bezahlt man Euch so viel Gold. Könntet Ihr das Feldtagebuch dieses toten Orcs zum Befehlshaber ihres Lagers bringen?\n\nLaut dem Feldtagebuch sollte es sich oben auf der Insel am Hang hinter der Kaja'mithöhle im Südosten befinden.\n\nViel Glück, {name}. Ich habe Euch immer gemocht.", sourceObjective = "Bringt das Feldtagebuch zu Aggra im Basislager der Horde auf den Verlorenen Inseln.", progress = "<Die Orcdame betrachtet Euch mit zusammengekniffenen Augen.>\n\nIhr müsst auf dem Sklavenschiff der Goblins gewesen sein, das versenkt wurde. Was habt Ihr da in der Hand?", completion = "<Die Orcdame versucht, nach dem Feldtagebuch zu greifen, unterbricht dann aber ihre Bewegung und seufzt tief.>\n\nEs tut mir leid. Wir haben alle ein paar harte Tage hinter uns.\n\nIch bin Aggra. Was Ihr hier seht, ist der klägliche Rest der Besatzung der Drakas Furor.\n\nVielleicht können wir ja zusammenarbeiten. Schließlich haben wir in der Allianz einen gemeinsamen Feind. Die Assassinen des SI:7 sind überall auf der Insel verstreut und werden keine Ruhe geben, bis wir alle tot sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[14235] = { id = 14235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kleine Horrortal", description = "Unser Jäger, Kilag Blutmaul, ist mit ein paar Spähern den Weg nach Westen entlang gereist. Sie… suchen nach… \"wertvoller Fracht\"… auf die wir aufgepasst haben, als die abscheuliche Allianz unser Schiff versenkt hat.\n\nDer Weg dorthin wird von tödlichen Pflanzen blockiert, sodass sie nicht durchdringen konnten.\n\n{name}, beweist Euren Wert als Goblin und {class}. Reist in das Kleine Horrortal und findet Kilag.", sourceObjective = "Findet Kilag Blutmaul im Kleinen Horrortal auf den Verlorenen Inseln.", completion = "{race}, könnt Ihr kämpfen?\n\nUm Euretwillen hoffe ich es einfach mal. Ansonsten gibt es keinen Weg durch diese Hölle aus Todespflanzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14236] = { id = 14236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unkrautvernichter", description = "<Kilag bleibt zwischen den Gewehrschüssen kaum Zeit, Euch zu beachten, doch sein Blick bleibt einen Moment lang bewundernd auf Eurem goblinischen Alles-in-1-zigartigem Gürtel ruhen.>\n\nJetzt sind kreative Lösungen gefragt. Zieht etwas aus diesem Gürtel und macht Euch an die Arbeit!\n\n<Ihr denkt kurz über die Situation nach. Dann fällt Euch etwas ein, was gerade verrückt genug ist, um funktionieren zu können!>", sourceObjective = "Benutzt den Unkrautvernichter Eures goblinischen Alles-in-1-zigartigen Gürtels, um 100 Pflanzen im Kleinen Horrortal niederzumähen.", progress = "Es sind immer noch zu viele. Wir kommen nicht durch.\n\nHabt Vertrauen in Euch selbst, {name}. Lasst Euer wahres Kriegerherz erstrahlen.", completion = "Ich habe es mit eigenen Augen gesehen und kann es immer noch nicht glauben!\n\nIhr habt unseren Dank. Wir schulden Euch unser Leben, kleiner {race}. Ich hoffe, dass wir Euch diese Ehre bald zurückzahlen können.\n\nDarf ich Euch um einen kleinen Gefallen bitten, während ich mit meinen Spähern weiterziehe?", sourceObjectiveStatus = "unverified-source-field" }
quests[14237] = { id = 14237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorrücken", description = "Kilag sollte jetzt in Position sein. Es wird Zeit, dass Ihr zur Wilden Aussicht vorrückt. Der Rest von uns packt hier zusammen und kommt bald nach.\n\nFolgt einfach dem Pfad nach Nordwesten durch das Kleine Horrortal. Dank Euch hält sich der Horror dort ja jetzt in Grenzen, hm?\n\nKilag und seine Späher verstecken sich am Wegesrand, aber die Assassinen des SI:7 werden sie sicher bald entdecken. Ihr solltet Euch also beeilen!", sourceObjective = "Findet Kilag Blutmaul und seine Späher an der Wilden Aussicht auf den Verlorenen Inseln.", completion = "Throm-Ka, {name}. Wir haben ein Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[14238] = { id = 14238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infrarot = Infratot", description = "Seid leise! Im Tal nördlich und westlich von hier wimmelt es nur so von Assassinen der Allianz.\n\nLeider konnten wir sie noch nicht entdecken. Diese Feiglinge! Sie verstecken sich lieber, als von Angesicht zu Angesicht zu kämpfen.\n\nIhr Goblins seid doch für Eure wunderlichen Brillen bekannt. Habt Ihr nicht eine, mit der Ihr sie sehen könnt?\n\nIhr müsst Euch mit einem meiner Späher zusammentun und alle Assassinen des SI:7 töten, die Ihr entdecken könnt.", sourceObjective = "Tötet 10 Assassinen des SI:7.\n\nWenn Eurem orcischen Späher etwas zustößt, kehrt zu Kilag zurück und schaut, ob er einen anderen Partner für Euch hat.", completion = "Gut gemacht, {name}, sehr gut. Vielleicht wird aus Euch doch noch ein Orc!\n\nEs ist Zeit, weiterzuziehen. Wir sollten uns sputen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14239] = { id = 14239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geht nicht ins Licht!", sourceObjective = "Es liegt jetzt an Euch. Kehrt Ihr zurück ins Leben und seid der Held, den die restlichen Überlebenden so dringend brauchen, oder bleibt Ihr bis in alle Ewigkeit hier?\n\nNur Ihr könnt das entscheiden.\n\nGeht nicht ins Licht, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[14240] = { id = 14240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Klippen", description = "Ich habe Späher Brax die Straße weiter zu den Klippen geschickt, die den Strand im Westen überragen.\n\nIch werde Euch auf Bastia setzen. Reist den Pfad entlang und teilt Brax mit, dass wir einen anderen Weg nehmen.\n\nWir treffen uns beim Angriff an der Landespitze der Allianz!", sourceObjective = "Sprecht mit Späher Brax am Pfad entlang der Klippen nördlich der Wilden Schlucht auf den Verlorenen Inseln.", completion = "Hallo, kleiner {race}. Bastia ist ganz schön schnell, was?\n\nWir haben wichtige Dinge zu erledigen. Helft Ihr uns?", sourceObjectiveStatus = "unverified-source-field" }
quests[14241] = { id = 14241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zum Gyroschrauber!", description = "Die Allianz hat der Horde etwas von größter Wichtigkeit gestohlen. Sie bewahren es auf ihren Schiffen auf.\n\nAm anderen Ende des Strands findet Ihr einen Gyroschrauber. Unsere Kriegshetzer geben Euch auf dem Weg dorthin Deckung.\n\nFliegt zu ihrem Flaggschiff, der Sog der Vergeltung, und holt unsere wertvolle Fracht zurück!", sourceObjective = "Besorgt Euch die Gyroschrauberschlüssel.", progress = "Hm, sieht nach überkomplizierter gnomischer Ingenieurskunst mit vielen unnötigen Instrumenten und Sicherheitsmaßnahmen aus.", completion = "Wo zum Teufel ist die Zündung?\n\nMich würde nicht wundern, wenn dieses Ding beim Fliegen etwas Komisches macht, zum Beispiel sich in ein Hühnchen verwandelt oder auf Ameisengröße zusammenschrumpft.\n\nHe, schaut! Da hat jemand etwas Kleingeld im Aschenbecher vergessen! Was hier wohl sonst noch so herumliegt?", sourceObjectiveStatus = "unverified-source-field" }
quests[14242] = { id = 14242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wertvolle Fracht", description = "Sie sagten, dass ihre \"wertvolle Fracht\" auf dem Allianzschiff, der Sog der Vergeltung, aufbewahrt würde, was auch immer das für eine Fracht sein mag.\n\nEs gibt nur eins zu tun… Fliegt mit diesem Ding dorthin und holt sie Euch zurück!", sourceObjective = "Findet die wertvolle Fracht unter Deck des Allianzschiffs \"Sog der Vergeltung\" am Strand der Verlorenen Inseln.", progress = "Vielleicht könntet Ihr mir helfen, aus diesem arkanen Käfig zu kommen?", completion = "Wenn Ihr nicht wärt, würde man mich jetzt sicher nach Sturmwind bringen und als Trophäe und Sklave in der Stadt präsentieren.\n\nDiese Hunde der Allianz haben mich bewusstlos am Strand gefunden und in diesen magischen Käfig gesteckt. Er hat mich davon abgehalten, eine Verbindung zu den Elementen aufzubauen.\n\nAber das ist jetzt vorbei!", sourceObjectiveStatus = "unverified-source-field" }
quests[14243] = { id = 14243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache des Kriegshäuptlings", description = "Brüder der Erde und des Feuers, hört mich an! Schwestern des Wassers und der Luft, folgt meinem Ruf!\n\nAzeroth steht an der Schwelle der Zerstörung! Unser aller Leben ist in Gefahr! Leiht mir Eure Macht, wie Ihr sie einst meinen Vorfahren geliehen habt. Macht dieses Kind von Kezan zum Instrument Eures Willens.\n\nSetzen wir denen ein Ende, die uns daran hindern wollen, die Welt zu heilen!", sourceObjective = "Benutzt die Macht des Zyklons der Elemente, um 50 Matrosen der Allianz zu töten.\n\nSobald Ihr Eure Aufgabe erledigt habt, werdet Ihr zur Wilden Aussicht geflogen.", completion = "Ihr habt geschafft, was nur wenige hätten schaffen können, {name}. Unsere Welt steht tiefer in Eurer Schuld, als Ihr es je begreifen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14244] = { id = 14244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf, auf und davon!", description = "Während Ihr den Kriegshäuptling gerettet und uns alle vor der Allianz bewahrt habt, hat Vorarbeiter Feuchtlunte diese Raketenschleuder gebaut, um uns über die von Haien verseuchte Meerenge auf die größere Insel zu katapultieren.\n\nZu unserem Glück konnte der Vorarbeiter eine Instastadt aus dem Schiffswrack retten. Sobald Ihr sie aufbaut, haben wir endlich wieder eine eigene Stadt. Ich kann es kaum erwarten, wieder in einem Bett zu schlafen!\n\nFeuchtlunte hält sich dort unten am Landeplatz auf und erwartet Euch. Warum nehmt Ihr nicht gleich die nächste Rakete?", sourceObjective = "Überlebt den Schuss mit der Raketenschleuder über die Bedrängnis.", completion = "{name}, ich bin so froh, dass Ihr die Reise gut überstanden habt… Leider kann man das nicht von allen behaupten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14245] = { id = 14245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stadt in der Kiste", description = "Der Handelsprinz hatte im Frachtraum des Schiffes eine ganze Stadt in einer Kiste! Ich konnte die Kiste an mich bringen, während Ihr uns da draußen die Haut gerettet habt.\n\nWürdet Ihr mir die Ehre erweisen? Klettert einfach auf diesen riesigen Sprengstoffberg, drückt den Auslöser und Abrakablam! Ihr seid in Instastadt.", sourceObjective = "Klettert auf den Sprengstoffberg und benutzt den Auslöser von Instastadt.", completion = "<hust, hust>\n\nHe! Wo sind die Docks? Jemand hat die Docks und die Raffinerie aus unserer Instastadt gestohlen!\n\nWer würde denn so etwas tun?\n\nWo ist dieser Handelsprinz?", sourceObjectiveStatus = "unverified-source-field" }
quests[14246] = { id = 14246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwangsadoption", description = "Während diese Region immer üppiger und grüner wird, werden die Wüstenkreaturen auf immer begrenzterem Raum zusammengedrängt.\n\nBesonders besorgniserregend ist das fortschreitende Aussterben der einheimischen Sturzflieger. Während der Nistzeit tun sich die Raubtiere an den Vögeln und ihren Eiern gütlich.\n\nIch habe ein paar Sturzflieger-Eier aus Tanaris besorgt und sie mit einem unwiderstehlichen Lockstoff benetzt. Legt ein Ei in jedes Nest, das Ihr findet könnt, und beschützt es, bis ein Sturzflieger kommt und es davonträgt.\n\nIhr werdet damit dem natürlichen Gleichgewicht dieses Landes einen großen Dienst erweisen.", sourceObjective = "Legt 3 Sturzflieger-Eier in die Nester von Sturzfliegern und beschützt sie, bis sie eingesammelt wurden.", completion = "Ihr habt gute Arbeit geleistet, {class}.\n\nDieses Land steht in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[14247] = { id = 14247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raues Land", description = "Ich wurde vom Zirkel des Cenarius offiziell beauftragt, dieses raue Land in eine saftige Prärie zu verwandeln.\n\nDie Länder südlich von hier sprießen bereits, aber hier kämpft irgendetwas dagegen an und widersteht dem Wachstum.\n\nVielleicht können Eure Augen ausfindig machen, was meinen verschlossen bleibt.\n\nBitte, {race}. Durchkämmt diese Länder und findet den Ursprung für die Sturheit der Wüste.", sourceObjective = "Thunk in Thunks Heimstatt will, dass Ihr die unnatürliche Felszunge findet.", completion = "Ihr seht Euch um und sucht den Horizont nach etwas ab, das diesen Felsstein hier platziert haben könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[14248] = { id = 14248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hilfe gesucht", description = "Tolle Neuigkeiten! Vorarbeiter Feuchtlunte hat auf der Insel eine ganze Höhle voller Kaja'mit entdeckt! Wer hätte das gedacht?\n\nNatürlich hat die Sache einen kleinen Haken. Er hat ein paar Überlebende mitgenommen, um ihm beim Abbau des Erzes zu helfen, aber keiner von ihnen ist wieder aus der Mine herausgekommen.\n\nSo verrückt es klingt, aber der Vorarbeiter sagt, dass es in der Höhle Affen gibt... mit Spitzhacken! Sie bauen das Kaja'mit ab! Wie ist das überhaupt möglich?\n\nKönntet Ihr nach Südosten zur Höhle gehen? Der Vorarbeiter steht direkt an ihrem Eingang.", sourceObjective = "Sprecht mit Vorarbeiter Feuchtlunte außerhalb der Kaja'mithöhle auf den Verlorenen Inseln.", completion = "Boss! Äh, ja, ich schätze, Ihr seid nicht mehr der Boss. Aber es ist trotzdem schön, Euch zu sehen!\n\nKönnt Ihr das glauben? Eine Höhle voller intelligenter Killeraffen, die Kaja'mit abbauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14249] = { id = 14249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Federgewichtig", description = "Ich wäre super! In Erzmagie. Der Hit! Er würde nicht mal mit mir sprechen, denn ich habe keine so dämliche Robe und keinen Hut. Pffft.\n\nDer fantastischste Erzmagier, den dieses Land jemals gesehen hat, kann nicht einfach eine Robe und einen Hut haben. Ich muss ihm zeigen, dass ich etwas ganz Besonderes bin und ich weiß auch schon genau, wie ich das mache.\n\nGeht hinaus und tötet mir ein paar dieser Hippogryphen. Bringt mir eine TONNE ihrer Federn.\n\nIhr habt mich verstanden! Eine Riesenmenge Federn! Geht, geht. Ich werde die Robe fertig haben, wenn Ihr zurück seid.", sourceObjective = "Besorgt 80 makellose Donnerkopffedern von den Hippogryphen in der Nähe der Ruinen von Nordressa.", progress = "Meine Robe sieht ziemlich schick aus. Habt Ihr die Federn dabei?", completion = "Haha! Perfekt! Lasst mich das alles schnell zusammennähen. Der Erzmagier wird von meinem Auftritt sicher überwältigt sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[14250] = { id = 14250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erneuerbare Ressourcen", description = "Wir brauchen noch mehr belebten Basalt. Dafür gibt es nur eine zuverlässige Quelle in diesem Gebiet: ein Bergriese namens Balboa. Wir können den Bergriesen nicht töten, wenn wir langfristig was von dem Zeug haben wollen, also schlagen wir immer nur kleinere Teile auf einmal ab.\n\nIhr werdet in der Lage sein, seinen Weg nordöstlich und östlich von hier zu erkennen. Findet ihn, legt den Sprengsatz vor ihm auf den Pfad und dann versteckt Euch, bis er explodiert. Sobald er das Gebiet verlassen hat, solltet Ihr den Basalt an Euch nehmen können und ihn zu mir bringen.", sourceObjective = "Verwendet die Arkane Aufladung, um 5 Stück belebtes Basalt von Balboa in der Nähe der Ruinen von Nordressa zu erlangen.", progress = "Ich habe ein paar Explosionen gehört. Ich kann nur schwer sagen, ob eine von ihnen von Euch war oder nicht... Diese Goblins können eine ziemliche Plage sein.", completion = "Gute Arbeit. Das gibt uns noch ein paar Stunden, bevor wir wieder zu ihm müssen, um uns mehr zu holen.\n\nEr scheint nicht gerade der hellste Riese zu sein. Ich gehe davon aus, dass wir das noch eine Zeitlang machen können, bevor er es kapiert.", sourceObjectiveStatus = "unverified-source-field" }
quests[14251] = { id = 14251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mal von vorne", description = "So weit im Norden bestand bisher nie die Gefahr eines Zentaurenangriffs. Irgendjemand hat sie aufgehetzt. Ich weiß es einfach!\n\nAber davon abgesehen bin ich am Ende. Ich habe alles in diese Ladung investiert.\n\nGlücklicherweise gibt es etwas, das mir kein Zentaur nehmen kann, und das ist meine goblinische Genialität! Ich fange noch einmal ganz von vorne an und errichte ein Imperium!\n\n<Bizby macht in einiger Entfernung einen Skorpion aus.>\n\nEs gibt immer einen Markt für Gift. Was sagt Ihr?", sourceObjective = "Sammelt 15 Skorpionenstachel.", progress = "Werfen wir doch mal einen Blick auf diese Skorpionenschwänze.", completion = "So habe ich angefangen, müsst Ihr wissen.\n\nGift an die Schurken in Orgrimmar vertickt. Ach, das waren noch Zeiten...", sourceObjectiveStatus = "unverified-source-field" }
quests[14252] = { id = 14252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gutes Gold für schlechte Schwänze", description = "Ich brauche haufenweise Schwänze, {class}! Und nicht irgendwelche Schwänze. Die Schwänze, die ich brauche, müssen alt sein - uralt sogar. Je oller je doller.\n\nDie Schuppen eines Basiliskenschwanzes sind einzigartig, denn sie werden mit den Jahren immer härter, ohne spröde zu werden. Die gehärteten Schuppen sind ideal für die Herstellung bestimmter Rüstungen.\n\nEs ist viele Jahre her, dass ich darauf angewiesen war, Eidechsenschuppen zu verkloppen, aber wer weiß, vielleicht stärkt es ja meinen Charakter! Falls das überhaupt noch möglich ist...", sourceObjective = "Findet 15 alte Basiliskenschwänze.", progress = "Wie läuft die Suche nach den Basiliskenschwänzen, {name}?", completion = "Das wird reichen, {class}.\n\nNoch mehr so Freunde wie Ihr, und ich bin in nullkommanix wieder auf den Beinen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14253] = { id = 14253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befiederung", description = "Sagt, {class}, während Ihr unterwegs seid und die Ödnis der Wüste erforscht, könnt Ihr mir einen Gefallen tun?\n\nHaltet Ausschau nach Schreckenssturzfliegern. Ihre öligen Federn sind für die Befiederung von Pfeilen bestens geeignet und bei den richtigen Käufern bringen sie ein hübsches Sümmchen ein.\n\nZum Glück für Euch kenne ich alle richtigen Käufer!", sourceObjective = "Sammelt 25 Federn von Schreckenssturzfliegern.", progress = "Wie läuft die Suche nach den Sturzfliegern?", completion = "Nun gut, das sind reichlich Federn, {class}.\n\nDie werden ein gutes Kissen abgeben, bis ich sie morgen zum Markt schaffe!", sourceObjectiveStatus = "unverified-source-field" }
quests[14254] = { id = 14254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwermetall", description = "Ihr habt das starke Gefühl, dass dieser Stein irgendwie dafür verantwortlich ist, dass diese Region sich gegen die Wiederbegrünung wehrt.\n\nIhr seht in Richtung Westen und bemerkt dort Anzeichen von schwelenden Trümmern, die auf rätselhafte Weise damit in Verbindung zu stehen scheinen.\n\nIhr vermutet, dass die Entfernung der Trümmer Thunks Bemühungen entgegenkommen würde.\n\nUnd wer weiß, wofür das Zeug gut sein könnte?", sourceObjective = "Ihr sollt 7 Stück Element 116 einsammeln und sie zu Bizby in Bizbys Karawane bringen.", progress = "Was habt Ihr da, {class}?", completion = "Was ist das?\n\n<Bizby untersucht das Erz.>\n\nWahnsinn! Ich kenne jemanden, der größtes Interesse daran haben wird, diese Proben in die Finger zu bekommen.\n\nUnd er würde auch äußerst großzügig dafür zahlen. Darauf wette ich.\n\nHier, {class}. Nehmt dies als Finderlohn.", sourceObjectiveStatus = "unverified-source-field" }
quests[14255] = { id = 14255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ethel Rethor", description = "Wir haben zahlreiche Feinde in dieser Region, auch ohne dass wir den Zorn des Zirkels des Cenarius auf uns ziehen.\n\nAls wir diesen Posten hier aufgebaut haben, wurden wir gebeten, eine ihrer Forscherinnen im Auge zu behalten.\n\nKorrah wurde zuletzt am Turm im Westen gesehen. Seid so lieb und stattet ihr einen Besuch ab. Es ist schon etwas länger her, seit wir uns die Mühe gemacht habe, nach ihr zu sehen.", sourceObjective = "Cerelia in Furions Posten will, dass Ihr mit Korrah in Ethel Rethor sprecht.", completion = "Es ist gut, dass Ihr gekommen seid.\n\nHier lauert eine große Gefahr.", sourceObjectiveStatus = "unverified-source-field" }
quests[14256] = { id = 14256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wachsende Bedrohung", description = "Außer mir ist niemand von meiner Gruppe übrig geblieben, die hierher entsendet wurde, um die zahlreichen Veränderungen an dieser Küste von Desolace zu beobachten.\n\nIch habe Bericht von der dramatischen Zunahme der Naga erstattet, aber ohne Reaktion.\n\nMeine Mitstreiter konzentrieren sich auf die anderen Krisenherde. Deshalb muss ich Euch, <einen Fremden/eine Fremde>, bitten, mich bei meinen Forschungen zu unterstützen.\n\nZunächst gestattet mir jedoch, dass ich Euch die Bedrohung zeige, der wir gegenüberstehen.", sourceObjective = "Korrah will, dass Ihr mit ihr sprecht, wenn Ihr bereit seid, die Bedrohung durch die Naga näher zu besehen.", completion = "Jetzt versteht Ihr. Dies ist keine einfache Bande von verdrängten Naga, sondern eine gut organisierte Armee, die in der Lage ist, große Zerstörung zu verursachen.\n\nWilligt Ihr ein, mich bei meinen Untersuchungen zu unterstützen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14257] = { id = 14257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zackenkämme getötet", description = "Wieder und wieder erweisen sich die Naga als Feinde des natürlichen Gleichgewichts. Ich habe keinerlei Bedenken, Ihr Blut zu vergießen.\n\nEure größten Bemühungen können ihren Kräften jedoch kaum einen nennenswerten Schaden zufügen. Wo einer fällt, scheinen zwei an seine Stelle zu treten.\n\nIch habe einen Plan, {class}! Euer Ziel soll es nicht mehr nur sein, die Feinde zu töten, sondern Ihr sollt Teile ihres Körpers sammeln, die für den nächsten Schritt unserer Forschung vonnöten sind...", sourceObjective = "Sammelt 10 Zackenkammknochen von Naga der Zackenkämme, 30 Zackenkammschuppen von Zauberinnen der Zackenkämme und 4 Zackenkammflossen von Kriegern der Zackenkämme.", progress = "Habt Ihr die Teile gesammelt, die ich benötige?", completion = "Ihr habt gute Arbeit geleistet, {class}. Aber leider ist diese Arbeit erst der Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[14258] = { id = 14258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mörsermunition", description = "Die Naga sind auf diese Halbinsel vorgerückt, nachdem wir die Endhaltestelle der Raketenbahn fertiggestellt hatten. Aber es gibt kein Problem auf dieser Welt, das sich nicht mit genügend Feuerkraft lösen ließe! Mein Vater hat das immer gesagt. Vor dem Unfall.\n\nMeine Vorräte werden allerdings knapp. Tut mir einen Gefallen und sammelt die Mörsergranaten ein, die ich im Geheimlabor westlich von hier gelagert habe. Wenn Ihr reichlich neue liefert, dann lasse ich Euch selbst die Abschussbefehle für die Artillerie geben!", sourceObjective = "Holt 5 Goblinmörsergranaten aus dem Geheimlaborkomplex in Azshara.", progress = "Ich hoffe, Ihr habt Munition für mich. Meine einzige Waffe ist zurzeit mein loses Mundwerk.", completion = "Schön! Wundervoll! Hervorragend! Ihr seid granatenstark!\n\nDa meine Mörser wieder bestückt sind, kann ich Euch mit ihnen unterstützen, wenn Ihr die Naga östlich von hier angreift. Verwendet diese Markierungen irgendwo an den Klippen, um Artillerieschläge anzufordern, und ich bade das gesamte Gebiet in feuriges Auaweh. Oh, du köstliche, gnadenlose, willkürliche Zerstörung! Ich hoffe, Ihr seid gut gepanzert...", sourceObjectiveStatus = "unverified-source-field" }
quests[14259] = { id = 14259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Mörser, mehr!", description = "Danke, dass Ihr mir beim Auffüllen meiner Vorräte geholfen habt, {name}. \n\nWisst Ihr was - wenn Ihr mir Mörser aus dem Labor bringt, kann ich Euch weiterhin mit Signalen für die Artillerie versorgen. Ich von hier aus und ihr von unten aus können wir die Klippen sprengen, bis sie ins Meer fallen!", sourceObjective = "Sammelt 5 Goblinmörsergranaten aus dem Geheimlabor in Azshara.", sourceObjectiveStatus = "unverified-source-field" }
quests[14260] = { id = 14260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Tiefe gehen", description = "Ich habe einen Glücksbringer erstellt, der es Euch ermöglicht, Euch bei den Naga einzuschleusen. Er gibt Euch das Erscheinungsbild eines der ihrigen.\n\nMithilfe dieser Tarnung werdet Ihr in der Lage sein, ihre Sprache zu sprechen und zu verstehen. Sie werden nicht in der Lage sein, Eure wahre Identität zu erkennen.\n\nAber seht Euch vor! Die Haie und andere Meereswesen hier werden Euch für alle sichtbar machen. Meidet sie um jeden Preis.\n\nNun geht. Sprecht mit der Priesterin von Azshara und tut, was getan werden muss, um herauszufinden, warum sie hier sind.", sourceObjective = "Benutzt den Zackenkammglücksbringer.", completion = "Steht nicht einfach so herum, wenn es so viel zu tun gibt!\n\nMuss ich denn jedem jede Kleinigkeit erklären?", sourceObjectiveStatus = "unverified-source-field" }
quests[14261] = { id = 14261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiskalt", description = "Ich habe die perfekte Lösung für Euer Drachenproblem. Meine ganz persönlicher Kryomat 16.\n\nIch habe ihn ursprünglich entwickelt, um meine Arbeiter während des Transports und zwischen den Schichten einzufrieren. Denn dann muss ich sie nicht füttern oder unterhalten. Aber es gab... Komplikationen. Sie ist aber auch perfekt dafür geeignet, diese Drachen vom Himmel zu holen!", sourceObjective = "Verwendet den Kryomat 16, um 8 finstere Drachen einzufrieren und zu töten.", completion = "Was? Ihr habt die Drachenteile gar nicht mitgebracht? Wie enttäuschend.\n\nIch wusste, ich hätte Euch einen Vertrag unterschreiben lassen müssen, bevor ich Euch losschickte...", sourceObjectiveStatus = "unverified-source-field" }
quests[14262] = { id = 14262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man einen Fisch ausnimmt", description = "Es stellt meine Geduld auf die Probe, Kreaturen abzuwehren, die jederzeit im Meer verschwinden können und wieder auftauchen, wo es ihnen beliebt. Aber ich werde mich nicht geschlagen geben, bis sie allesamt von Azsharas Antlitz gefegt sind.\n\nNaga der Grollflossen haben die Klippen erklommen und belagern uns nun von Osten her. Vernichtet sie, {name}. Nehmt sie aus vom Schwanz bis zum Kopf, sodass sie den wahren Zorn meiner Horde zu spüren bekommen.", sourceObjective = "Tötet 6 Sturmwute der Grollflossen und 6 Seeruferinnen der Grollflossen.", completion = "<Torg sucht den Horizont ab.> Trotzdem kommen immer mehr! Sie sind wie eine Plage, {name}. Aber mithilfe Eurer Kraft werden wir sie zermalmen. Eines Tages.", sourceObjectiveStatus = "unverified-source-field" }
quests[14263] = { id = 14263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fidele Kräuter", description = "Lebendiger Zornthymian. Ich brauche mehr davon! Beeilt Euch, schnell!", sourceObjective = "Sammelt 8 Bündel Lebendigen Zornthymian in der Nähe der Ruinen von Nordressa.", progress = "Habt Ihr den Thymian bekommen?", completion = "Perfekt. Es ist ganz interessant, als wie nützlich sich die unscheinbarsten Dinge für eine Beschwörung dieser Art erweisen.\n\nEs gibt noch so viel zu entdecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[14264] = { id = 14264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nasser als Nass", description = "Neptulons Schergen haben diesen Ort erreicht und tun alles, um unsere Pläne zu durchkreuzen. Offensichtlich haben sie unsere Beweggründe herausgefunden.\n\nDas bestätigt nur meinen Verdacht, dass sich das, was wir suchen, tatsächlich in diesen Ruinen verbirgt!\n\nDiese Wasserelementare können sich nicht mit unseren Kräften messen! Nehmt diesen Dreizack und verwendet ihn, um die wertlosen Diener des Gezeitenjägers zu vernichten.\n\nWenn wir finden, was wir hier suchen, soll Neptulon selbst um sein Leben fürchten müssen!", sourceObjective = "Besiegt 5 Diener von Neptulon. (Ihr müsst in Nagagestalt sein, während Ihr sie bekämpft.)\n\nSolltet Ihr Euren Dreizack der Zackenkämme verlieren, sprecht mit Valishj.\n\nWenn Ihr Euren Zackenkammglücksbringer verliert, sprecht mit Korrah in Ethel Rethor.", completion = "Die feindlichen Linien dünnen sich aus, kleines Fischlein.\n\nVielleicht seid Ihr würdig, uns bei unserer Suche zu helfen...", sourceObjectiveStatus = "unverified-source-field" }
quests[14265] = { id = 14265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Lehrmeister", description = "Die meisten von uns haben es lebend hierher geschafft... aber auf dieser Seite der Stadt gibt es auch Worgen.\n\nSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.\n\nDa fällt mir ein: Jemand hat nach Euch gefragt. Ein Typ namens Cleese meinte, Ihr wärt einer seiner Lehrlinge und wollte sicherstellen, dass es Euch gut geht.", sourceObjective = "Redet mit Unteroffizier Cleese im Militärviertel.", completion = "{name}! Wo wart Ihr?\n\nWie auch immer, es ist großartig, Euch in einem Stück wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14266] = { id = 14266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmangriff", description = "Ihr seid am Leben, {name}! Also habe ich wohl meine Sache richtig gemacht.\n\nEine Schande, dass unser Unterricht so abrupt abgebrochen wurde. Aber auf Eurem Weg werdet Ihr beginnen, neue Techniken zu entdecken.\n\nGeht, sammelt mehr Erfahrung, lernt etwas Neuers und probiert es dann an den Blutfangworgen im Westen aus.", sourceObjective = "Erreicht Stufe 3, um 'Sturmangriff' zu erlernen. Übt anschließend 'Sturmangriff' gegen einen Blutfangworgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14267] = { id = 14267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Untersuchung des Meeresschreins", description = "Die Eindringlinge der Naga haben eine Reihe von Schreinen an den Klippen errichtet. Ich kenne ihren Zweck nicht, {name}, aber ich glaube, dass sie unsere Feinde stärken. Ich brauche jemanden, der sich dorthin begibt und diese Bedrohung untersucht.\n\nEin nahegelegener Schrein wird nur wenig bewacht. Überquert die erste Brücke östlich von hier und dann wendet Euch nach Norden in Richtung der Bucht. Ihr findet den Schrein auf einer kleinen Felszunge. Untersucht ihn und kehrt mit ein paar nützlichen Informationen zurück.", sourceObjective = "Untersucht den Schrein der Naga für Torg Zweimalmer.", completion = "Der Stein in der Mitte dieses Schreins verströmt ein schwaches Schimmern und donnert mit der Kraft des wütenden Meeres.", sourceObjectiveStatus = "unverified-source-field" }
quests[14268] = { id = 14268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wasserzeichen", description = "Königin Azshara sucht nach einem Eingang zur Wasserebene. Ich weiß nicht warum.\n\nSie glaubt, dass die Uralten wussten, wie dieser Ort zu finden ist.\n\nIch wurde persönlich damit betraut, die Ruinen in dieser Gegend abzusuchen, und niemand soll ruhen, bis wir die Geheimnisse gelüftet haben, die wir suchen!\n\nNördlich von hier ist eine Ansammlung von Ruinen. Durchsucht das Geröll mit diesem Stab.\n\nKehrt zu mir erst dann zurück, wenn Ihr gefunden habt, was wir suchen!", sourceObjective = "Priesterin Valishj will, dass Ihr die uralten Neptulon-Gravuren findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14269] = { id = 14269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemand sucht nach Euch", description = "Die meisten von uns haben es lebend hierher geschafft... aber auf dieser Seite der Stadt gibt es auch Worgen.\n\nSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.\n\nDa fällt mir ein: Jemand hat nach Euch gefragt. Eine Frau namens Loren... Sie schien etwas enttäuscht zu sein, als ich ihr sagte, dass es Euch gut geht.\n\nIch glaube sie sagte, sie schulde Euch Gold.", sourceObjective = "Sprecht mit Loren der Hehlerin im Militärviertel.", completion = "Oh, da seid Ihr ja!", sourceObjectiveStatus = "unverified-source-field" }
quests[14270] = { id = 14270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlüsselsteinscherbe", description = "Die Luft um diesen rätselhaften Stein knistert vor Energie. Der Stein selbst ist glatt und eiskalt. Als Ihr mit Euren Händen darüber gleitet, pulsiert er gleichmäßig wie brandende Wogen.\n\nEin keilförmiges Stück scheint an der Oberfläche des Artefakts zu fehlen. Diese 'Schlüsselsteinscherbe' ist vermutlich der Schlüssel zum Geheimnis des Steins. Durchsucht die Umgebung des Tempels und findet die Schlüsselsteinscherbe.", sourceObjective = "Findet die Schlüsselsteinscherbe in der Nähe.", progress = "Der Kraftstein der Naga pulsiert und summt erwartungsvoll.", completion = "Die Schlüsselsteinscherbe gleitet an ihren Platz und plötzlich erscheinen bisher unsichtbare Runen auf der Steinoberfläche und schimmern blau und violett. Eure Knie werden weich, als mächtige, arkane Ströme unvermittelt durch Euren Körper fahren...", sourceObjectiveStatus = "unverified-source-field" }
quests[14271] = { id = 14271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Berichtet Zweimalmer", description = "Eine magische Barriere pulsiert um Euch herum und Kälte fährt Euch in die Glieder. Hinter dieser Zauberwand fühlt Ihr Euch sicher.\n\nTorg Zweimalmer wird von Eurer Entdeckung erfahren wollen!", sourceObjective = "Kehrt zu Torg Zweimalmer an der Südlichen Endhaltestelle der Raketenbahn in Azshara zurück und berichtet ihm von Eurer Entdeckung.", completion = "Eine Energiebarriere, sagt Ihr? Das erklärt einiges! Ich habe Anführer der Naga gesehen, die in der Lage waren, die Klingen meiner besten Krieger abzulenken.\n\nJetzt kennen wir die Quelle ihrer Kraft, {name}. Bringen wir es zu Ende!", sourceObjectiveStatus = "unverified-source-field" }
quests[14272] = { id = 14272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausweiden", description = "Schön, Euch lebend wiederzusehen!\n\nNein, natürlich habe ich das Gold nicht, das ich Euch schulde. Jetzt ist nun wirklich nicht die Zeit, darüber zu diskutieren!\n\nHört zu, vielleicht kann ich Euch ein oder zwei Tricks beibringen, die Euch helfen werden, trotz des ganzen Gemetzels hier Eure Haut zu retten.\n\nWährend Ihr lernt, wie man kämpft, werdet Ihr auch andere neue Dinge lernen. Geht, sammelt mehr Erfahrung und wenn Ihr dann etwas Neues gelernt habt, solltet Ihr es an den Blutfangworgen im Westen ausprobieren. Ich werde Euch beobachten.", sourceObjective = "Erreicht Stufe 3, um 'Ausweiden' zu erlernen. Übt 'Ausweiden' an einem Blutfangworgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14273] = { id = 14273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwielichtige Gesellen", description = "Die meisten von uns haben es lebend hierher geschafft... aber auf dieser Seite der Stadt gibt es auch Worgen.\n\nSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.\n\nDa fällt mir ein: Jemand hat nach Euch gefragt. So ein seltsamer Geselle namens Vitus... der war echt unheimlich.\n\nEr hat die ganze Zeit von einem \"verbotenen Wissen\" erzählt, das er sich angeeignet hat.", sourceObjective = "Sprecht mit Vitus Dunkelwandler im Militärviertel.", completion = "Dunkelheit ist über unser Land gekommen. Und nicht die übliche Art Dunkelheit, wenn Ihr versteht, was ich meine.", sourceObjectiveStatus = "unverified-source-field" }
quests[14274] = { id = 14274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbnis", description = "Also ist es wahr! Ihr seid am Leben!\n\nIch hatte nie die Gelegenheit, meine größte Entdeckung mit Euch zu teilen. Aus dem geheimen Wissen der kaum entzifferbaren Bücher von Balcephoth dem Teufelsschatten... lernte ich die verbotenen Geheimnisse der...\n\nVerderbnis!\n\nGeht, sammelt mehr Erfahrung, vielleicht erlernt Ihr einen neuen Zauberspruch. Ihr könnt Ihn dann gegen die Blutfangworgen im Westen einsetzen.", sourceObjective = "Erreicht Stufe 3, um 'Verderbnis' zu erlernen. Übt 'Verderbnis' an einem Blutfangworgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14275] = { id = 14275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemand ist Euch auf der Fährte", description = "Die meisten von uns haben es lebend hierher geschafft... aber auf dieser Seite der Stadt gibt es auch Worgen.\n\nSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.\n\nDa fällt mir ein: Jemand hat nach Euch gefragt. Ein Mann namens Blake. Sagte etwas über einen Plan, in die Wälder zu flüchten.", sourceObjective = "Sprecht mit Jäger Blake im Militärviertel.", completion = "{name}! Ich wusste, dass Ihr hier irgendwo sein müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[14276] = { id = 14276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zuverlässiger Schuss", description = "Also, ich habe gute und schlechte Nachrichten.\n\nDie schlechte Nachricht ist, dass es in den Wäldern mehr Worgen gibt als hier drin... also haben wir keinen sicheren Ort, an den wir uns zurückziehen können.\n\nDie gute Nachricht ist, dass Ihr langsam den Dreh raushabt. Wenn Ihr erfahrener werdet, werdet Ihr neue Dinge erlernen.\n\nSobald Ihr Eure erste Fähigkeit erlernt habt, probiert Euch doch gegen die Blutfangworgen im Westen aus.", sourceObjective = "Erreicht Stufe 3, um 'Zuverlässiger Schuss' zu erlernen. Übt 'Zuverlässiger Schuss' zweimal gegen einen Blutfangworgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14277] = { id = 14277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Anfragen", description = "Die meisten von uns haben es lebend hierher geschafft, aber auch in diesem Teil der Stadt gibt es Worgen.\n\nWir werden weiter nach Süden ziehen, sobald sich alle gesammelt haben.\n\nDa fällt mir ein, dass jemand nach Euch gefragt hat. Es war eine Magierin namens Myriam. Sie meinte etwas wie Ihr wärt \"bereit\".", sourceObjective = "Sprecht mit Myriam Zauberwache im Militärviertel.", completion = "Ein Schüler der arkanen Künste findet immer einen Weg nach vorne. Ich freue mich, Euch zu sehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14278] = { id = 14278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht die Schwester", description = "Die meisten von uns haben es lebend hierher geschafft... aber auf dieser Seite der Stadt gibt es auch Worgen.\n\nSobald alle hier eingetroffen sind, werden wir weiter nach Süden ziehen.\n\nDa fällt mir ein: Jemand hat nach Euch gefragt. Eine Geistliche namens Schwester Almyra sagte, Ihr befändet Euch in großer Gefahr und brauchtet den Schutz des Lichts.\n\nIhr solltet mit ihr reden. Sie schien sehr in Sorge zu sein.", sourceObjective = "Sprecht mit Schwester Almyra im Militärviertel.", completion = "Das Licht ist mit Euch, {name}. Ich bin sehr erleichtert, Euch zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14279] = { id = 14279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das richtige Wort", description = "Ihr habt noch viel zu lernen, {name}. Und ich habe Euch viel beizubringen.\n\nEs herrschen gefährliche Zeiten, daher fürchte ich, dass wir unsere Lektionen etwas beschleunigen müssen.\n\nHabt keine Angst, <Bruder/Schwester>. Das Licht wird uns beschützen.\n\nGeht, sammelt mehr Erfahrung und erlernt eine neue Fähigkeit. Setzt sie dann gegen die Blutfangworgen in der Nähe ein.", sourceObjective = "Erreicht Stufe 3, um 'Schattenwort: Schmerz' zu erlernen und wendet es 2-mal gegen einen Blutfangworgen an.", sourceObjectiveStatus = "unverified-source-field" }
quests[14280] = { id = 14280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Winde kennen Euren Namen… anscheinend", description = "Die meisten von uns haben es lebend hierher geschafft, aber auch in diesem Teil der Stadt gibt es Worgen.\n\nWir werden weiter nach Süden ziehen, sobald sich alle gesammelt haben.\n\nDa fällt mir ein, dass jemand nach Euch gefragt hat. Es war die Erntehexe Celestine. Sie sagte, die Winde hätten Euren Namen geflüstert.\n\nIhr solltet Euch lieber beeilen, {name}. Ihr müsst schnell zurückkommen und den Worgen den Garaus machen, wenn Ihr Euer Gespräch mit der Natur beendet habt.", sourceObjective = "Sprecht mit Celestine Erntedank im Militärviertel.", completion = "Welcher Segen ereilt uns heute! Ihr seid am Leben und wohlauf!", sourceObjectiveStatus = "unverified-source-field" }
quests[14281] = { id = 14281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostnova", description = "Es liegt ein harter Weg vor uns, {name}. Wir müssen all unsere geistige Kraft auf unsere Aufgabe richten.\n\nWenn Ihr an Macht gewinnt, werden sich Euch neue Wege zum Arkanen in Eurem Geist offenbaren. Ihr werdet Zauber entwickeln, die Ihr vorher noch nicht kanntet.\n\nGeht, sammelt Erfahrung und nutzt dann das, was Ihr gelernt habt, gegen die Blutfangworgen.", sourceObjective = "Erreicht Stufe 3, um 'Frostnova' zu erlernen. Übt 'Frostnova' an einem Blutfangworgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14282] = { id = 14282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rätsel gelöst", description = "Eure Bemühungen haben sich ausgezahlt. Das große Risiko, das Ihr eingegangen seid, hat sich gelohnt.\n\nIhr habt das Objekt der Begierde der Naga gefunden und damit ihre Gründe dafür, warum sie die Küsten von Desolace überrennen.\n\nWas die Gravuren angeht, die Ihr entdeckt habt – Eure nächste Aufgabe ist klar...", sourceObjective = "Ihr sollt die uralten Neptulon-Gravuren zu Korrah, Forscher des Cenarius bringen.", progress = "Was habt Ihr herausgefunden, {class}?", completion = "Die Vision traf zu!\n\nIm Alleingang habt Ihr das erreicht, wo andere gescheitert sind.\n\nDer Zirkel wird keine Wahl haben, als diesen Entdeckungen seine Aufmerksamkeit zu schenken.", sourceObjectiveStatus = "unverified-source-field" }
quests[14283] = { id = 14283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondfeuer", description = "Wir standen schon einmal am Rande der Ausrottung, {name}. Aber wir Druiden, Hüter des alten Wegs, haben unsere Leute vor der Hungersnot gerettet.\n\nAls wir uns selbst von der Außenwelt abschnitten und unsere Ernte ein Misserfolg war, war es unser Orden, der den Segen der Erde herbeigerufen und die Früchte wieder zum Wachsen gebracht hat.\n\nGenauso wie damals sollten wir unser Schicksal in die Hände einer höheren Macht legen. Kommt mit mir und lernt, was die Wildnis uns zu lehren hat.\n\nGeht, entwickelt Eure Kräfte und setzt das, was Ihr erlernt habt, gegen die Blutfangworgen ein.", sourceObjective = "Erreicht Stufe 3, um 'Mondfeuer' zu erlernen und wendet es dann gegen einen Blutfangworgen an.", sourceObjectiveStatus = "unverified-source-field" }
quests[14284] = { id = 14284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache eines Klagegeistes", description = "Ich bin Hydronis, ein Diener von Neptulon dem Gezeitenjäger, Herr über alle Gewässer.\n\nAzshara und ihre finsteren Naga haben sich gegen meinen Meister verbündet und ihm den Krieg erklärt. Das ist die erste in einer langen Reihe von Schlachten.\n\nIch habe erbittert gekämpft, {race}, und ich mache mir Sorgen.\n\nEs scheint, dass meine Taten hier die Aufmerksamkeit ihrer Priesterin auf sich gezogen haben.\n\nAllerdings habe ich nicht die Stärke, sie zu überwinden. Aber vielleicht können wir sie mit vereinten Kräften besiegen.", sourceObjective = "Hydronis will, dass Ihr ihn besteigt und die Priesterin Valishj besiegt.", completion = "Die Priesterin existiert nicht mehr...", sourceObjectiveStatus = "unverified-source-field" }
quests[14285] = { id = 14285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je mehr, desto sicherer", description = "Solange die Worgen es darauf angelegt haben, uns alle Gliedmaßen auszureißen, kann ich Euch leider nicht so viel beibringen, wie ich möchte.\n\nWir sollten wirklich in Betracht ziehen, mit den anderen Überlebenden nach Süden zu ziehen. Wir haben erfahren, dass König Graumähne sich dort aufhält.\n\nWenn wir zusammen bleiben, steigen unsere Überlebenschancen... besonders wenn Ihr neben jemandem steht, der schmackhaft aussieht.", sourceObjective = "Sprecht mit König Genn Graumähne im Militärviertel.", completion = "Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14286] = { id = 14286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je mehr, desto sicherer", description = "Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.\n\nEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.\n\nWir sollten dorthin gehen und in der Masse Schutz suchen.", sourceObjective = "Sprecht mit König Genn Graumähne im Militärviertel.", completion = "Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14287] = { id = 14287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je mehr, desto sicherer", description = "Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.\n\nEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.\n\nWir sollten dorthin gehen und in der Masse Schutz suchen.", sourceObjective = "Sprecht mit König Genn Graumähne im Militärviertel.", completion = "Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14288] = { id = 14288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je mehr, desto sicherer", description = "Solange die Worgen es darauf angelegt haben, uns alle Gliedmaßen auszureißen, kann ich Euch leider nicht so viel beibringen, wie ich möchte.\n\nWir sollten wirklich in Betracht ziehen, mit den anderen Überlebenden nach Süden zu ziehen. Wir haben erfahren, dass König Graumähne sich dort aufhält.\n\nWenn wir zusammen bleiben, steigen unsere Überlebenschancen... besonders wenn Ihr neben jemandem steht, der schmackhaft aussieht.", sourceObjective = "Sprecht mit König Genn Graumähne im Militärviertel.", completion = "Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14289] = { id = 14289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je mehr, desto sicherer", description = "Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.\n\nEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.\n\nDie anderen werden in diesen dunklen Zeiten die Hilfe des Lichts dringend benötigen.", sourceObjective = "Sprecht mit König Genn Graumähne im Militärviertel.", completion = "Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14290] = { id = 14290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je mehr, desto sicherer", description = "Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.\n\nEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.\n\nWir sollten dorthin gehen und in der Masse Schutz suchen.", sourceObjective = "Sprecht mit König Genn Graumähne im Militärviertel.", completion = "Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14291] = { id = 14291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Je mehr, desto sicherer", description = "Ich habe Euch alles beigebracht, was mir derzeit sinnvoll erscheint.\n\nEs ist an der Zeit, dass wir uns den anderen Überlebenden anschließen. Ich habe gehört, dass König Graumähne und seine Königswache sich direkt südlich von hier aufhalten sollen.\n\nWir sollten dorthin gehen und in der Masse Schutz suchen.", sourceObjective = "Sprecht mit König Genn Graumähne im Militärviertel.", completion = "Es war klug von Euch, hierher zu kommen. Wenn die Einwohner von Gilneas zusammenhalten, können wir diesen schrecklichen Feind vielleicht doch noch besiegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14292] = { id = 14292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Feind unserer Feinde", description = "Ihr habt uns einen großen Dienst erwiesen, {class}.\n\nObwohl sie weiterhin eine imposante Streitmacht sind, haben Eure Bemühungen den Naga ein wichtiges Artefakt vorenthalten.\n\nIch werde meinen Mitstreitern von Eurem Fund berichten. Währenddessen hat sich der Wasserklagegeist auf der Insel Ranazjar die ganze Zeit alleine gegen den ständigen Ansturm der Naga zur Wehr gesetzt.\n\nIch bitte Euch, ihn ausfindig zu machen. Findet heraus, ob es eine Möglichkeit gibt, ihm zur Seite zu stehen.", sourceObjective = "Korrah, Forscher des Cenarius, will, dass Ihr mit Lord Hydronis sprecht.", completion = "Ich habe Eure Taten hier wohl beobachtet, {race}.\n\nEure Anwesenheit ist sehr geschätzt und kommt genau im rechten Augenblick.", sourceObjectiveStatus = "unverified-source-field" }
quests[14293] = { id = 14293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet Krennan Aranas", description = "Noch so viele Jahre nach dem Krieg hat Crowley genügend Waffen in diesem Keller versteckt, um das halbe Viertel in die Luft zu jagen.\n\nLeider werden wir das wahrscheinlich auch tun müssen.\n\nWir können das Feuer jedoch noch nicht eröffnen, da ein Zivilist auf der anderen Seite des Gefängnisses in der Falle sitzt.\n\nUnd dabei handelt es sich nicht um irgendeinen Zivilisten. Krennan Aranas ist einer der brillantesten Alchemisten, den die Welt je gesehen hat.\n\nEiner seiner Tränke hat meine Tochter Tess kurz nach der Geburt vor dem sicheren Tod gerettet.\n\nNehmt mein Pferd und rettet ihn. Krennan darf nicht sterben.", sourceObjective = "Rettet Krennan Aranas.", completion = "Gut gemacht, {name}. Wir werden dafür sorgen, dass Krennan heil aus der Stadt fliehen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[14294] = { id = 14294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neu formieren", description = "Wir haben hier alles getan, was wir tun konnten. Gebt König Graumähne Bescheid, dass wir etwas Zeit herausschinden konnten.\n\nIch habe das Gefühl, dass es nicht lange dauern wird, bis die Worgen sich neu formieren.\n\nWir werden uns in den Graumähnenhof im Westen zurückziehen müssen, wenn es so weit kommt. Das ist der letzte Ort, an dem wir standhalten können, ohne wie ein Fisch im Netz zu zappeln.", sourceObjective = "Sprecht mit König Genn Graumähne im Graumähnenhof in Gilneas.", completion = "Viele Möglichkeiten stehen uns nicht zur Auswahl, {name}. Unser nächster Schritt wird eine wichtige Entscheidung.", sourceObjectiveStatus = "unverified-source-field" }
quests[14295] = { id = 14295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwestern des Meeres", description = "Zwei Hexen der Naga haben den Angriff auf diesen Außenposten ersonnen. Sie haben die direkten Angriffe meiner besten Grunzer abgewehrt, aber Ihr könnt die Aufgabe erledigen, an der andere gescheitert sind.\n\nFindet und vernichtet Lady Silisthra und Lady Vesthra am östlichen Rand der Klippen in der Nähe der Ruinen des uralten Nachtelfenkolosses. Ihr müsst zuerst die Kraftsteine vernichten, die ihnen ihre Stärke geben. Enttäuscht mich nicht, {class}!", sourceObjective = "Tötet Lady Silisthra und Lady Vesthra, indem Ihr ihre Kraftsteine deaktiviert.", completion = "SO springen wir mit Schlangen in Durotar um – wir zertreten sie unter unseren Stiefeln! Ihr habt die Horde stolz gemacht, {name}. Sobald meine Verstärkung eintrifft, fegen wir den Rest dieses Ungeziefers von der Halbinsel und beanspruchen sie ein für alle Mal für uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[14296] = { id = 14296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolpert nicht", description = "Auf eine Art ist dies einfach und auf eine andere Art nicht. Den ganzen Weg nach dort oben liegen Energieleitungen. So ähnlich wie diese hier möchte ich sagen! Ich sage es also.\n\nNun zu Euch. Ihr müsst meine Springfelder verwenden, um die Spitze zu erreichen und Ihr müsst alle Leitungen berühren, die Ihr auf Eurem Weg seht. Wenn Ihr bei mir an der Spitze ankommt, solltet Ihr vor Energie nur so triefen und so soll es auch sein.\n\nUnd achtet darauf, dass Ihr nicht stillsteht, denn sonst werdet Ihr vermutlich eine unangenehme Reise antreten!", sourceObjective = "Empfangt 6 Energieladungen von den Energieleitungen, während ihr zum Gipfel der Arkanen Spitze gelangt.", progress = "Neinneinnein, so läuft das nicht. Ihr solltet die Energie der Leitungen empfangen, bevor Ihr hier herauf kommt, erinnert Ihr Euch?\n\nNoch einmal und mit etwas mehr Haltung!", completion = "In diesem Augenblick fragen sich die meisten Schüler, ob es einen logischen Grund dafür gibt, die Energie für mein Portal in diesen Leitungen zu speichern und ob sie auf diese Weise gesammelt werden muss.\n\nNatürlich gibt es einen Grund! Ich will Euer Verhalten erforschen... Eure Strategien, Eure Fehler, Eure Frustration, Eure Siege. Das ist der eigentliche Witz, der hinter diesen Prüfungen steckt.\n\nUnd nun noch weitere. Noch mehr Prüfungen! Klingt das nicht aufregend?! Aber natürlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[14297] = { id = 14297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheitskämpfer", description = "Ich wusste, dass diese Kerle Schwierigkeiten machen werden, sobald wir mit dem Turmbau anfingen. Sie spotten über unsere Bestechungsgelder. Sie stehlen unsere Arbeiter.\n\nArbeitskraft ist heutzutage nicht billig, wo in Azshara so viel gebaut wird. Ich muss diese Männer wiederhaben!", sourceObjective = "Verwendet die schmiedeeisernen Schlüssel der Kultisten und der Drachenkin, um 4 Arbeiter der Goblins auf dem Säbelrücken zu befreien.", completion = "Dank Euch, Kumpel. Hier ist Eure Provision.\n\nNun entschuldigt mich. Ich muss dafür sorgen, dass diese Faulpelze wieder an die Arbeit gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14298] = { id = 14298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet Kultisten/Drachenschwarm" }
quests[14299] = { id = 14299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xylems Asyl", description = "Ziemlich fabelhaft von Euch! Eine wahre Freude, Euch bei der Arbeit zuzusehen. Es gibt viel zu erforschen.\n\nUnd nun los, ruht Euch in meinem Turm aus. Joanna wird Euch unterbringen. Ich öffne ein Portal für Euch.", sourceObjective = "Nehmt das Portal zum Turm des Erzmagiers Xylem und sucht im Turm nach Joanna.", completion = "Willkommen! Ihr scheint die Prüfungen relativ unbeschadet überstanden zu haben. Gut für Euch, Liebchen.\n\nIhr seht so aus, als ob Ihr mit einer bestimmten Absicht hergekommen seid. Eine Frage. Eure Gedanken sind sehr laut. Es ist mir fast unmöglich, sie zu überhören.\n\nNa los, Schätzchen. Fragt mich schon.", sourceObjectiveStatus = "unverified-source-field" }
quests[14300] = { id = 14300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Prüfung des Feuers", description = "Die Prüfung des Feuers... ohooo... Das klingt einschüchternd, nicht wahr? Nein? Hm. Tja, das habe ich mir irgendwie gedacht. Wer zuerst kommt, mahlt zuerst. Ihr berührt den Feuerkristall und das Portal zur Prüfung öffnet sich.\n\nUm diese Prüfung zu bestehen, müsst Ihr durch die Feuerrunen springen, ohne von dem Feuer getroffen zu werden. Falls Ihr lange genug durchhaltet, ohne in Flammen zu stehen, habt Ihr gewonnen!\n\nEs gibt kleine Anzeichen, die Euch helfen. Das Feuer springt zu einer neuen Rune und es zischt, wenn eine Rune erkaltet. Wenn Ihr wollt, findet es heraus. Oder Ihr ratet einfach! Das machen die meisten so.", sourceObjective = "Besteht die Prüfung des Feuers, indem Ihr in den Feuerrunen steht und 10 aufeinanderfolgende Explosionen übersteht, ohne getroffen zu werden.", completion = "Hui! Gut für Euch! Die Prüfung macht einem wirklich Feuer unter dem Hintern.", sourceObjectiveStatus = "unverified-source-field" }
quests[14301] = { id = 14301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zurück und berichtet", description = "Es ist vollbracht! Gemeinsam haben wir es geschafft, einen gefährlichen Gegner auszuschalten.\n\nNeptulon selbst wird von Euren Heldentaten zu hören bekommen, {class}. Erlaubt mir, Euch in seinem Namen zu danken...\n\nIhr solltet nun gehen. Dieser Ort wird für Euch nicht mehr lange sicher sein. Bald werden die Naga auf Rache für ihre Priesterin sinnen.", sourceObjective = "Kehrt zu Korrah, Forscherin des Cenarius in Ethel Rethor zurück.", completion = "Bitte nehmt diese Belohnung für Eure Heldentaten entgegen, {name}.\n\nIhr habt uns wertvolle Zeit erkauft!", sourceObjectiveStatus = "unverified-source-field" }
quests[14302] = { id = 14302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offizielle Einschätzung", description = "Ihr habt mit Euren Bemühungen gegen die Naga viel erreicht, {name}. Aber ich fürchte, es ist nicht einmal ansatzweise genug...\n\nDies ist meine offizielle Einschätzung der Anwesenheit der Naga.\n\nIch bin mir sicher, dass meine Mitstreiter in der Wildnis die notwendigen Maßnahmen einleiten werden.\n\nBringt dies zu Karnum an der Lichtung in der Mitte der Cenariuswildnis im Südosten. Er wird wissen, was zu tun ist.\n\nHabt Dank, {name}. Und lebt wohl.", sourceObjective = "Korrah, Forscherin des Cenarius, will, dass Ihr Korrahs Bericht zu Karnum auf Karnums Lichtung bringt.\n\nBereitgestellter Gegenstand:", completion = "<Karnum öffnet Korrahs Bericht und liest ihn.>\n\nDas ist wahrhaftig eine alarmierende Neuigkeit, {race} – etwas, das hier leider keine Seltenheit ist.\n\nIch werde den Rat in dieser Angelegenheit einberufen. Ihr werdet hinzugezogen, wenn es vonnöten sein sollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[14303] = { id = 14303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Aggra", description = "Kehrt zum Basislager der Horde zurück und lasst Aggra wissen, dass wir noch am Leben sind, {name}.\n\nSagt ihr, dass ich zur Wilden Aussicht weiterziehe und dass wir uns alle im Nordwesten der Insel treffen. Ich erwarte Euch dort.\n\nWir werden die Fährte der Allianz aufnehmen und jeden einzelnen von ihnen töten!", sourceObjective = "Informiert Aggra im Basislager der Horde auf den Verlorenen Inseln über die Geschehnisse.", completion = "<Aggra betrachtet Euch argwöhnisch, als würde sie Euch nicht glauben.>\n\nIch bin nicht leicht zu beeindrucken, aber wenn das, was Ihr sagt, stimmt, dann habe ich noch nie zuvor so etwas gehört.\n\nIhr habt meinen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14304] = { id = 14304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutabnahme", description = "In Desolace hat sich nicht nur das Land verändert. Hier haben die Wildtiere auf ihre neue Umgebung auf seltsame und manchmal höchst interessante Weise reagiert.\n\nBesonders interessiert bin ich an den verjüngten Donnerechsen, die in dieser Gegend im Westen umherstreifen.\n\nIch brauche eine Probe ihres Blutes.\n\nIhr könnt anfangen, mir zu helfen, indem Ihr dieses Glas voller Blutegel auf einigen von ihnen absetzt.\n\nSobald die Egel sich mit dem Blut der Tiere vollgesogen haben, bringt sie mir zurück.", sourceObjective = "Sammelt 10 blutgefüllte Egel.", progress = "Habt Ihr die Proben bekommen, die ich benötige?", completion = "Das sollte ausreichen.\n\nHabt Dank, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14305] = { id = 14305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erntezeit", description = "Keiner weiß es besser, als der Zirkel des Cenarius, dass diese grünende Oase genauso schnell vertrocknen kann, wie sie erblüht ist.\n\nWir müssen dafür sorgen, dass wir uns nicht in die Prozesse einmischen, die hier stattfinden, aber wir müssen sie unterstützen und schützen.\n\nEine neue Pflanzensorte hat sich nach der großen Teilung in der umgebenden Region breitgemacht.\n\nSammelt mir ein paar Proben dieser Pflanzen, sodass ich sie untersuchen kann. Ich will herausfinden, was wir von ihnen lernen können.", sourceObjective = "Sammelt 10 Aloedisteln.", progress = "Habt Ihr die Proben gesammelt, die ich benötige?", completion = "Das sind schöne Exemplare, {race}.\n\nIch werde sofort mit meinen Untersuchungen beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14306] = { id = 14306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unkraut jäten", description = "Bei einem derart abrupten Wandeln der Ökologie ist zu erwarten, dass einige Teile der Flora und Fauna nicht so reagieren, wie wir es uns erhoffen.\n\nDie entwurzelten Peitscher sind ein lästiges Beispiel dafür. Sie befinden sich in den Feldern im Osten und Süden und schaden der Region. Wir müssen sie loswerden.\n\nWährend Ihr dort seid, kümmert Euch bitte um alle dieser Schädlinge, die Ihr finden könnt.", sourceObjective = "Tötet 7 entwurzelte Peitscher.", completion = "Im Namen von Desolace selbst danke ich Euch, {race}.\n\nBitte nehmt unsere tiefste Dankbarkeit an.", sourceObjectiveStatus = "unverified-source-field" }
quests[14307] = { id = 14307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steife Brise", description = "Wandel liegt in der Luft, {race}. Daran besteht kein Zweifel.\n\nEs gibt zahlreiche, dringende Angelegenheiten, die um unsere Aufmerksamkeit und unsere Tatkraft buhlen. Die wichtigste unter ihnen ist der Ausbau unserer wachsenden Oase.\n\nSie ist schneller gewachsen, als wir zu hoffen gewagt haben und auch schneller, als wir verstehen können. Dennoch stößt das Wachstum nun auf Widerstand.\n\nIm Westen, wo das Gras auf den Sand trifft, verhindern Wirbelstürme ihr weiteres Eindringen in die Wüste.\n\nGeht und vernichtet diese lebensfeindlichen Hindernisse!", sourceObjective = "Zerstört 5 Wirbelsturmgänger.", completion = "Ihr habt gute Arbeit geleistet, {class}.\n\nWir werden Euch zukünftig zweifellos in wichtigeren Angelegenheiten um Hilfe bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14308] = { id = 14308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Wissenschaft", description = "Habt Ihr die Explosionen auf Eurem Weg hierher gesehen? Das Geheimlabor steht in Flammen! Schon wieder! Wenn wir diese Flammen nicht löschen, wird die Temperatizität kritisch und das wird in einer Schmelzkettenreaktion resonieren.\n\nHier. Ich vertraue Euch einen Kanister eines experimentellen, hypergekühlten Druckflüssiggels an: das flüchtigste Feuerlöschmittel, das der Wissenschaft bekannt ist! (Haltet den Kanister fern von offenen Flammen.) Löscht das Feuer und rettet meine Praktikanten. Dann kontaktiert mich über den Quäkkasten der Zentralsteuerung.", sourceObjective = "Verwendet den Feuerliminator X-21, um 8 Feuer zu löschen und rettet 6 Laborpraktikanten aus dem Inferno im Geheimlabor.\n\nSprecht mit Assistentin Greely an der Südlichen Endhaltestelle der Raketenbahn, solltet Ihr Euren Feuerliminator verlieren.", progress = "<Greelys Quäkstimme dringt durch ein Lautsprecherpaar.>\n\nRaketenbahn an Geheimlabor! Raketenbahn an Geheimlabor! Geheimlabor, bitte kommen...", completion = "Gute Arbeit, {name}! Jetzt müssen wir die Reaktionskernmatrix vom Treibstofftank trennen oder wir kriegen hier unsere eigene Mini-Scherbenwelt...", sourceObjectiveStatus = "unverified-source-field" }
quests[14309] = { id = 14309, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kodoflüsterer", description = "Wie Ihr bereits bemerkt habt, können die ungewöhnlich schnellen Veränderungen in dieser Region sowohl positive als auch negative Effekte auf die einheimischen Kreaturen haben.\n\nIm Süden und im Osten sind wütende Kodos eine ständige Bedrohung für jeden in der Nähe.\n\nEs wird Zeit, meine Theorie zu testen. Ich habe das Blut der verjüngten Donnerechse für die Herstellung dieses Gebräus verwendet. Ich hoffe, dass es die Kodos besänftigen wird, die es zu sich nehmen.\n\nPlatziert es in der Nähe eines wütenden Kodos und seht zu, dass Ihr es mit dem entsprechenden Sicherheitsabstand tut!", sourceObjective = "Benutzt das Kodobesänftigungsmittel in der Nähe von 5 wütenden Kodos.", completion = "Wundervoll! Karnum wird sehr erfreut sein!\n\nBitte nehmt dies zum Dank dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[14310] = { id = 14310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schutzverletzung: Kernabkopplung", description = "Sobald wir den Zentralreaktor versenkt haben, müsst Ihr den Kern zu mir bringen. Er besteht aus 100% raffiniertem Azsharitkristall, der sowohl mächtig als auch gefährlich ist. Und hübsch anzusehen. Oh, du schöner Azsharit, Former der kommenden Welten!\n\nDer riesenhafte Hebel zu Eurer Linken wird den Kern versenken und über das Schienensystem zu mir schicken. Der Kern wird stark erhitzt sein. Deshalb müsst Ihr ihn immer wieder mit dem Feuerliminator auf dem Weg hierher abkühlen... Er darf keinesfalls kritische Temperatur erreichen!", sourceObjective = "Aktiviert das Reaktorkontrollpult und eskortiert den Azsharitkern zurück zur Südlichen Endhaltestelle der Raketenbahn. Wendet den Feuerliminator X-21 auf den Kern an, damit er sich nicht überhitzt.", progress = "Sorgt Euch nicht um die Spätfolgen all dieser ätzenden Chemikalien im Labor. Haare wachsen nach!", completion = "Puh, die Probe ist in Sicherheit. Und sie dampft noch immer! Habt Dank, {name}.\n\nAzsharit ist ein komplexes Geheimnis, gehüllt in ein samtiges Rätsel der Gefahr. Wurfhammer besteht darauf, dass wir mehr über diese mysteriöse Substanz herausfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14311] = { id = 14311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer Ernten will muss säen", description = "In was für herrlichen Zeiten wir doch leben!\n\nDas ehemalige Ödland von Desolace blüht und birst vor Leben. Stellt Euch vor, {class}, das Ödland von ganz Azeroth würde in dieser Art erblühen! Vielleicht eines Tages...\n\nEs stimmt, dass es hier gewichtigere Dinge gibt, aber warum sollten wir uns nicht einen Augenblick Zeit nehmen, um die erstaunlichen Wunder zu würdigen, deren wir Zeuge sein dürfen?\n\nOder warum nehmen wir nicht daran Teil? Hier sind ein paar Samen des Cenarius. Verwendet sie an einem fruchtbareren Ort in der Einöde.\n\nEs ist die perfekte Medizin zur Erheiterung der sorgenvollen Seele!", sourceObjective = "Pflanzt 5 Samen des Cenarius in der Nähe der fruchtbaren Erdhügel in der Cenariuswildnis.", completion = "Die Verjüngung ist so belebend! Findet Ihr nicht auch?", sourceObjectiveStatus = "unverified-source-field" }
quests[14312] = { id = 14312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorstellung beim Khan", description = "Ich habe von Euren Heldentaten hier in Desolace gehört, {name}. Wir stehen in Eurer Schuld.\n\nLeider muss ich Euch bereits in einer weiteren Angelegenheit um Hilfe bitten, die dringlicher ist als der Rest.\n\nHier hat sich in der letzten Zeit nicht nur die Landschaft verändert. Alte Konflikte sind neuen, noch schlimmeren gewichen. Ich sollte unseren Gästen erlauben, alles Weitere zu erklären...\n\nKhan Leh'prah ist einer der Letzten des Stammes der Kolkar, der einst den gesamten Osten von Desolace beherrschte. Wir fanden ihn dem Tode nah an unserer Grenze. Hört seine Worte.", sourceObjective = "Garren Finsterwind auf Karnums Lichtung will, dass Ihr mit Khan Leh'prah sprecht.", completion = "Habt keine Angst, {race}. Ich tue Euch nichts zuleide.", sourceObjectiveStatus = "unverified-source-field" }
quests[14313] = { id = 14313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder unter Menschen", description = "Krennans Trank hat Euch also nicht umgebracht? Nun, das heißt wohl, dass der Mensch in Euch die Überhand hat.\n\nUnter diesen Umständen werde ich Euch doch nicht erschießen. Zumindest noch nicht.\n\nSprecht mit Krennan Aranas und überbringt ihm die gute Nachricht.\n\nAber vergesst nicht, {name}. Ich behalte Euch im Auge. Sobald Ihr irgendetwas Merkwürdiges versucht, jage ich Euch eine Kugel zwischen die Augen.", sourceObjective = "Sprecht mit Krennan Aranas in Dämmerhafen.", completion = "Es hat funktioniert! Beim Licht, es hat funktioniert!", sourceObjectiveStatus = "unverified-source-field" }
quests[14314] = { id = 14314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausbruch!", description = "Es begann mit einem Traum, der mich immer wieder vor einer Gefahr warnte, die da kommen sollte. Ich sah die dämonischen Legionen über unsereins herfallen und das Land überrennen.\n\nDer Traum ist wahr geworden. Die Brennende Klinge und ihre Dämonenmeister haben die Magram aus ihren Ländern im Süden vertrieben. Im Gegenzug haben die Magram mein Volk vernichtet und unsere Heimat übernommen.\n\nDer Kampf war wild und grausam. Nur eine Handvoll der Kolkar ist noch am Leben. Ich bitte Euch, dorthin zu gehen, wo einst mein Land im Osten war, und sie aus Ihrem Gefängnis zu befreien.", sourceObjective = "Tötet den Wächter der Magram im Dorf der Magram.", completion = "Habt Dank, {race}.\n\nUnser Stamm hätte ohne Eure Hilfe nicht überlebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14315] = { id = 14315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liams Schock", description = "Geht weg! Ihr seid nur in meinem Kopf… Ihr seid nicht echt… Ihr seid tot!\n\nIhr seid in Gilneas gestorben… Die Worgen… Sie haben Euch erwischt…\n\nSie hätten mich kriegen sollen… Sie hätten mich kriegen sollen…\n\nAhhh… Erst hört die Erde nicht auf zu beben... und jetzt sehe ich Trugbilder... Zu viel Schnaps...\n\n<Der Prinz scheint ganz von Sinnen zu sein. Vielleicht findet Ihr jemand anderen, mit dem Ihr sprechen könnt.>", sourceObjective = "Sprecht mit Gwen Armstead in Dämmerhafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14316] = { id = 14316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarisches Eigentum", description = "Seit die Dämonen ihr Land überfallen haben, haben die Magram alle Verbindungen zu Außenstehenden abgebrochen.\n\nSie sind misstrauisch und feindselig und haben damit begonnen, von anderen zu stehlen, anstatt für sich selbst zu sorgen.\n\nViele unserer benötigten Vorräte sind kürzlich verschwunden und wir vermuten, dass die Magram schuld daran sind.\n\nBitte, {name}, geht zu ihrem Land im Osten und sucht nach unseren Besitztümern.", sourceObjective = "Sammelt 7 Vorratskisten des Cenarius in den Ländern der Magram.", progress = "Habt Ihr unsere Besitztümer gefunden, {name}?", completion = "Wie wir vermutet haben, haben die Magram unsere Vorräte gestohlen.\n\nWir werden sie in Zukunft besser bewachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14317] = { id = 14317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erschütterungen", description = "{name}! Wir dachten, wir würden Euch nie wieder sehen!\n\nHört zu, wir brauchen Eure Hilfe. Ein großes Erdbeben hat uns heimgesucht. Die Nachbeben haben immer noch nicht nachgelassen. Prinz Liam wird uns auch keine große Hilfe sein.\n\nWir müssen sicherstellen, dass unsere Verteidigungsanlagen noch ausreichend sind. Das Königinnentor ist der einzige Schutz zwischen uns und den tollwütigen Worgen des Schwarzforsts.\n\nFolgt der Straße nach Osten aus der Stadt hinaus. Lasst mich wissen, ob das Tor der Erschütterung Stand gehalten hat.", sourceObjective = "Gwen Armstead möchte, dass Ihr das Königinnentor in Augenschein nehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14318] = { id = 14318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feinfühlige Verhandlungen", description = "Es gibt nur eine Möglichkeit, das Vertrauen und die Loyalität der Magram zu gewinnen.\n\nWir müssen sie aus ihnen herausprügeln.\n\nSie haben im Krieg gegen meinen Klan viele Verluste erlitten. Jetzt besitzen sie ein unvertrautes Land, wo sie darum kämpfen müssen, überhaupt genug zu essen zu haben.\n\nJetzt ist die richtige Zeit, um zuzuschlagen.\n\nSprecht wieder mit mir, wenn Ihr bereit seid. Dann reitet hinein und treibt meinen Speer in den Vaterstein. Wenn wir genug von ihnen töten, wird sich ihr Khan unserem Willen unterwerfen.", sourceObjective = "Khan Leh'prah will, dass Ihr den Speer des Khans der Kolkar in den Vaterstein treibt und ihn vor den Magram verteidigt, bis Khan Kammah erscheint.\n\nSprecht mit Khan Leh'prah, sobald Ihr bereit seid, zum Schlachtfeld zu reiten.", completion = "Warum mischt Ihr Euch in die Angelegenheiten der Zentauren ein, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[14319] = { id = 14319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Behandlung", description = "Hört zu, {name}. Ich will nicht groß um den heißen Brei herumreden.\n\nEs besteht die Chance, dass der Trank, den Krennan Euch zubereitet hat, nicht zum gewünschten Ergebnis führt. Oder vielleicht braucht Ihr mehr davon.\n\nSo oder so, er ist vermutlich eher in der Lage, Euch die Sache zu erklären, also geht und sucht ihn auf.", sourceObjective = "Sprecht mit Krennan in Dämmerhafen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14320] = { id = 14320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Benötigte Zutaten", description = "Ah, ja. Soweit wir wissen, gibt es kein Heilmittel gegen die Folgen des Fluchs.\n\nMit der richtigen Behandlung können wir jedoch dafür sorgen, dass Euer Verstand der Eurige bleibt, nicht der eines wilden Tiers.\n\nWir haben Glück, dass die Behandlung bei Euch angeschlagen hat. In der Regel lassen sich nur kürzlich erfolgte Infektionen behandeln.\n\nWenn wir eine Hoffnung haben wollen, den Fluch jemals rückgängig zu machen, müsst Ihr weiter Eure Medizin einnehmen.\n\nFür weitere Dosen meines Serums benötige ich Alraunenessenz. Unter einer Hütte südwestlich von hier findet Ihr eine Kiste mit dieser Essenz.", sourceObjective = "Findet die Kiste mit Alraunenessenz.", completion = "Die Kiste wurde offensichtlich zerschlagen. Alle darin enthaltenen Phiolen sind zerbrochen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14321] = { id = 14321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion", description = "<Ein langes Messer, dessen Griff mit einem Schädel verziert ist, ragt aus dem Rücken des Milizionärs. Als Ihr Euch nach Hinweisen umseht, entdeckt Ihr ein paar wild aussehende Kriegsschiffe an der Küste.>\n\n<Jemand fällt in Gilneas ein. Berichtet sofort der Bürgermeisterin von Dämmerhafen, Gwen Armstead, davon.>", sourceObjective = "Sprecht mit Gwen Armstead in Dämmerhafen.", completion = "Verlassene! Schnell, {name}! Wir müssen eine Verteidigung zusammenstellen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14322] = { id = 14322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böse Wissenschaft! Pfui!", description = "Ich habe versucht, die einheimischen Hippogryphen zu domestizieren. Als ich eine Reihe von schwächenden Elektroschocks eingesetzt habe, sind sie aus irgendeinem Grund durchgedreht! Jetzt nehmen meine Testsubjekte diesen Ort völlig grundlos auseinander! {class}, geht und schlachtet meine gescheiterten Experimente ab, bevor sie mich finden.", sourceObjective = "Tötet 8 statisch aufgeladene Hippogryphen.", completion = "Die Welt ist also wieder sicher für die Wissenschaft? Ausgezeichnet! Das nächste Mal versuche ich es mit glühenden Nadeln oder so.", sourceObjectiveStatus = "unverified-source-field" }
quests[14323] = { id = 14323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supersaugstark", description = "Ich brauche noch etwas anderes. Heißes Wasser.\n\nEs ist hier nicht leicht zu bekommen. Keine heißen Quellen, keine Freunde, die mit einem teilen. Aber es gibt dennoch eine Möglichkeit. Nehmt diesen Schwamm... Er ist supersaugstark. Verwendet ihn, um ein paar üble Platscher auf der Sandbank im Osten aufzusaugen.\n\nHabt Ihr genug, wringt sie in der Nähe des Turms aus, um den Jumbo-Elementar zu beschwören. Er hat heißes Wasser.", sourceObjective = "Saugt 20 köchelnde Wassertropfen der üblen Platscher im Osten der Ruinen von Arkkoran auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[14324] = { id = 14324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voll heißen Wassers", description = "Ergll deutete an, dass Ihr in der Lage sein solltet, den vollgesogenen Seeschwamm aus Azshara dazu zu verwenden, einen 'Jumbo'-Elementar in der Nähe des Turms von Eldara im Nordosten zu beschwören.", sourceObjective = "Erlangt eine Kugel voll kochendem Wasser von einem brühenden Wasserlord am Turm von Eldara.", progress = "Ihr seid zurück!", completion = "Bequem, nicht wahr? Wer braucht schon heiße Quellen? Das ist perfekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14325] = { id = 14325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeite für Essen", description = "<Khan Kammah hört Euch aufmerksam zu, während Ihr ihm die dämonische Bedrohung erläutert und von Khan Leh'prahs Visionen berichtet.>\n\nEs ist nicht notwendig, uns einen Vortrag über Dämonen zu halten, {race}. Sie waren es, die unseren Klan aus unseren angestammten Ländern vertrieben haben.\n\nSie waren es, die uns gezwungen haben, das Ödland der Kolkar zu übernehmen, wo wir nun um unser Überleben kämpfen.\n\nDurch den Krieg gegen die Kolkar hat unser Volk große Verluste hinnehmen müssen. Die wenigen, die von uns übrig geblieben sind, sind müde und hungrig.\n\nBringt meinem Volk Essen und dann können wir uns über Dämonen unterhalten.", sourceObjective = "Sammelt 5 Basiliskenflanken.", progress = "Habt Ihr Nahrung für meinen Klan mitgebracht, {race}?", completion = "Sehr gut, {race}!\n\nDies wird uns für den Moment am Leben erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14326] = { id = 14326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufs Oberdeck", description = "Ich hätte nie gedacht, dass ich einst wieder ein Gefangener der Allianz sein würde. Ich kann Euch nicht sagen, wie dankbar ich bin… {name}, oder?\n\nIch treffe Euch auf dem obersten Deck. Von dort machen wir ihnen den Garaus!", sourceObjective = "Begebt Euch auf das obere Deck der Sog der Vergeltung an der Küste der Verlorenen Inseln und sprecht mit Thrall.", completion = "Meine Mission ist zu wichtig, um eine Einmischung durch diese Hunde zuzulassen. Es liegt an uns beiden, ihnen ein für alle Mal ein Ende zu setzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14327] = { id = 14327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versprochen ist versprochen", description = "Es scheint, als ob wir keine Wahl haben.\n\nSo sehr es mir auch widerstrebt, mit den Kolkar zusammenzuarbeiten, in den Worten ihres Khans liegt Weisheit.\n\nIhr dürft ihm mein Wort geben, dass unsere Speere ihm in der Schlacht beistehen werden.", sourceObjective = "Khan Kammah will, dass Ihr mit Khan Leh'prah sprecht.", completion = "Ihr habt gute Arbeit geleistet, {class}.\n\nJetzt müssen wir die Gelkis überzeugen...", sourceObjectiveStatus = "unverified-source-field" }
quests[14328] = { id = 14328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drei Prinzen", description = "Die Gelkis halten sich im Südwesten von Desolace auf. Sie sind genauso stur wie die Magram, und da sie von Krieg und Vertreibung verschont geblieben sind, sind sie bedeutend stärker.\n\nUm die Gelkis gefügig zu machen, wird es einer besonderen Machtdemonstration bedürfen.\n\nKhan Shodo und seine drei Söhne regieren den Klan. Shodo ist alt und leidet unter seinen alten Kriegsverletzungen. Er verlässt niemals die Tiefen seiner Höhle. Die Quelle seiner Herrschaftsmacht liegt in seinen Söhnen.\n\nTötet sie und überzeugt den Khan, sich unserer Sache anzuschließen.", sourceObjective = "Tötet Rhoho, Sherik, und Jorreth.", completion = "Meine Söhne sind alle tot... Mein Klan zerfällt...\n\nHätte ich noch meine Jugend, ich würde Euch Arme und Beine einzeln ausreißen!\n\nJetzt führt zu Ende, was Ihr begonnen habt. Tötet mich oder lasst mich alleine mit meiner Trauer, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14329] = { id = 14329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht so schnell!", description = "<Der Khan des Klans der Gelkis starrt Euch aus leeren Augen an, als Ihr von der Bedrohung durch die Dämonen und Leh'prahs Visionen berichtet.>\n\nEs ist mir gleichgültig, was aus diesem Land wird. Ich habe meinen Klan und meine Vorväter im Stich gelassen...\n\nAuf dieser Welt gibt es nur noch eine Person, die meiner alten Seele Hoffnung geben könnte, und sie ist vermutlich ebenfalls tot.\n\nMeine geliebte Tochter Kharrah wurde vom Klan der Maraudine geraubt. Wenn Ihr sie mir lebend zurückbringt, werde ich Euren Vorschlag in Erwägung ziehen.", sourceObjective = "Khan Shodo will, dass Ihr 10 Raufer der Maraudine im Tal der Speere tötet.\n\nIhr müsst ihre Leichen nach Hinweisen über den Verbleib von Kherrah durchsuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14330] = { id = 14330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinter verschlossenen Türen", description = "Ihr habt herausgefunden, wo sich Khan Shodos Tochter Kherrah aufhält. Sie wird in Maraudon gefangen gehalten!\n\nEin Rettungsversuch ist sicher riskant, aber wenn Ihr die Unterstützung des Klans der Gelkis wünscht, müsst ihr die Tochter des Khans befreien.", sourceObjective = "Ihr müsst Kherrah finden, die in Maraudon gefangen gehalten wird.\n\nBereitgestellter Gegenstand:", completion = "Kann ich gefahrlos gehen, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[14332] = { id = 14332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit für eine Veränderung", description = "<Kherrah hört Euch zu, während Ihr von den vorangegangenen Ereignissen berichtet.>\n\nIch stimme den Worten des Khans der Kolkar zu. Die Zeit des uralten Zwists ist vorüber. Es ist eine Schande, dass es einer dämonischen Krise bedurfte, um die Stämme zu vereinen.\n\nIch werde zu meinem Vater zurückkehren und ihn davon überzeugen, sich Eurer Sache anzuschließen. Ich gebe Euch mein Wort, dass er einwilligen wird.\n\nKehrt zu Khan Leh'prah zurück und unterrichtet ihn darüber, dass die Gelkis bereit stehen, wenn er sie ruft.", sourceObjective = "Kherrah will, dass Ihr mit Khan Leh'prah sprecht.", completion = "Das habt Ihr gut gemacht, {race}.\n\nUnd keinen Augenblick zu früh...", sourceObjectiveStatus = "unverified-source-field" }
quests[14333] = { id = 14333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo Ihr schon mal hier seid", description = "Die Maraudine überfallen die Lager der Gelkis seit vielen Jahren. Sie rauben alles, was sie in die Finger kriegen.\n\nEine Schandtat begehen sie besonders gerne: Sie stehlen die Relikte der Macht, die den Gelkis heilig sind. Sie schaffen sie hierher, um sie zu schänden.\n\nDer Klan der Gelkis wäre sicherlich sehr dankbar, wenn Ihr diese entweihten Artefakte findet und zerstört.", sourceObjective = "Ihr sollt das Tal der Speere nach 6 entweihten Relikten absuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14334] = { id = 14334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blubberwampe", description = "Ahoi, Mann!\n\nMeint Ihr, Ihr seid in der Lage für dieses Dorf etwas zu tun?\n\nMit den meisten Walen werden wir fertig, aber dort draußen gibt es einen besonderen Wal, der zu groß für unsere Harpunen ist.\n\nBlubberwampe wird immer größer und größerer – und futtert all die Fische auf, von denen wir früher gelebt haben!\n\nBegebt Euch da raus und findet dieses Viehding - und dann lasst ihn für seine Gefräßigkeit bezahlen!", sourceObjective = "Mai'Lahii will, dass Ihr Blubberwampe tötet.", completion = "Ai, Mann! Ihr habt es geschafft!\n\nDank Euch haben wir bald wieder Frischfisch auf dem Tisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[14335] = { id = 14335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hummerplage", description = "Wie Ihr zweifelsohne bereits bemerkt habt, haben die Veränderungen dieses Landes zahlreiche Nebenwirkungen. Einige sind zum Vorteil, andere bereiten ernsthafte Probleme.\n\nGenau im Süden dieses Dorfes steigen die einheimischen Hummerstroks aus dem Meer und blockieren die Straße zum Dorf.\n\nBitte, {class}, geht und dezimiert diese Plage.", sourceObjective = "Tötet 5 Kaltschnappkriecher und 5 Kaltschnappzangen.", completion = "Ich danke Euch im Namen aller Bewohner von Schattenflucht, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14336] = { id = 14336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Töten oder getötet werden", description = "Die Riffe haben uns bisher immer vor einem Angriff vom Wasser aus bewahrt, doch die Erdbeben scheinen einen Weg für die Schiffe der Verlassenen geöffnet zu haben.\n\nSchnell, {name}. Verlangsamt die Angriffe, während ich den Rest der Miliz bereit mache.\n\nIch glaube, ich höre den Prinz und seine Männer schon gegen die Verlassenen kämpfen. Sprecht mit Liam und schaut, wo Ihr helfen könnt.\n\nOh... und achtet darauf, dass er nicht in den sicheren Tod rennt. In seinem derzeitigen Zustand ist er leider etwas tollkühn.", sourceObjective = "Sprecht mit Prinz Liam Graumähne außerhalb von Dämmerhafen.", completion = "{name}!!! Ihr seid also WIRKLICH am Leben!\n\nIch dachte, ich hätte von alten Zeiten geträumt, als ich Eure Stimme hörte…", sourceObjectiveStatus = "unverified-source-field" }
quests[14337] = { id = 14337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenflucht", description = "Da seid Ihr wieder, {class}.\n\nIch habe Neuigkeiten aus Schattenflucht. Das Dorf braucht Hilfe. Wir haben hier alle Hände voll zu tun, also muss ich Euch bitten, Euch dort hinzubegeben und ihnen zur Seite zu stehen.\n\nDas Dorf liegt an der Küste südwestlich von hier. Wenn Ihr dort eintrefft, sucht nach derjenigen, die Mai'Lahii genannt wird.", sourceObjective = "Karnum Marschenwirker will, dass Ihr mit Mai'Lahii sprecht.", completion = "Willkommen in Schattenflucht, {race}.\n\nIch war mir nicht sicher, ob der Zirkel des Cenarius jemanden schicken würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[14338] = { id = 14338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geistwandlerposten", description = "Seid gegrüßt, {class}!\n\nEs ist schön, zu sehen, dass Ihr noch atmet. Die Zeit ist gekommen, Euch um Eure Hilfe zu bitten.\n\nIm Südwesten dieser Lichtung befindet sich der Geistwandlerposten. Dort werdet Ihr einen Verlassenen mit dem Namen Maurin Knochenspalter finden.\n\nEr könnte eine Lösung für eines unser Probleme haben, denen wir hier gegenüberstehen.\n\nSprecht mit ihm und tut, was Ihr könnt, um ihm zu helfen.", sourceObjective = "Karnum Marschenwirker will, dass Ihr mit Maurin Knochenspalter sprecht.", completion = "Seid gegrüßt, {class}!\n\nEs ist gut, dass Ihr endlich hergekommen seid...", sourceObjectiveStatus = "unverified-source-field" }
quests[14339] = { id = 14339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferungsgerät", description = "Wie es das Schicksal so will, gibt es etwas Besonders zu tun – etwas, von dem der Zirkel des Cenarius ebenso profitieren wird wie ich.\n\nWisst Ihr, {class}, ich stehe unter dem Druck, ein besonderes... sagen wir 'Gebräu' herzustellen. Ich glaube, meine Arbeit ist vollbracht, aber es muss getestet werden, damit ich sicher sein kann.\n\nDie Zielobjekte dieses Tests sind die Naga, die diese Region vom Westen her bedrohen. Ihr Niedergang würde dem Zirkel sicherlich dienlich sein.\n\nAber zuerst bräuchte ich ein Lieferungsgerät. Die hohlen Hörner von sterbenden Kodos wären bestens dafür geeignet.", sourceObjective = "Maurin Knochenspalter will, dass Ihr 3 hohle Kodohörner von sterbenden Kodos sammelt.", progress = "So schnell zurück, {class}?", completion = "Jaja.\n\nDie sind bestens geeignet...", sourceObjectiveStatus = "unverified-source-field" }
quests[14340] = { id = 14340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicker Fummel", description = "Jeder muss wohl seine eigenen Erfahrungen machen, schätze ich.\n\nHier, nehmt meinen Zaubererhut. Ich zweifle nicht daran, dass er Euch als Lehrling akzeptiert, wenn Ihr der Rolle entsprechend gekleidet seid... Vielleicht müsst Ihr auch erst noch ein paar seiner Mätzchen mitmachen. Und mit Mätzchen meine ich unangenehme, fiese und tödliche Mätzchen.\n\nIhr solltet ein Abbild von Xylem auf der Spitze dieses Hügels im Nordosten antreffen.", sourceObjective = "Setzt Euren neuen Zaubererhut auf und dann sprecht mit dem Abbild von Erzmagier Xylem nordöstlich des Nördlichen Umschlagplatzes der Raketenbahn.", progress = "Hallo.", completion = "Na, schaut Euch mal an. Seid Ihr nicht ein Wunder des modernen Magiertums! Ziemlich schick muss ich sagen.\n\nLehrlinge? Lehrlingse! Ich glaube, dass ich bereits ziemlich viele habe, aber ich nehme an, dass man nie ZU viele Lehrling...se haben kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[14341] = { id = 14341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smeeds Harnische", description = "Verzeiht, {race}.\n\nIch brauche ein wenig Hilfe. Ich habe gerade eine Bestellung für Harnische fertiggestellt, die sofort ausgeliefert werden muss.\n\nIch bin ein bisschen zu alt für diese Ausflüge, besonders wenn man bedenkt, wie gefährlich es in dieser Gegend in letzter Zeit geworden ist.\n\nWäret Ihr so nett?\n\nSie gehen an Smeed, einen Goblin, der gerade südöstlich von hier lebt.", sourceObjective = "Nataka im Geistwandlerposten will, dass Ihr Smeeds Harnische an Smeed ausliefert.\n\nBereitgestellter Gegenstand:", completion = "Ahh, meine Harnische!\n\nHabt Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[14342] = { id = 14342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllische Übergriffe", description = "Die Dämonen sind unterwegs, {race}!\n\nWenn nichts getan wird, werden wir in ein paar Wochen überrannt. Ich bin gerade vom Zirkel der Mannoroc zurückgekehrt, wo es Höllenbestien vom Himmel regnet!\n\nWir müssen zumindest ein wenig Zeit gewinnen. Begebt Euch dorthin und macht weiter, wo ich aufgehört habe!", sourceObjective = "Felgur Zweischneid will, dass Ihr 10 niedere Höllenbestien vernichtet.", completion = "Gut gemacht, {race}!\n\nDie Gefahr besteht weiter, aber ihr habt uns ein wenig Zeit verschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[14343] = { id = 14343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maurins Gebräu", description = "<Maurin versiegelt sorgfältig die hohlen Kodohörner, in denen sich sein Gebräu befindet.>\n\nBitte sehr, {class}.\n\nBringt sie zu Karnum. Es ist seine Sache, wie er es sie gegen die Naga einsetzen will. \n\nIch werde zusehen, um die Wirkungskraft meiner Formel zu beobachten!", sourceObjective = "Maurin will, dass Ihr Maurins Gebräu zu Karnum in Karnums Hain bringt.\n\nBereitgestellter Gegenstand:", completion = "Ich verabscheue es, solch unnatürliche Maßnahmen zu ergreifen, aber ich befürchte, dass wir einfach keine andere Wahl haben...", sourceObjectiveStatus = "unverified-source-field" }
quests[14344] = { id = 14344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jugkars Verderben", description = "Ihr erkennt hierin die Essenz eines beschworenen Dämons.\n\nGefährliche und unerklärliche Energien treten aus der Oberfläche und schlängeln sich wieder hinein.\n\nWährend Ihr es anstarrt, erfüllt eine Vision Euren Geist – ein Bild von Euch, wie Ihr dämonischen Dienern gebietet. Ein Anflug der Erregung überkommt Euch, als Ihr Euch vorstellt, über so eine Macht zu verfügen.\n\nIhr seht Euch um und fragt Euch, wie dieser Schatz gegen die dämonischen Feinde eingesetzt werden könnte...", sourceObjective = "Ihr seid dazu auserkoren, den höllischen Kern der Macht zu verwenden, um an Jugkars Altar die Herrschaft über Lord Azrethoc zu übernehmen und mit dessen Kräften Jugkar Grimm'rod zu vernichten.", completion = "Ihr solltet stolz darauf sein, wie Ihr die Kräfte des Feindes gegen sie eingesetzt habt.\n\nIhr habt den Dämonen von Mannroc einen schweren Schlag zugefügt...", sourceObjectiveStatus = "unverified-source-field" }
quests[14345] = { id = 14345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waschtag", description = "Köstlich!\n\nAzy versucht immer, magische Artefakte in die Finger zu bekommen. Er sagt, er hat versucht, sich mit diesem Erzmagier anzufreunden. Xylem!\n\nXylem hat SEHR viele Lehrlinge. Er nimmt alle möglichen bei sich auf, verschleißt sie und lässt sie überall herumlaufen. Hohe Fluktuation.\n\nDer letzte ging letzte Nacht. Er ging in Richtung dieser großen Goblinturmkonstruktion tief im Westen. Vielleicht kann er Euch helfen, Xylem zu treffen? Vielleicht weiß Xylem, wo Azy ist?\n\nBenehmt Euch!", sourceObjective = "Sprecht mit Sorata Feuerspinner am Nördlichen Umschlagplatz der Raketenbahn.", completion = "Seht, Kumpel, vor ein paar Wochen war ich an Eurer Stelle. Der große, mächtige Erzmagier nimmt tatsächlich Lehrlinge auf! Wer würde so eine Gelegenheit verpassen wollen?!\n\nManchmal sind die Dinge einfach zu schön, um wahr zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[14346] = { id = 14346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säubert unseren Riss", description = "Wie Ihr sicher wisst, {name}, sind die Naga weiterhin eine ernsthafte Bedrohung für dieses Gebiet. Die Zeit ist gekommen, dass wir sie zurück ins Meer treiben!\n\nWenn Ihr bereit seid, wird Euch Grimmfeder zur Spalte bringen, wo sie einen brutalen Angriff vorbereiten. Sobald Ihr dort seid, verwendet Maurins Gebräu, um ihnen eine Lektion zu erteilen, die sie nicht so schnell vergessen sollen.", sourceObjective = "Karnum Marschenwirker will, dass Ihr Maurins Gebräu verwendet, um 10 Eindringlinge der Zackenkämme, 10 Sirenen der Zackenkämme und 3 Meeresriesen zu töten.", progress = "Habt Ihr Euch um die Naga in unserer Spalte gekümmert, {name}?", completion = "Eure Taten beindrucken mich immer mehr, {name}.\n\nBitte nehmt dieses Geschenk im Namen des Zirkels des Cenarius entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14347] = { id = 14347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleibt standhaft", description = "{name}! Ich bin mir nicht sicher, ob Ihr lebendig oder tot seid… Mensch oder Worgen…\n\nIch bin mir nicht einmal sicher, ob ich wache oder träume. Aber EINER Sache bin ich sicher…\n\nWir werden einen ganzen Haufen dieser mutterlosen Verlassenen töten.", sourceObjective = "Tötet 10 Eindringlinge der Verlassenen.", completion = "Ja, {name}! Genau wie in alten Zeiten…\n\nIch muss mich sehr zurückhalten, um Euch nicht zu erschießen, aber Krennan hat uns alles erklärt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14348] = { id = 14348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr schafft sie nicht alleine", description = "Schaut her, {name}. Die besonders großen, massigen, auch Monstrositäten genannt, sind nicht so leicht zu bezwingen. Versucht also nicht, alleine mit ihnen fertigzuwerden.\n\nAber ich habe eine Idee, die so verrückt ist, dass sie tatsächlich funktionieren könnte. Sie könnte allerdings auch Euren Tod bedeuten, wenn wir nicht vorsichtig genug sind.\n\nHinter den Schuppen und in der Nähe der Windmühlen liegen einige Fässer mit Sprengpulver. Schnappt sie Euch und werft sie den Monstrositäten direkt an den Kopf. Den Rest erledige ich mit meiner treuen alten Donnerbüchse.", sourceObjective = "Jagt mit den Schwarzpulverfässern 4 entsetzliche Monstrositäten in die Luft.", completion = "Ihr und ich, {name}. Wir sind ein tolles Team…\n\nEs ist schön, dass Ihr wieder da seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[14349] = { id = 14349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Befehl", description = "Der Befehl ist gekommen, {class}. Sylvanas selbst hat verlangt, dass ich meine 'tüchtigsten' Agenten auf eine höchst diffizile taktische Mission nach Unterstadt schicke.\n\nLeider wurden meine tüchtigsten Agenten alle vor drei Jahren getötet. An ihrer Stelle habe ich eine Bande hirntoter Trottel.\n\n<Nathanos schaut Euch kalt an.>\n\nReist sofort nach Unterstadt und erstattet der Dunklen Fürstin Bericht. Macht mir keine Schande, {class}!", sourceObjective = "Reist nach Unterstadt und sprecht mit Fürstin Sylvanas Windläufer.", sourceObjectiveStatus = "unverified-source-field" }
quests[14350] = { id = 14350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Purpurrote Kurier", description = "Wir können die Oberbefehlshaber des Scharlachroten Kreuzzugs nicht direkt angreifen; sie verfügen über eine zu gute Verteidigung. Aber bekanntlich führen viele Wege zum Ziel. Ohne ihre Hauptstreitkraft sind sie hilflos.\n\nMeine Todespirscher haben Daten über die Aktivitäten des Kreuzzugs außerhalb von Stratholme gesammelt. Jeden Tag wird ein Bericht aus ihrer Befehlszentrale nach Tyrs Hand geschickt. Dieser Bericht ist der Schlüssel, {race}! Sucht den Purpurroten Kurier und beschafft diesen Bericht. Bringt ihn zu Nathanos.", sourceObjective = "Kehrt in die Östlichen Pestländer zurück und spürt den Purpurroten Kurier auf. Tötet den Kurier und schnappt Euch den Befehl des Obersten Kreuzfahrers.\n\nBringt den Befehl zu Nathanos Pestrufer und wartet auf weitere Anweisungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14351] = { id = 14351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf um das Hügelland", description = "Da Ihr mit solcher Verbissenheit und Ehre in der Schlacht des Hügellands gekämpft habt, habe ich für Euch diese Belobigung geschrieben, in der Eure Heldentaten im Kampf angemessen gerühmt werden, sodass das Oberkommando sie anerkennt.\n\nBringt die versiegelte Belobigung zu Bragor Blutfaust nach Unterstadt. Geht erhobenen Hauptes, {class}.", sourceObjective = "Bringt Darthalias versiegelte Belobigung zu Bragor Blutfaust nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14352] = { id = 14352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unheilige Allianz", description = "Mylady,\n\nIhr wisst sehr genau, was wir Euch anbieten. Die Gelegenheit, das Brachland und das dahinter liegende Gebiet zu erobern, ist nicht zu verachten. Wir verlangen dafür nur Eure Hilfe. Mit Hilfe meinen wir nicht weniger, als dass Ihr uns die Freiheit zugesteht, in dem Gebiet aktiv zu werden.\n\nErlaubt uns bitte, dies weiter auszuführen. Wir haben große Macht und sind gewillt, sie mit jenen zu teilen, die weise genug sind, sich uns anzuschließen. Ich werde mich bis auf Weiteres abseits der Hügel der Klingenhauer aufhalten.\n\nHochachtungsvoll,\nBotschafter Malcin", sourceObjective = "Bringt die kleine Rolle zu Bragor Blutfaust nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14353] = { id = 14353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unheilige Allianz", description = "Angeblich hält sich dieser Malcin außerhalb der Hügel der Klingenhauer auf. Keine Frage - er muss sterben.\n\nMeine Kontakte in Orgrimmar erzählen mir, dass ihre Späher dort unten Anzeichen der Seuche gefunden haben. Die Stacheleber weisen auch Anzeichen einer Verseuchung auf und sie sind um einiges stärker. Was auch immer die Geißel dort unten unternimmt, muss ein Ende haben. Jetzt sofort.\n\nFindet diesen Malcin und schaltet ihn aus. Meldet Euch wieder bei mir, sobald er tot ist.", sourceObjective = "Bringt den Kopf von Botschafter Malcin zu Bragor Blutfaust nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14354] = { id = 14354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Gaben", description = "Einfach unerträglich!\n\nAusgerechnet Satyrn entweihen unser geheiligtes Land...\n\nIhre Tage sind gezählt, {race}. Das lasst Euch gesagt sein. Sobald wir wissen, wie viele es sind, werde ich ein Kommando anführen, welches das Land von diesen niederträchtigen Kreaturen befreit.\n\nAber bis dahin könntet Ihr vielleicht meiner Seele zu ein wenig mehr Frieden verhelfen?\n\nReist von hier nach Osten zu Sargeron und durchsucht die Ruinen. Findet die Relikte von Elune und versichert Euch, dass sie in gutem Zustand sind.\n\nIch werde Euch für diesen Dienst großzügig belohnen.", sourceObjective = "Besucht Elunes Relikte in Sargeron.", completion = "Die Relikte sind unbeschädigt! Das ist wirklich erfreulich.\n\nIhr habt meine innere Ruhe wieder hergestellt, {race}. Bitte nehmt dies als mein Geschenk an Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[14355] = { id = 14355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In das Scharlachrote Kloster", description = "Eine meiner Aufgaben, während ich hier stationiert bin, ist es, den Verlassenen dabei zu helfen, ihre Grenzen zu überwachen – und das ist exakt das, was Ihr, {class}, für mich erledigen werdet.\n\nIch mag am Leben sein, doch ist der Scharlachrote Kreuzzug bereit, meine Leute genauso schnell niederzumähen wie einen der Untoten. Sie sind ein Problem hier, ein großes sogar, und Ihr werdet etwas dagegen unternehmen.\n\nGeht zum Kloster und erschlagt Hochinquisitorin Weißsträhne und ihre Offiziere.", sourceObjective = "Tötet Hochinquisitorin Weißsträhne, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Bragor Blutfaust in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14356] = { id = 14356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht zu Zerstören...", description = "Zugehört, {class}.\n\nIhr mögt vielleicht nichts davon wissen, aber Orgrimmar hat ein Problem. Tief im Flammenschlund treibt eine Sekte des Schattenrats, die sich 'Die Sengende Klinge' nennt, ihr Unwesen. Es sind hauptsächlich Orcs und ich kann vertrauliche Informationen nicht in die Hände der Grunzer dort legen. Hier kommt Ihr ins Spiel.\n\nSie sollten zwei Bücher in ihrem Besitz haben. Ich möchte sie weder der Sengenden Klinge noch den Verlassenen überlassen. Bringt sie direkt zu mir.", sourceObjective = "Bringt die Bücher 'Schattenzauber' und 'Zauberformeln aus dem Nether' zu Bragor Blutfaust nach Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14357] = { id = 14357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu den Waffen!", description = "Elunes Dienstmaid! Sie ist noch prächtiger als es in den Geschichten erzählt wird.\n\nDie Legenden, die dieses Relikt umgeben, kommen Euch in den Sinn, als Ihr Euch nähert:\n\nIn uralten Zeiten nach dem Krieg wurden die Waffen der Feinde dem Becken dargeboten im Austausch für eine Art göttliche Gabe.\n\nAls Ihr über das Ritual nachdenkt, bemerkt Ihr das Funkeln von Stahl in einem nahegelegenen Waffenregal...", sourceObjective = "Besorgt 20 Satyrsäbel aus dem Waffenregal und von den Satyrn aus der Gegend.", progress = "Die Statue steht dort erwartungsvoll.", completion = "Als Ihr das Ritual abgeschlossen habt, empfangt Ihr eine göttliche Gabe.\n\nIhr könnt Euch des Gefühls nicht erwehren, dass Euch eine große Ehre zuteil geworden ist, als Ihr den Segen Elunes erhaltet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14358] = { id = 14358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zehn Pfund Fleisch", description = "Alten Legenden zufolge wurde dieses uralte Kohlenbecken hier aufgestellt, um Opferrituale durchzuführen.\n\nSoweit Ihr Euch erinnern könnt, besagen die Geschichten, dass derjenige gesegnet wird, der das Fleisch von Elunes Feinden auf die brennenden Glutspäne im Kohlenbecken legt.\n\nIhr seht Euch um und beschließt, dass die Satyrn, welche die Region derzeit beherrschen, sicherlich als Feinde bezeichnet werden könnten.", sourceObjective = "Beschafft 10 Stücke Satyrfleisch von den zahlreichen Satyrn in Sargeron.", progress = "Das Becken erwartet still eine Opfergabe.", completion = "Das göttliche Becken versieht Euch gnädig mit einem Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14359] = { id = 14359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen von oben", description = "Ihr spürte eine tiefe Verbindung zu längst vergangenen Zeiten, nachdem Ihr den uralten Segen von diesem Relikt empfangen habt.\n\nIhr seid entschlossen, so viel Nutzen wie möglich aus dieser göttlichen Gabe zu ziehen.", sourceObjective = "Ihr müsst 10 Stücke Satyrfleisch von den zahlreichen Satyrn in Sargeron beschaffen und sie in Elunes Kohlenbecken legen.", progress = "Das Becken erwartet still eine Opfergabe.", completion = "Das göttliche Becken versieht Euch gnädig mit einem Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14360] = { id = 14360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nichts, was ein paar Melonen nicht richten können", description = "Die Markierungen der Ruinen von Sargeron in Kombination mit den Informationen aus Furiens Text lassen lassen in einer Sache keine Zweifel:\n\nMit dem Brunnen im Heiligtum von Elune hat es etwas ganz Besonderes auf sich.\n\nEs scheint, dass er einem besondere Kräfte verleiht, wenn man sein Gesicht in seinem Wasser wäscht. Als erstes muss es im uralten Brunnen natürlich etwas geben, mit dem man sich waschen kann.\n\nWährend Ihr über dieses Problem nachdenkt, bemerkt Ihr eine Melone an den Wurzeln eines Baumes...", sourceObjective = "Ihr müsst 8 Melonenfrüchte sammeln und ihren Saft in den Kelch von Elune in Sargeron pressen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14361] = { id = 14361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenfrieden", description = "Unser Lager hat die Aufgabe, mögliche Widersacher zu beobachten. Sobald die Allianz ihren Desolace-Feldzug startet, wird unsere Arbeit hier sicherstellen, dass es keine Überraschungen geben wird.\n\nKürzlich wurde einer unserer Späher gefangen genommen und von der Brennenden Klinge in ihrem Stützpunkt im Westen geopfert. Seitdem werden wir von einem Schuft der Brennenden Klinge bedroht und gepiesackt. Sein Name ist Kohor.\n\nIhre Tage sind gezählt, aber ich werde denjenigen großzügig belohnen, der ihn jetzt zum Schweigen bringt!", sourceObjective = "Tötet Kohor.", completion = "Es ist vollbracht.\n\nHauptmann Pentigast sollte nun in Frieden ruhen, jetzt wo Kohor mit seinen Drohungen zum Schweigen gebracht wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[14362] = { id = 14362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Satz heiße Ohren", description = "Hauptmann Pentigast hat kein Geheimnis aus seiner Verachtung gegenüber der Brennenden Klinge in Festung Donneraxt gemacht.\n\nSicherlich würde ein Beweis ihres Dahinscheidens für ihn von großem Wert sein.", sourceObjective = "Sammelt 25 Ohren von Mitgliedern der Brennenden Klinge.", progress = "Was habt Ihr da, {class}?", completion = "Ohren der Brennenden Klinge?\n\n<Hauptmann Pentigast lächelt.>\n\nGute Arbeit, {class}. Dies ist nur eine Vorahnung von dem, was aus dem gesamten, ekelhaften Kult wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[14363] = { id = 14363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr erkennt es, wenn Ihr es seht", description = "Mit seinen letzten Atemzügen erwähnte Kohor die Beschwörung eines Dämons, der das gesamte Gebiet bedrohen könnte.\n\nVielleicht war das ein Täuschungsversuch, aber das Risiko kann nicht eingegangen werden.\n\nDies kann nicht bis zum Einfall der Allianz in Desolace warten. Ihr müsst die Festung Donneraxt nach Hinweisen durchsuchen und dieser möglichen Gefahr ein Ende setzen.", sourceObjective = "Findet das uralte Beschwörungsritual in der Festung Donneraxt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14364] = { id = 14364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Köpfe zusammenstecken", description = "Es stimmt also...\n\nDas Pergament, das Ihr in der Festung Donneraxt gefunden habt, beschreibt ein mächtiges Beschwörungsritual. Eines das stärker ist als alle anderen, von denen wir wissen, dass die Brennende Klinge sie besitzt.\n\nDieses Ritual muss selbstverständlich unterbrochen werden, koste es, was es wolle!\n\nWenn diese Dämonen vorzeitig beschworen würden, könnte die Krise abgewendet werden.", sourceObjective = "Sammelt 100 gebleichte Schädel aus der Festung Donneraxt, stapelt sie am Beschwörungszirkel der Brennenden Klinge auf und tötet dann Nazargen.", completion = "Ihr habt eine schlimme Krise abwenden können, {class}.\n\nWenn diese Beschwörung noch ein wenig länger hinausgezögert worden wäre, wäre der Dämon viel zu mächtig für unsere kleine Streitmacht geworden.\n\nBitte nehmt dieses Geschenk zum Dank für Eure Dienste an.", sourceObjectiveStatus = "unverified-source-field" }
quests[14365] = { id = 14365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ethel Rethor", description = "Wir haben kürzlich ein Hilfegesuch von einer Forscherin des Zirkels des Cenarius erhalten.\n\nZurzeit können wir niemanden entbehren. Deshalb bitte ich Euch, ihr in unserem Namen einen Besuch abzustatten.\n\nKorrah befindet sich in der Nähe der Ruinen des Turms von Ethel Rethor an der Küste im Westen.", sourceObjective = "Korporal Melkins will, dass Ihr mit Korrah in Ethel Rethor sprecht.", completion = "Es ist gut, dass Ihr gekommen seid.\n\nHier lauert eine große Gefahr.", sourceObjectiveStatus = "unverified-source-field" }
quests[14366] = { id = 14366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durchhalten", description = "Ab hier schaffen wir es alleine, {name}. Schaut Ihr nach Bürgermeisterin Armstead.\n\nDies hier ist nur ein kleiner Teil der Streitkräfte der Verlassenen. Wenn wir nicht schnell handeln, werden wir bald noch größeren Problemen gegenüberstehen.\n\nSchaut, was Ihr tun könnt, um Euch der Armee der Verlassenen an ihrem Anlegeplatz zu stellen.", sourceObjective = "Sprecht mit Gwen Armstead in Dämmerhafen.", completion = "Gute Nachrichten, {name}. Ich habe die verbleibenden Milizen an die Küste geschickt, damit sie der Streitmacht der Verlassenen direkt gegenübertreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14367] = { id = 14367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allens Sturmkeller", description = "Lord Godfrey führt den Angriff auf die Verlassenen in der Nähe ihres Anlegeplatzes an. Schaut, wie Ihr ihm dabei helfen könnt, die Verlassenen zurückzuhalten.\n\nIch habe gehört, dass Godfrey den Sturmkeller in Allens Bauernhof weit im Westen unter sein Kommando gebracht hat. Sucht ihn dort.", sourceObjective = "Sprecht mit Lord Godfrey im Sturmkeller von Allens Bauernhof in Gilneas.", completion = "Die Verlassenen sind hier und es sind viele, {name}. Wir haben kaum genug Männer, um sie zurückzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14368] = { id = 14368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Kinder!", description = "Die Soldaten lassen mich nicht aus dem Keller, aber meine Kinder sind noch auf dem Bauernhof! Bitte, Ihr müsst sie finden.\n\nDie Verlassenen haben kein Mitgefühl mit den Unschuldigen. Meine Kinder sind in großer Gefahr!\n\nSie heißen Cynthia, Ashley und James. Wenn Ihr sie findet, bringt sie hierher. Ich stünde auf ewig in Eurer Schuld.", sourceObjective = "Rettet Cynthia, Ashley und James in Hammonds Bauernhof.", completion = "Meine Kinder sind in Sicherheit! Ihr habt etwas Wundervolles getan, {name}. Ich weiß nicht, wie ich Euch danken soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[14369] = { id = 14369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfesselt die Bestie", description = "Ich werde Euch nicht belügen, {name}. Der Gedanke, einen Worgen in unseren Reihen zu haben, gefällt mir ganz und gar nicht.\n\nWer weiß schon, wie lange Krennans Gebräu anhält und wann Ihr versuchen werdet, einem von uns den Kopf abzubeißen?\n\nAber bis dahin können wir uns Eure Wildheit zunutze machen.\n\nGeht hinaus auf das Schlachtfeld und tötet so viele dieser Verlassenen, wie Ihr könnt, und zwar so brutal, wie Ihr könnt.\n\nWir werden ihnen schon beibringen, die Worgen zu fürchten, {name}.", sourceObjective = "Tötet 8 Fußsoldaten der Verlassenen oder Seeleute der Verlassenen.", completion = "Nicht schlecht, {name}. Gut, dass Ihr auf unserer Seite steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[14370] = { id = 14370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rätselhafter Azsharit", description = "Azsharit! Aus dieser rätselhaften Kristallsubstanz wurden Waffen mit teuflischer Macht geschmiedet, aber wir haben entdeckt, dass sie in unseren Händen in der Lage ist, gewaltige Kraftmengen zu bündeln. Das könnte die größte Entdeckung der Goblins seit dem Kaja'mit sein.\n\nAber was ist es? Wo kommt es her? Warum gibt es das nur hier? Die Wissenschaft verlangt nach einer Antwort! Ich brauche weitere Proben für meine Forschungen. Sucht nach Azsharitvorkommen an den nahegelegenen Klippen.", sourceObjective = "Sammelt 5 Azsharitproben an den nahegelegenen Klippen.", progress = "Habt Ihr weitere Proben gesammelt? Die gedankenlosen Abenteurer sammeln dieses Zeug schon seit Jahren, ohne zu wissen, wie wertvoll es ist!", completion = "Ah, hervorragend. Einige der Proben sehen frisch aus. Ich kann mich jetzt bis über beide Ohren in dem Zeug vergraben, um dieses Rätsel zu lösen!", sourceObjectiveStatus = "unverified-source-field" }
quests[14371] = { id = 14371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Riesenimbiss", description = "Während Ihr an den Klippen herumklettert, könnt Ihr mir vielleicht bei einer weiteren Untersuchung helfen. Die Riesen, die an diesen Klippen entlangwandern, sind hier, seit die Berge entstanden. Vielleicht wissen sie, wo der Azsharit herkommt? Es liegt sehr in unserem Interesse, uns mit diesen Riesen gut zu stellen und es herauszufinden.\n\nSammelt ein gigantisches Mahl für mich - als Friedensangebot! Tötet die Nebelschwingenkliffbewohner, die unsere Forschungen so stark behindern, und sammelt ihre Kadaver für mich ein.", sourceObjective = "Sammelt 8 verstümmelte Nebelschwingenkadaver von Nebelschwingenkliffbewohnern.", progress = "Ich hätte Euch vermutlich vorwarnen sollen, dass diese Nebelschwingenschimären Blitze schleudern können.", completion = "Puh! Was für ein Gestank! Nun, hoffentlich riecht der Kadaverhaufen für die Riesen appetitlicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[14372] = { id = 14372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thargads Lager", description = "Es ist schön, zu sehen, dass Ihr noch atmet, {class}. Mir ist zu Ohren gekommen, dass die Aktivitäten der Dämonen im Süden zunehmen.\n\nDort gibt es ein Lager im Grenzgebiet, das Gefahr läuft, durch die Bewegungen der Dämonen Richtung Norden abgeschnitten zu werden.\n\nVielleicht könnt Ihr ihnen ein wenig zur Hand gehen?\n\nIch weiß, dass der Anführer des Lagers Thargad heißt. Er wird Euch sicher kluge Anweisungen geben können.\n\nHabt Dank, <Freund/Freundin>. Gehabt Euch wohl.", sourceObjective = "Karnum Marschenwirker will, dass Ihr mit Thargad sprecht.", completion = "Dämonen?\n\nIch kann Euch viel über Dämonen erzählen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14373] = { id = 14373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllische Übergriffe", description = "Hört mal gut zu. Und seht her.\n\n<Thargad zeigt in den Osten.>\n\nIhr seht die großen, grünen, glühenden Feuerbälle vom Himmel regnen?\n\nDas ist ein ganzer Haufen dieser hässlichen Dämonen, welche die Länder ungehindert durchstreifen. Nun, praktisch ungehindert... Ich habe sie ein wenig auf Trab gehalten und ihnen einen Denkzettel verpasst.\n\nWie wär's, wenn Ihr mal bei ihnen vorbeischaut und dort weitermacht, wo ich aufgehört habe?", sourceObjective = "Tötet 10 niedere Höllenbestien.", completion = "Gut, Jungchen!\n\nZögert nicht, noch ein paar weitere zusätzlich aus den Socken zu hauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14374] = { id = 14374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portale der Legion", description = "Hier ist sie - die Hand von Iruxos.\n\nHab sie mir selbst von einem der Anführer der Brennenden Klinge geholt.\n\nMächtiges Ding! Wisst Ihr, man benutzt sie mit Dämonenportalen und sie verschwinden einfach! Unheimliche Magie, aber wir leben in schweren Zeiten...\n\nWenn die Dämonen weiter in diesen Zahlen hier auftauchen, wird mein Lager überlaufen, bevor ich mich wehren kann.\n\nDa habt Ihr sie. Und jetzt beeilt Euch.", sourceObjective = "Verbannt 6 Portale beim Zirkel des Mannoroc.", completion = "Ja, das wird uns etwas Zeit verschaffen, {class}.\n\nIch danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[14375] = { id = 14375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Hoffnung auf Menschlichkeit", sourceObjective = "Ich muss Euch irgendwie durchkriegen, {name}. Diese Dosis ist stark genug, um ein Pferd zu töten.\n\nAber ich kenne Euch. Ich weiß, aus welchem Holz Ihr geschnitzt seid. Ihr werdet es schon schaffen.\n\nVertraut mir. Ich weiß genau, was Ihr durchmacht.\n\nJetzt trinkt leer und schließt Eure Augen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14376] = { id = 14376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jugkars Verderben", description = "Ihr erkennt hierin die Essenz eines beschworenen Dämons.\n\nGefährliche und unerklärliche Energien treten aus der Oberfläche und schlängeln sich wieder hinein.\n\nWährend Ihr es anstarrt, erfüllt eine Vision Euren Geist – ein Bild von Euch, wie Ihr dämonischen Dienern gebietet. Ein Anflug der Erregung überkommt Euch, als Ihr Euch vorstellt, über so eine Macht zu verfügen.\n\nIhr seht Euch um und fragt Euch, wie dieser Schatz gegen die dämonischen Feinde eingesetzt werden könnte...", sourceObjective = "Ihr seid dazu auserkoren, den höllischen Kraftkern zu verwenden, um an Jugkars Altar die Herrschaft über Lord Azrethoc zu übernehmen und mit dessen Kräften Jugkar Grimm'rod zu vernichten.", completion = "Ihr solltet stolz darauf sein, wie Ihr die Kräfte des Feindes gegen sie verwendet habt.\n\nIhr habt den Dämonen von Mannroc einen schweren Schlag zugefügt...", sourceObjectiveStatus = "unverified-source-field" }
quests[14377] = { id = 14377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Freund der Riesen", description = "Eine oberflächliche Untersuchung des Azsharits, das Ihr mir gebracht habt, lässt erkennen, dass es weder biologischen Ursprungs ist noch sich auf natürliche Weise gebildet hat. Es gibt eine weitere Kreatur in Azshara mit ähnlichen Eigenschaften: die Klippenriesen, die über diese Klippen stapfen.\n\nEiner der Riesen scheint willens zu sein, uns bei unseren Forschungen zu unterstützen. Bringt das Fleisch, dass Ihr gesammelt habt, zu Gormungan, dem Riesen, der genau westlich von hier steht. Freundet Euch mit ihm an, dann fühlt ihm auf den Zahn. Findet heraus, ob er etwas über das Geheimnis des Azsharits weiß.", sourceObjective = "Sprecht mit Gormungan außerhalb der Südlichen Endhaltestelle der Raketenbahn und entlockt ihm das Geheimnis des Azsharits.", completion = "Sprecht langsamer. Was habt Ihr zu sagen? Höre ich recht? Azsharit bildet sich dort, wo die Riesen... Oje. Ekelhaft!! Erzählen wir das besser nicht Dr. Wurfhammer. Er hat sein Leben diesem Zeug gewidmet.\n\nNun, zumindest wissen wir jetzt, wo Azsharit herkommt und warum er so selten ist. Wir müssen herausfinden, wie wir die... 'Produktion' beschleunigen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[14378] = { id = 14378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Jagd nach Brendol", description = "Ich bin zu beschäftigt, um Artefakte oder irgendetwas anderes zu sammeln, aber es gibt eine kleine Sache hier, die ich gerne klären würde.\n\nEin Apotheker der Verlassenen stöbert schon seit einer Weile in der Gegend herum. Normalerweise würde ich ihn ignorieren, aber er hat sich schon dreimal in mein Lager geschlichen und meine Vorräte geplündert... Was zu viel ist, ist zu viel!\n\nFindet den Dieb und bringt mir das, was von meinen Sachen übrig ist!", sourceObjective = "Beschafft Brendols Beutel.", progress = "Nun, {class}? Habt Ihr den Idioten gefunden?", completion = "Der Gerechtigkeit wurde genüge getan!\n\nJetzt schauen wir uns an, was von meinen Sachen übrig ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[14379] = { id = 14379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hummerstroks!", description = "Thargad jagt praktisch ununterbrochen nach den uralten Relikten der Titanen. Er ist so darin vertieft, dass er vermutlich vergessen würde zu essen, wenn ich ihn nicht daran erinnern würde!\n\nWo wir vom Essen sprechen: Ich würde ihm gerne etwas Besonderes zubereiten. Vielleicht könnt Ihr mir dabei helfen?\n\nEntlang der Küste im Westen krabbeln Hummerstroks herum. Einen Kampf gegen sie könnte ich niemals bestehen, aber ich könnte ein fantastisches Mahl herrichten, wenn Ihr mir ein paar ihrer Schwänze brächtet.", sourceObjective = "Beschafft 7 zarte Hummerstrokschwänze.", progress = "Habt Ihr die Hummerstrokschwänze mitgebracht, {race}?", completion = "Ohhh, damit wird es wunderbar!\n\nThargad wird ja so überrascht sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[14380] = { id = 14380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bedeutsame Entdeckung", description = "<Thargad durchsucht den Ranzen und zieht ein merkwürdiges Objekt heraus.>\n\nAha, das ist seltsam... Das ist ein hohles Kodohorn mit einer Art Trank darin.\n\n<Thargad schnuppert an dem Trank.>\n\nIIH! Eindeutig kein Gesundheitselixier. Dies dient nur einem Zwecke: dem Töten.\n\nWie wäre es, wenn wir es zu Karnum bringen und schauen, ob er etwas damit anfangen kann...", sourceObjective = "Bringt das mysteriöse Gebräu zu Karnum auf Karnums Lichtung.\n\nBereitgestellter Gegenstand:", completion = "<Karnum untersucht das Gebräu.>\n\nJa, {class}. Ich weiß nicht nur, was das ist. Ich weiß auch, was Ihr damit anstellen solltet...", sourceObjectiveStatus = "unverified-source-field" }
quests[14381] = { id = 14381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säubert unseren Riss", description = "Ich erkenne diese üble Erfindung. Es ist eine schreckliche Krankheit, die beinahe sofort tötet – und zwar auf brutalste Weise. So sehr ich es auch verabscheue, so ein Mittel einzusetzen, ich fürchte, wir haben keine Wahl.\n\nWie Ihr sicher wisst, sind die Naga weiterhin eine ernsthafte Bedrohung für dieses Gebiet. Die Zeit ist gekommen, sie zurück ins Meer zu treiben!\n\nWenn Ihr bereit seid, wird Euch Grimmfeder zum Riss bringen, wo sie einen brutalen Angriff vorbereiten.\n\nSetzt das Gebräu gegen die Naga und ihren Verbündeten ein, um Desolace wieder sicher zu machen!", sourceObjective = "Verwendet Maurins Gebräu, um 10 Eindringlinge der Zackenkämme, 10 Sirenen der Zackenkämme und 3 Meeresriesen zu töten.", progress = "Habt Ihr Euch um die Naga in unserem Riss gekümmert, {name}?", completion = "Eure Taten beindrucken mich immer mehr, {name}.\n\nBitte nehmt dieses Geschenk im Namen des Zirkels des Cenarius entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14382] = { id = 14382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nimm mich mit, Kapitän, auf die Reise", description = "Die Katapulte der Verlassenen machen uns ganz schön zu schaffen, {name}. Und selbst wenn wir ihrer Herr würden, stehen da noch zwei Schiffe mit zwei Reihen Kanonen.\n\nIch habe jedoch einen Plan, mit dem wir zwei Fliegen mit einer Klappe schlagen. Ihr seid bei diesem Plan die Klappe.\n\nBeseitigt die Maschinisten an den Katapulten. Nutzt danach die Katapulte, um Euch selbst an Bord der Schiffe der Verlassenen zu katapultieren.\n\nWenn Ihr nicht gerade komplett daneben zielt, solltet Ihr sicher landen. Sobald Ihr an Bord seid, geht unter Deck und erledigt den Kapitän jedes Schiffes. Viel Erfolg, {class}.", sourceObjective = "Benutzt die Katapulte der Verlassenen, um auf die Schiffe zu gelangen und tötet Kapitän Morris und Kapitän Anson.", completion = "Gut gemacht, {name}. Ihr seid vielleicht eine blutrünstige Bestie, aber Ihr seid unsere Bestie.", sourceObjectiveStatus = "unverified-source-field" }
quests[14383] = { id = 14383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die tobenden Tüftler der Verfallenen Gegenden", description = "Halunken! Ungläubige! Seit ich meine Arbeit hier in Azshara aufgenommen habe, haben die Federdings meine Experimente behindert und meine Forschungen sabotiert. Und jetzt ist ihnen eine Bande von mittelmäßigen, zweitklassigen Tüftlern zu Hilfe geeilt! Ich habe mich dringenden Geschäften zuzuwenden. Kümmert Euch darum, dass diese Gnome für immer erledigt werden.\n\nBegebt Euch in die Verfallenen Gegenden an der Küste südlich meines Geheimlabors und lasst ihre überdimensionierten Köpfe für mich rollen.", sourceObjective = "Tötet Bingham Federdings in den Verfallenen Gegenden und dazu 4 Netzgewehrgnome und 6 Britzelgnome.", completion = "Oh - fabelhaft. Erzählt mir mehr. Und dieser altkluge junge Federdings? Auch tot? Ah, wunderbar. Meine Arbeit hier ist sehr wichtig, aber manchmal vermisse ich das Gemetzel, wenn ich meine Feinde auf einem persönlicheren Level demontiere. Hier, vielleicht kann Euch etwas von meiner ausgemusterten Ausrüstung nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[14384] = { id = 14384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Umgeleitet!", description = "Halt!\n\nIm Namen der Wache der Nijelspitze - ich habe Befehl, dafür zu sorgen, dass alle tauglichen Verbündeten sich bei Korporal Melkins melden.\n\nIch bin nicht befugt, weitere Informationen zu geben.\n\nIch kann allerdings Transport anbieten. Ihr dürft mein Reittier benutzen. Es wird Euch direkt dort absetzen.\n\nWegtreten.", sourceObjective = "Offizierin Jankie möchte, dass Ihr auf ihrem Reittier zur Nijelspitze fliegt und dort mit Korporal Melkins sprecht.", completion = "Willkommen auf der Nijelspitze, {race}. \n\nAlso, dann wollen wir Euch mal über unsere Situation hier aufklären.", sourceObjectiveStatus = "unverified-source-field" }
quests[14385] = { id = 14385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsharitexperiment Nummer Eins", description = "Nun, ich kann mir einen todsicheren Weg vorstellen, wie man einen Riesen dazu bringt, zur Toilette zu rennen, aber das wird Euch nicht gefallen. Wir brauchen einfach ein... gewaltiges... Abführmittel. Oh hey! Ihr werdet es nicht glauben, aber die Gnome haben tatsächlich so etwas. Das kann kein Zufall sein. Ich frage mich, was die da drüben wohl durchdrücken wollen.\n\nUnser Geheimdienst berichtet, dass das Abführmittel bei Federdings' Turm unten an der Küste südlich des Geheimlabors abgegeben wurde. Holt das Abführmittel und verabreicht es Gormungan!", sourceObjective = "Besorgt Euch ein Abführmittel in Riesengröße von dem Gnomenturm in den Verfallenen Gegenden. Versucht, das Abführmittel dem Riesen Gormungan zu verabreichen.", progress = "Sobald Ihr das Abführmittel habt, versucht, es Gormungan zu verabreichen. Und gebt ihm vielleicht eine Zeitschrift oder so etwas. Tut es für die Wissenschaft!", completion = "Also ist nichts dabei rausgekommen? Im wahrsten Sinne des Wortes? Nun, Wurfhammer wird ein Nein nicht akzeptieren. Wir müssen etwas Anderes ausprobieren.\n\nVielleicht lasse ich meine Praktikanten dieses Abführmittel in das Lager der Nachtelfen schmuggeln. Das wäre doch bestimmt sehr lustig.", sourceObjectiveStatus = "unverified-source-field" }
quests[14386] = { id = 14386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Leithund", description = "Ausgezeichnete Arbeit bisher, {name}. Unsere Späher haben die Anführerin des Bodenangriffs der Verlassenen ermittelt.\n\nEine von Sylvanas persönlich ausgewählte Dunkle Waldläuferin kontrolliert das Schlachtgeschehen vom Haus der Waldens bei der Küste aus. Nehmt diese Pfeife mit und benutzt sie, wenn Ihr in ihrer Nähe seid.\n\nIch befehle meinen Männern dann, unsere Angriffsmastiffs loszulassen, um sie zur Strecke zu bringen. Seid vorsichtig, {name}. Ihr solltet ihr nicht allein gegenübertreten.", sourceObjective = "Benutzt die Mastiffpfeife, um Hilfe dabei zu bekommen, die Dunkle Waldläuferin Thyala zu töten.", progress = "Ist es schon vollbracht, {name}?", completion = "Ihr habt es geschafft, {name}. Das sollte ihnen den Wind aus den Segeln nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14387] = { id = 14387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschaffenheit des Geländes", description = "Ja, ja. Willkommen in Desolace, {race}.\n\nTut mir leid, dass wir so darauf bestehen mussten, aber wir sind nur ein kleiner Außenposten und es gibt große Probleme in dieser Region - die meisten davon ziemlich dringend.\n\nUnterm Strich heißt das: Wir können jede Hilfe gebrauchen, die wir bekommen können.\n\nZunächst einmal ist unser Freund Vahlarriel da drüben ziemlich nervös geworden und besteht darauf, dass wir ein Aufgebot zu den Ruinen im Osten entsenden.\n\nWarum geht Ihr nicht und stellt Euch vor...", sourceObjective = "Hauptmann Pentigast möchte, dass Ihr mit Vahlarriel auf der Nijelspitze sprecht.", completion = "Ist mir ein Vergnügen, Euch kennenzulernen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14388] = { id = 14388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsharitexperiment Nummer Zwei", description = "Ok - neuer Plan. Wir ERSCHRECKEN sie so, dass wir es bekommen! Meiner Erfahrung nach ängstigen große Kreaturen sich vor kleinen - wie Ratten. Hmm. Hier wimmelt es nur so von Ratten, aber wie locken wir sie zu dem Riesen?\n\nHey! Es macht Euch doch nichts aus, wenn Eure Zellenmatrix auseinandergenommen und wieder zusammengesetzt wird, oder? Es tut nur während des Vorgangs weh. Ich kann Euch auf Rattengröße zusammenschrumpfen und Ihr könnt eins von den Viechern dort drüben reiten wie ein Pferd. Das ist so verrückt, dass es funktionieren muss! Lasst mich wissen, wenn Ihr zum Schrumpfen bereit seid...", sourceObjective = "Sprecht mit Assistentin Greely, um auf Rattengröße zusammengeschrumpft zu werden. Steigt auf eine Ratte der Raketenbahn und jagt Gormungan dem Riesen damit Angst ein.", completion = "Also hat Angst einjagen auch nichts bewirkt? Verflixt nochmal! Das muss ich Wurfhammer schonend beibringen. Azsharit wird wohl die seltenste Substanz auf dem Planeten bleiben. Wir müssen ihn äußerst sparsam verwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[14389] = { id = 14389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "War das nicht klar?", description = "Azuregos! Ja, natürlich! Verstörter, alter Drache, aber ein gutes Herz. Ich glaube, all die Jahre, in denen er von Vagabunden angegriffen wurde, haben ihm nicht gutgetan. Heutzutage ist er ein wenig seltsam.\n\nVor nicht allzu langer Zeit, als ich wieder einmal zu Anara, unserer hiesigen Geistheilerin, zurückkehrte, fiel mir auf, dass sie und Azuregos sich anscheinend sehr gut verstehen. Ich könnte mir vorstellen, dass er ihr immer noch Gesellschaft leistet.\n\nDas Portal hinter mir ist der wahrscheinlich schnellste Weg, um zu ihr zu gelangen. Es könnte allerdings ein wenig zwicken.", sourceObjective = "Benutzt das Portal hinter Joanna in Xylems Turm, um Anara, die Geistheilerin - und hoffentlich Azuregos - zu finden.", completion = "Azuregos! Ihr habt ihn endlich gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[14390] = { id = 14390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfach kann jeder", description = "Nach langer Suche mit einigen zweifelhaften Wendungen habt Ihr endlich Azuregos gefunden.\n\nJetzt müsst Ihr ihn nur noch davon überzeugen, sich mit Kalecgos zu treffen und der Bedrohung Azsharas durch den schwarzen Drachenschwarm ein Ende zu bereiten.", sourceObjective = "Überzeugt Azuregos, in die Welt der Lebenden zurückzukehren und sich mit Kalecgos zu treffen.", completion = "Azuregos erklärt sich mit einem Treffen mit Kalecgos einverstanden. Erfolg!", sourceObjectiveStatus = "unverified-source-field" }
quests[14391] = { id = 14391, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Blatt wenden", description = "Azuregos und Kalecgos sind kurz davor, sich an der Nördlichen Endhaltestelle der Raketenbahn zu treffen. Ihr solltet dort zu ihnen stoßen, um sicherzustellen, dass Kalecgos keine zusätzliche Hilfe benötigt.\n\nSolltet Ihr es vorziehen, nicht tot zu sein, wird Anara Euch höchstwahrscheinlich helfen können.", sourceObjective = "Sprecht mit Anara, um in die Welt der Lebenden zurückzukehren, dann sprecht mit Kalecgos an der Nördlichen Endhaltestelle der Raketenbahn.", completion = "Schön, Euch wiederzusehen! Danke, dass Ihr Azuregos gefunden und zu mir geschickt habt.\n\nIch glaube, ich muss mich bei Euch entschuldigen - möglicherweise habe ich ein wenig untertrieben, als ich Euch über die Schwierigkeit der Aufgabe, die ich Euch stellte, ins Bild setzte. Ihr habt Euch bewundernswert geschlagen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[14392] = { id = 14392, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leb wohl, Minnow", description = "Danke, kleines Wesen.\n\nManchmal ist es einfach, sich in der Umklammerung der Liebe zu verirren und die Sicht auf die wichtigen Dinge zu verlieren, sogar für einen Drachen. Ich gedenke, mich wieder vollkommen dem Ziel zu verschreiben, dass Kalec niemals Malygos' Platz einnehmen wird. Das ist die edelste Sache, die ich mir vorstellen kann.\n\nIhr solltet Euch auf den Weg zurück zum Hafen machen. Soweit ich weiß, wartet dort jemand auf Euch.\n\nVersucht, nicht zerquetscht oder von etwas gefressen zu werden.", sourceObjective = "Sprecht mit Sorata Feuerspinner im Bilgewasserhafen.", completion = "Hallo - wieder einmal.\n\nHört mal, ich habe Euch meinen Hut gegeben. Er war ein Geschenk. Ich dachte, er könnte Euch vielleicht irgendwie nützlich sein. Um genau zu sein, dachte ich, Ihr würdet ihn so weit wie möglich von mir wegbringen.\n\nKönnt Ihr Euch meine Überraschung vorstellen, als Xylem höchstpersönlich hier vorbeikam, um ihn mir zurückzugeben? \"Willst du mehr wie meine anderen Lehrlinge sein, Sorata? Dann versuch's nochmal mit deinem Hut.\" Das war nicht einer der Momente, auf die ich stolz bin.\n\nAlso wie war das... Ihr habt ihn achtlos zur Seite geworfen, damit er ihn findet? Nein. Das glaube ich nicht. Ihr werdet diesen Hut nehmen und Ihr werdet ihn mögen. Ganz bestimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14393] = { id = 14393, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf in den Kampf!", description = "Seit unzähligen Generationen bekämpfen die Zentauren sich untereinander, aber das ist vorbei.\n\nWegen Eurer Taten stehen wir hier Seite an Seite und bekämpfen einen gemeinsamen Feind. Wir werden das Land unserer Vorfahren von diesen Dämonen zurückgewinnen, oder als Brüder sterben.\n\nWie ist es mit Euch, {name}?\n\nIhr habt Euch das Recht verdient, an unserer Seite zu kämpfen. Ich möchte Euch eine Gruppe meiner besten Zentauren anvertrauen, damit Ihr sie in den Kampf führt.\n\nWerdet Ihr den Speer aufnehmen?", sourceObjective = "Khan Leh'prah möchte, dass Ihr 15 Hexenmeister der Brennenden Klinge, 3 Verdammniswacheneindringlinge und Priesterin Than'darissa besiegt.\n\nSprecht mit Khan Leh'prah, um in den Kampf zu ziehen.", completion = "Gut gemacht, {name}!\n\nLasst uns das hier beenden!", sourceObjectiveStatus = "unverified-source-field" }
quests[14394] = { id = 14394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod dem Agogridon", description = "Unser Ziel ist zum Greifen nahe, {name}!\n\nWir können den Willen dieser Dämonenarmee brechen, indem wir ihren Anführer zur Strecke bringen. Gelingt es uns, wird Desolace uns gehören!\n\nWenn Ihr bereit seid, führt eine Gruppe Zentauren durch den Pass im Süden nach Schattenklamm. Findet Agogridons Versteck!\n\nIch werde die anderen Khans um mich versammeln und Euch dort treffen, damit wir uns ihm im Kampf stellen.", sourceObjective = "Besiegt Agogridon.", completion = "Agogridon gibt es nicht mehr.\n\nDie Dämonen werden sich nie wieder in unseren Landen ausbreiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[14395] = { id = 14395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Atemlos", description = "{name}! Ich war gerade unterwegs, als es passiert ist.\n\nWir haben keine Zeit zu verlieren. Gut die Hälfte der Wachleute der Stadt hat sich in dem Bereich aufgehalten, der eingestürzt ist. Geht dorthin und rettet so viele, wie Ihr könnt.\n\nZieht sie aus dem Wasser ans Ufer. Ich kümmere mich darum, dass sie die benötigte Hilfe bekommen.", sourceObjective = "Rettet 4 ertrinkende Wachleute.", completion = "Ihr habt getan, was Ihr konntet, {name}. Mit etwas Glück schaffen es noch ein paar andere ans Ufer.", sourceObjectiveStatus = "unverified-source-field" }
quests[14396] = { id = 14396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Als das Land zerbarst", description = "Was in aller Welt war das, {name}?\n\nDas waren keine Kanonen oder Katapulte, so viel steht fest.\n\nGeht nach draußen und seht nach, was los ist.", sourceObjective = "Sprecht mit Prinz Liam Graumähne auf Allens Bauernhof.", completion = "Das Meer, {name}! Es hat alles verschlungen… das Land… die Verlassenen… unsere Männer!", sourceObjectiveStatus = "unverified-source-field" }
quests[14397] = { id = 14397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evakuierung", description = "Wir sind dem Tod nur durch schieres Glück entkommen, {name}. Aber unser Glück ist langsam erschöpft.\n\nNoch während wir hier sprechen wird die Küste überflutet. Und auch die Landmasse unter uns scheint sich noch nicht beruhigt zu haben.\n\nIch sage es nicht gerne, aber wir müssen hier weg. Verdammt, {name}... Ich darf mein Heimatland nicht zweimal in meinem Leben verlieren. Aber diese Erdbeben sind kein Feind, den wir besiegen können.\n\nSagt Gwen Armstead, dass sie die Evakuierung einleiten soll.", sourceObjective = "Sprecht mit Gwen Armstead in Dämmerhafen.", completion = "Liam hat Recht. Wir müssen in ein höher gelegenes Gebiet fliehen.\n\nHelft mir, die Leute zu benachrichtigen, während ich die Organisation der Evakuierung übernehme.", sourceObjectiveStatus = "unverified-source-field" }
quests[14398] = { id = 14398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oma Wahl", description = "Es wird nicht leicht, Oma Wahl dazu zu bewegen, mit uns zu kommen. Ihr müsst dennoch alles in Eurer Macht Stehende tun, um sie zu überzeugen.\n\nIhr findet sie in Wahls Landhaus. Bitte, {name}, seid geduldig mit ihr. Sie ist schon sehr alt und ihr Geist wird immer schwächer.", sourceObjective = "Findet Oma Wahl in Wahls Landhaus.", completion = "Oh, Besuch! Bleibt Ihr auf eine Tasse Tee, Herzchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14399] = { id = 14399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oma hat sie nicht mehr alle", description = "Gehen? Jetzt?\n\nNun, was sein muss, muss wohl sein. Aber wärt Ihr ein Engel und würdet etwas für mich suchen?\n\nIch habe mein Lieblingsbuch verlegt und werde ganz sicher nicht ohne es gehen.\n\n<Nachdem Ihr Oma die Dringlichkeit der Lage erläutert habt, schüttelt sie herablassend den Kopf.>\n\nLiebes, sucht einfach das Buch für mich, ja?", sourceObjective = "Findet das leinengebundene Buch.", progress = "Wie läuft es, Schätzchen? Bleibt Ihr zum Tee?", completion = "Vielen Dank, {name}. Ich hoffe, Ihr habt nicht hineingelinst!\n\nWo bleiben Eure Manieren, Herzchen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14400] = { id = 14400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So gehe ich nicht außer Haus", description = "Was wolltet Ihr nochmal?\n\nOh, stimmt ja. Der Evakuierungsbefehl.\n\nAber so kann ich ja schlecht unter die Leute gehen, oder?\n\nSeid so lieb und holt mir meine guten Kleider. Sie hängen draußen auf der Wäscheleine.\n\n<Ihr versucht vergeblich, Oma Wahl davon zu überzeugen, dass ihre jetzige Kleidung völlig angemessen ist.>\n\nIhr jungen Leute habt einfach keine Manieren. Wurdet Ihr von Ogern großgezogen? Und jetzt geht und bringt mir meine Kleider, Liebes.", sourceObjective = "Besorgt Omas gute Kleider.", progress = "Habt Ihr alles gefunden, Schätzchen?", completion = "Ihr seid ein Goldschatz, {name}! Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[14401] = { id = 14401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omas Katze", description = "Genau! Was die Evakuierung angeht, Liebes.\n\nIch kann nicht ohne meine Katze gehen. Er ist ein zuckersüßer orangefarbener Tigerkater.\n\nFelix spielt am liebsten in der Nähe eines alten Karrens in der Nähe einer Laube nordöstlich von hier.\n\nBringt ihn zu mir, dann können wir sofort aufbrechen.", sourceObjective = "Holt Felix, die Katze.", progress = "Ihr seid so ein bezaubernder junger Mann, {name}.", completion = "Da ist er ja! Omas kleiner Liebling!\n\nVielen Dank, dass Ihr ihn gefunden habt. Ich hoffe, es hat Euch nicht allzu viele Umstände bereitet.\n\nOh je… meine Fingernägel sind ja ganz dreckig!", sourceObjectiveStatus = "unverified-source-field" }
quests[14402] = { id = 14402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abmarschbereit", description = "Ich schätze, jetzt aufzubrechen ist genauso gut wie zu jedem anderen Zeitpunkt.\n\nIch habe meine schönste Kleidung, mein Lieblingsbuch und meine geliebte Katze bei mir.\n\nIch hoffe, ich habe nichts vergessen.\n\nSagt dieser Bürgermeisterin, dass ich auf dem Weg bin. Dann sehe ich Euch wohl zusammen mit den anderen in der Stadt!", sourceObjective = "Sprecht mit Gwen Armstead in Dämmerhafen.", completion = "Ihr habt das Unmögliche geschafft, {name}! Ihr habt Oma Wahl überredet, ihr Zuhause zu verlassen.\n\nIch muss schon sagen, Ihr seid etwas ganz Besonderes.", sourceObjectiveStatus = "unverified-source-field" }
quests[14403] = { id = 14403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Brüder Hayward", description = "Weit im Süden findet Ihr die Fischerei Hayward. Die Brüder Hayward führen sie schon seit vielen Jahren.\n\nSie kommen nicht oft in die Stadt, nur um ihre Fische zu verkaufen. Gebt ihnen Bescheid, dass die Evakuierung eingeleitet wurde.", sourceObjective = "Sprecht mit Sebastian Hayward in der Fischerei Hayward.", completion = "Seid Ihr hier, um uns zu helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[14404] = { id = 14404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht alles im Lot auf'm Boot", description = "Evakuierung, sagt Ihr? Nun, nachdem die Verlassenen hier aufgetaucht sind, kam uns diese Idee von ganz alleine.\n\nWir dachten, zur See wäre der sicherste Fluchtweg.\n\nLeider haben unsere Boote das letzte Erdbeben nicht unbeschadet überstanden.\n\nIch benötige noch ein wenig Material, um meine Reparaturen abzuschließen: Holz, Teer und meine Werkzeuge. Besorgt sie mir, damit ich und meine Brüder von hier entkommen können.", sourceObjective = "Besorgt Holzplanken, Kohlenteer und Schiffbauerwerkzeuge.", progress = "Habt Ihr mein Material, {name}?", completion = "Toll, {name}. Jetzt kann ich die Reparaturen im Handumdrehen fertigstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14405] = { id = 14405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht zur See", description = "Danke für Eure Hilfe, {name}. Unser Schiff ist bereit zum Ablegen.\n\nUnd jetzt geht und sagt Fräulein Armstead, dass wir nicht an der Evakuierung über Land teilnehmen.\n\nWir Haywards sind seit Jahren Männer der See. Wenn wir unser Zuhause verlassen müssen, dann nur zu Wasser.", sourceObjective = "Kehrt zu Gwen Armstead in Dämmerhafen zurück.", completion = "Soll mir Recht sein, {name}. Vielleicht ergeht es den Haywards ja besser als uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[14406] = { id = 14406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crowleys Obstgarten", description = "Ihr erinnert Euch doch sicher an Lord Darius Crowleys Tochter Lorna.\n\nSie hat sich nie ganz vom Verlust ihres Vaters in Gilneas erholt. Seitdem fristet sie ihr Leben als Einsiedlerin. Der einzige Besucher, den sie je in ihr Haus gelassen hat, war Krennan... und er verliert kein Wort über die ganze Sache.\n\nBenachrichtigt sie über die Evakuierung.", sourceObjective = "Sprecht mit Lorna Crowley bei Crowleys Obstgarten.", completion = "Bleibt zurück! Sonst werde ich…\n\nSeid Ihr das? Beim Licht! Ihr seid es, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[14407] = { id = 14407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azshara Blues", description = "He! Ich bin froh, dass ich Euch erwischt habe.\n\nIch komme im Auftrag meines Meisters, Kalec. Er benötigt Eure Hilfe. Sucht ihn unter der Brücke in den Slums so bald wie möglich auf!", sourceObjective = "Sprecht mit Kalec im Bilgewasserhafen.", completion = "Danke, dass Ihr gekommen seid. Ich muss mich für die Geheimnistuerei entschuldigen, aber es ist ungeheuer wichtig, dass ich von gewissen Individuen nicht gesehen werde.\n\nIch bin nämlich ziemlich in der Klemme und mir sind Eure Taten in letzter Zeit aufgefallen. Hört Euch an, was ich zu sagen habe, helft mir und ich werde dafür sorgen, dass Ihr angemessen belohnt werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[14408] = { id = 14408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuns Plan", description = "Meine Wohltäter haben ihre spärliche Intelligenz dazu benutzt, ein interplanetares Transportmittel zu konstruieren. Mit dem jetzigen Design ist diese sogenannte \"Rakete\" eine Todesfalle. Aber ich denke, dass eine Umarbeitung der Klappe des Treibstoffkatalysators eine stabile Mischung erbringen würde, die ein atembares Sauerstoffnebenprodukt liefern würde. Um derartige Veränderungen einzubauen, benötige ich die Originalbaupläne.\n\nFindet die Laborarchive und betätigt die Türglocke, um hineinzugelangen. Der Labordirektor selbst hat die Pläne, wenn er denn noch lebt.", sourceObjective = "Beschafft die geheimen Raketenbaupläne aus den Laborarchiven am östlichen Ende des Geheimlabors. Betätigt die Türklingel und tötet den Labordirektor, wenn er herauskommt.", progress = "Ich nehme an, dass die Archive sich in der Nähe befinden, {name}. Findet diese Pläne!", completion = "<Das Raptorenweibchen schnappt sich die Papiere mit ihren Greifklauen und hält sie sich vors Gesicht. Dabei klappert sie verächtlich mit den Zähnen.>\n\nDas sieht wie das Gekritzel von Kindern aus. Der gesunde Menschenverstand sagt, dass man die hydraulischen Kontrollen nicht so nah an die Brenner der zweiten Stufe legt. Immerhin, man kann noch etwas daraus machen.\n\nWisst Ihr, wie man eine Treibstoffmatrix so verändert, dass sich der Druck ändert und man eine bestimmte Beschleunigung erhält? Nein? Also schön, vielleicht könnt Ihr dann etwas anderes für mich erledigen, während ich die Rakete repariere...", sourceObjectiveStatus = "unverified-source-field" }
quests[14409] = { id = 14409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine vorsichtige Rückkehr", description = "Schenkt mir einen Moment Eurer Zeit, {class}.\n\nVeränderung liegt in der Luft. Sie hat uns aus den Ruinen von Eldre'Thalas gelockt, ein weiteres Mal hinaus in die weite Welt. Ich bin gekommen, um diese Stadt zu erforschen und darf von dieser Aufgabe nicht abweichen, doch wenn Ihr interessiert wärt, hätte ich einen Auftrag für Euch.\n\nMein Kollege ist auf dem Weg nach Darnassus, um mit der Hohepriesterin zu sprechen, auf dass wir eine Übereinkunft erreichen. Nehmt dieses Tagebuch und bringt es zu Mordent Schattenfall im Tempel. Es könnte ihm bei seiner diplomatischen Mission nützlich sein.", sourceObjective = "Bringt Mordent Schattenfall in DarnassusDaros' Tagebuch.", sourceObjectiveStatus = "unverified-source-field" }
quests[14410] = { id = 14410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wildnis von Feralas", description = "Es ist wahrlich heldenhaft von Euch, uns beim Schutz dieses Landes zu helfen. Solltet Ihr noch mehr für die Wildnis tun wollen - es gibt noch andere, die Eure Hilfe benötigen.\n\nIm Süden liegen die grünen Wälder von Feralas. Sucht im Schatten der mächtigen Zwillingskolosse nach Telaron Windsegler. Bei Träumersruh haben er und seine Druidenfreunde der Kralle Zeichen einer beunruhigenden Krankheit gefunden.\n\nSie werden Eure Hilfe benötigen, {class}. Geht in Frieden.", sourceObjective = "Reist nach Feralas und sprecht mit Telaron Windsegler bei Träumersruh.", completion = "Willkommen in Feralas, {class}. Ich danke Euch, dass Ihr gekommen seid, um uns zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14412] = { id = 14412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angespült", description = "Die Schiffe der Verlassenen sind viel zu nahe an unserer Fischerei gesunken. All die Überlebenden machen sich auf den Weg hierher. Wie Ihr sehen könnt, sind wir zahlenmäßig unterlegen.\n\nHelft uns, sie zurückzuhalten, während ich die Boote fertig repariere.", sourceObjective = "Tötet 6 schiffbrüchige Verlassene.", completion = "Ausgezeichnet! Ich bin hier fast fertig.", sourceObjectiveStatus = "unverified-source-field" }
quests[14413] = { id = 14413, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gipfel des Lernens", description = "Ist das aufregend! Ihr fragt, was aufregend ist? Na, DIES ist natürlich aufregend!\n\nDie Zeit der Prüfungen... Zeit EURER Prüfungen. Es gilt, so viele Herausforderungen zu meistern, so vieles zu lernen. Ihr lernt etwas über Prüfungen. Ich lerne etwas über Euch.\n\nUnd jetzt geht nur. Zu meiner Arkanen Spitze. Natürlich werde ich Euch dort treffen, denn ich bin so ziemlich überall.", sourceObjective = "Sprecht mit dem Abbild von Erzmagier Xylem am Fuß der Arkanen Spitze.", completion = "Ihr seid schon da. Ich hoffe, Ihr hattet eine angenehme Reise. Euch ist doch nicht übel geworden, oder?\n\nEs wird viel Herumrennen und genauso viel Springen geben, deshalb ist ein ausgeglichener Magen von großem Vorteil.", sourceObjectiveStatus = "unverified-source-field" }
quests[14415] = { id = 14415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erscheinungen im Obstgarten", description = "Hört zu, {name}. Ich habe gehört, was Euch zugestoßen ist, aber ich vertraue Euch trotz Eures… Leidens. Schließlich seid Ihr bis zu Eurem Tod an der Seite meines Vaters gewesen.\n\nAber ich gehe nicht dort hinaus. Es ist zu gefährlich.\n\nDas Erdbeben hat einen Pfad aus den Bergen freigeräumt und ein Ettin hat beschlossen, uns einen kleinen Besuch abzustatten.\n\nAber das ist noch nicht alles! Nachdem ich mich im Haus verschanzt hatte, sah ich plötzlich geisterhafte Wolfsgestalten im Obstgarten.\n\nIch kann nicht vor die Tür gehen, bevor ich nicht weiß, was hier vor sich geht.", sourceObjective = "Untersucht Crowleys Obstgarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[14416] = { id = 14416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der hungrige Ettin", description = "Hört zu, {name}. Wir werden es ohne ein Transportmittel nicht weit schaffen, nicht wahr?\n\nWenn wir uns hier einfach nur so aus dem Staub machen, werden die Verlassenen uns im Handumdrehen einholen.\n\nNormalerweise wäre es überhaupt kein Problem, ein paar Pferde in den Stallungen im Südosten aufzutreiben, aber da gibt es einen Haken.\n\nDas letzte Erdbeben muss Koroth den Ettin aus den Bergen herunter zu uns vertrieben haben. Wenn wir uns die Pferde nicht bald schnappen, fürchte ich, dass er uns zuvorkommt.", sourceObjective = "Bringt 5 Gebirgspferde zu Lorna Crowley bei Crowleys Obstgarten.", completion = "Wir haben die Pferde. Ich stelle sicher, dass sie nach Dämmerhafen gelangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14418] = { id = 14418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Das Syndikat? Darauf wäre ich nie gekommen. Offenbar sind die Lords von Alterac in den Jahren seit ihrem Verrat tief gesunken.\n\nHawkins wird es mit Freuden hören, und da wir diese Entdeckung weitgehend Euch verdanken, ist es nur recht und billig, dass Ihr ihm die Nachricht überbringt.\n\nAh, und wie konnte ich das vergessen?\n\nWillkommen bei den Todespirschern.", sourceObjective = "Bringt Androns Geschäftsbuch zu Aleric Hawkins in die Halle der Dunklen Fürstin in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14419] = { id = 14419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Das Vorstellungsschreiben sollte Andron überzeugen, dass Ihr der Bote seid, auf den er gewartet hat. Ich kenne Andron, er ist nicht so helle im Kopf, dass er Verdacht schöpfen würde.\n\nUnser Anführer vermutet, dass Andron einer anderen Gruppe Unterstützung zuteilwerden ließ. Er möchte wissen, was das für eine Organisation ist, und braucht einen Beweis.\n\nIch möchte, dass Ihr mit Andron sprecht und diese Information bekommt. Ihr findet ihn in seinem Geschäft nahe des Apothekariums.", sourceObjective = "Sprecht mit Andron Gant in Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14420] = { id = 14420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Wenn Ihr Euch den Todespirschern anschließen möchtet, der Elitewache der Dunklen Fürstin, so müsst Ihr Euren Wert beweisen.\n\nIch will Euch nichts vormachen, {name}, diese Aufgabe könnte Euren Tod bedeuten.\n\nIch habe ein paar Angelegenheiten, die geregelt werden müssen. Ich benötige die persönlichen Habseligkeiten von Astor Hadren, einem Boten, der zwischen Silberwald und Unterstadt pendelt. Die Beschaffungsmethode überlasse ich ganz Euch.\n\nJe weniger Ihr über diese Angelegenheit Bescheid wisst, desto besser. Wenn Ihr Erfolg habt, sage ich Euch mehr.", sourceObjective = "Beschafft Astors Vorstellungsschreiben und bringt es zu Mennet Carkad im Schurkenviertel.", sourceObjectiveStatus = "unverified-source-field" }
quests[14421] = { id = 14421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Todespirscher", description = "Ihr findet das Geschäftsbuch mit den Informationen, die Eure Auftraggeber suchen, auf dem Bücherregal hinter mir. Überbringt es mit meinen besten Wünschen und sagt ihnen, dass ich es bevorzugen würde, wenn sie Euch schicken, sollte unsere Übereinkunft ihnen so lieb und teuer sein, dass sie sie fortsetzen möchten.", sourceObjective = "Bringt Androns Geschäftsbuch zu Mennet Carkad im Schurkenviertel von Unterstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14422] = { id = 14422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptor Rakete", description = "Kurz nachdem meine Intelligenz erweitert worden war, habe ich mich mit Versuchsobjekt vier verpaart, um eine einzigartige Rasse geistig überlegener Raptoren zu erschaffen. Im Anschluss hat Versuchsobjekt vier weder angerufen noch geschrieben: Ich habe beschlossen, ihn auseinanderzunehmen, wenn wir uns noch einmal begegnen.\n\nNichtsdestotrotz sind in diesem Labor genug Raptorenkinder gefangen, die einen angemessenen genetischen Grundstock bilden, um meine Rasse wieder aufleben zu lassen. Bitte befreit sie aus ihren Käfigen und tragt sie zu der Rakete.", sourceObjective = "Befreit fünf Versuchsraptoren aus ihren Käfigen im Geheimlabor und liefert sie bei der Rakete neben Versuchsobjekt neun ab.", completion = "Wunderbar! Eine beispielhafte Leistung, {name}! Wie Ihr Euch zweifellos schon gedacht habt, ist es mein Ziel, diese Rakete als eine Art Sternenwiege zu benutzen - eine Arche, wenn Ihr so wollt -, die es meiner neuerschaffenen Rasse erlaubt, den trostlosen Fesseln dieses geschundenen Planeten zu entfliehen und eine Welt zu kolonisieren, die uns gefällt. Ihr habt bei dieser Sache eine entscheidende Rolle gespielt. Bitte nehmt diese Währung an, da ich bei unserer Ankunft meine eigenen Geldeinheiten prägen werde. Lebt wohl, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[14423] = { id = 14423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raupenexorzismus", description = "... wir brauchen einen Priester!\n\nZum Glück habe ich ein bisschen Geld zur Seite gelegt, um die Maschinen segnen zu lassen. Nehmt diese Leuchtpistole und geht hinüber zu Margene, meiner armen, kleinen, kaputten Planierraupe. Feuert das Signal ab und einer unserer besten fliegenden Priester sollte mit dem Fallschirm eintreffen, um die Situation unter Kontrolle zu bringen. Kommt zurück, wenn meine Planierraupe in guten Händen ist!", sourceObjective = "Benutzt die gesegnete Leuchtpistole in der Nähe von Clubniks Planierraupe, um Hilfe herbeizurufen, dann führt an der Planierraupe einen \"Exorzismus\" durch.", progress = "Wie geht es Margene? Läuft sie wieder so süß, wie sie immer läuft?", completion = "Was? ...Was?\n\nMargene! Oh, meine süße Margene!", sourceObjectiveStatus = "unverified-source-field" }
quests[14424] = { id = 14424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Wissenschaft benötigt", description = "<Clubnik wischt sich eine Träne weg. Dann streckt er entschlossen sein Kinn vor.>\n\nNie wieder, {name}! Kein Bulldozer verdient das Schicksal meiner Margene. Wir werden professionelle Geisterjäger brauchen. Das ist ein Job für unsere besten Wissenschaftler und ich kenne genau die richtige Frau dafür! Sucht nach Assistentin Greely an der Südlichen Endhaltestelle der Raketenbahn. Sie ist die Verwalterin für Azsharas weltberühmtes Geheimlabor und sie schuldet mir einen Gefallen.", sourceObjective = "Findet Assistentin Greely an der Südlichen Endhaltestelle der Raketenbahn. Man kann die Goblinraketenbahn nutzen, um schnell durch Azshara zu reisen.", completion = "Wovon redet Clubnik da? Spukende Bauausrüstung? Seh ich so aus, als ob ich Zeit für Geistergeschichten hätte?\n\nIch habe ein Labor, das kurz vor der Schmelze steht, brennende Feuer, mutierte Tiere und das Schlimmste... Projekte, die hinter den Zeitplan zurückfallen. Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[14425] = { id = 14425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die erste Quest", description = "Grüße, {name}, das hier ist ein Test. Nehmt an und bringt Zeug um.", sourceObjective = "Thrall möchte, dass Ihr Zeug umbringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14426] = { id = 14426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die zweite Quest", description = "Dies ist die zweite Quest! Diesmal müsst Ihr nichts töten.", sourceObjective = "Santa Thrall möchte, dass Ihr 5 Schnäpschen einsammelt, was immer das sein soll.", sourceObjectiveStatus = "unverified-source-field" }
quests[14427] = { id = 14427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegenstandsquest", description = "Gegenstand einsammeln Quest", sourceObjective = "Holt die Gegenstände", sourceObjectiveStatus = "unverified-source-field" }
quests[14428] = { id = 14428, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goldwinds Tagebuch", description = "Wenn ich meinen Quellen vertrauen kann, überwacht Wissenshüterin Goldwind die Untersuchung der Ruinen durch die Allianz im Osten. Ich habe das Ausmaß ihrer Fähigkeiten noch nicht auf die Probe gestellt. Ich hoffe, Ihr könnt mir einen vollständigen Bericht liefern, nachdem Ihr sie zum Kampf gestellt und besiegt habt.\n\nJemand, der einen Titel wie 'Wissenshüter' trägt, wie Goldwind, wird ein Tagebuch bei sich haben, das uns sagen wird, was genau diese Nachtelfen vorhaben. Bringt mir dieses Tagebuch. Ihr müsst auch nicht zurück laufen, benutzt ihre Sehersteine, um mich aus der Ferne zu kontaktieren.", sourceObjective = "Tötet Wissenshüterin Goldwind im Darnassischen Basislager und bringt ihr Tagebuch in Euren Besitz.", progress = "<Andorels verzerrtes Gesicht taucht in dem Seherstein auf.>\n\n{name}, habt Ihr den Kontakt herstellen können? Was könnt Ihr mir mitteilen?", completion = "Goldwind hat sich ein Arkanes Konstrukt zunutze gemacht? Ha! Wie erfreulich unerfahren. Das ist, als ob man andere Kinder dabei beobachtet, wie sie mit Feuerwaffen spielen.\n\nSehen wir uns einmal das Tagebuch an, {name}. Haltet es vor den Seherstein... Haltet still...", sourceObjectiveStatus = "unverified-source-field" }
quests[14429] = { id = 14429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkane Dekonstruktion", description = "Arkane Konstrukte sind Kreaturen, die aus reinem Mana und Intelligenz ins Leben gerufen wurden. In den richtigen Händen befähigen sie ihre Nutzer, sich schnell riesige Mengen arkanes Wissen anzueignen. Aber sie sind gefährlich, {name}. So intelligent! So mächtig! So hilflos Manipulationen von außen ausgesetzt...\n\nLasst uns diesen Amateuren eine Lektion erteilen und ihre eigene Magie gegen sie verwenden. Tötet Lehrlinge und sammelt ihre Runensteine für mich ein. Nehmt über den Unteren Seherstein Kontakt mit mir auf, wenn Ihr fertig seid.", sourceObjective = "Tötet Angehende Ermittler und Angehende Illuminatoren um 10 Abgestimmte Runensteine einzusammeln.", progress = "<Andorels Bild ist verschwommen und unscharf. Er blinzelt Euch an und tippt gegen das Glas des Sehersteins.>\n\n{name}, seid Ihr das? Die Auflösung dieses Steins ist furchtbar. Was benutzen die nur für eine Hardware?", completion = "Gute Arbeit, diese Runensteine zu beschaffen. Um ehrlich zu sein, brauche ich nur einen, aber der Gedanke, dass so viele Nachtelfen für diese nutzlosen Kugeln getötet werden, bringt mir dunkle Freude, die mich ganz schwindelig macht.\n\nBitte haltet eine dieser Runen hoch vor den Seherstein, damit ich sie sehen kann. Hmmm. Wie ich mir bereits dachte - das ist bestenfalls dilettantisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[14430] = { id = 14430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Konstrukt hacken", description = "Jetzt werden wir ihr arkanes Konstrukt hacken und es dazu benutzen, Chaos anzurichten. Habt Ihr diese Art Magie schon einmal verwendet, {name}? Nein? Ha! Das macht meinen Plan noch delikater. In der Nähe solltet Ihr ein beeindruckendes arkanes Konstrukt sehen, das sie herbeigerufen haben. Dank der Runensteine, die ihr gesammelt habt, wissen wir, wie man mit ihm kommuniziert. Sprecht mit dem Konstrukt und sagt:\"Al'teth la c'tolgar.\" Verstanden? Wiederholt es? Sollte reichen. Meldet Euch wieder bei mir und lasst mich wissen, was geschehen ist.", sourceObjective = "Sprecht mit dem arkanen Konstrukt im Darnassischen Basislager und sprecht die Worte der arkanen Macht.", completion = "Haha! Ha - HA! Nachtelfische Magier, die vor ihrer eigenen, arkanen Kreation flüchten. Eure Taten haben mir den ganzen Monat versüßt, {name}. Deshalb benutzen wir Blutelfen die arkanen Konstrukte nicht länger - sie wurden vor, oh, ungefähr 1500 Jahren für ungesetzlich erklärt. Es ist schon lustig für mich zu sehen, wie unsere Feinde die Fehler der Vergangenheit wiederholen. \"Magier\". Dass ich nicht lache.", sourceObjectiveStatus = "unverified-source-field" }
quests[14431] = { id = 14431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwarzschlund-Narbe", description = "Die Furbolgs des Schwarzschlunds haben mit ihren Brüdern vom Holzschlund gebrochen, als wir begannen, Azshara aggressiv zu besiedeln. Sie sind wild geworden, {class}, und belästigen unsere Streitkräfte, wo sie nur können. Schlimmer noch - ich habe gesehen, wie sie den Nachtelfen von Talrendis freundlich begegnet sind. Wir können den beiden nicht erlauben, sich zu verbünden!\n\nGenau im Südwesten von hier findet Ihr eine große Narbe quer über die Erde. Von dort melden meine Späher Aktivitäten der Nachtelfen. Tötet sie und sammelt so viele Informationen, wie Ihr finden könnt.", sourceObjective = "Tötet 8 Biologen der Talrendisspitze und nehmt die Geheimdienstinformationen des Schwarzschlunds von einer der Leichen an Euch.", progress = "Die Schwarzschlundfurbolgs sind wild. Wenn sie sich jemals zusammenraufen sollten, würde das unsere Arbeit hier sehr behindern.", completion = "Ich verstehe... Das sieht aus wie die Rohfassung eines Abkommens. Der Ernstfall ist also eingetreten, {name}: Nachtelfen koordinieren ihre Angriffe mit unbeugsamen Furbolgverbündeten.\n\nMein erster Instinkt - ein Frontalangriff - würde sie nur in die Arme der Allianz treiben. Wir müssen uns etwas anderes überlegen...", sourceObjectiveStatus = "unverified-source-field" }
quests[14432] = { id = 14432, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein fahles Gebräu", description = "Es sieht so aus, als ob unsere Feinde der Allianz uns bei den Gesprächen mit den Schwarzschlund voraus sind, weil sie die Verhandlungen in Furbolgsprache führen. Wenn wir das Abkommen sabotieren wollen, müssen wir das genauso machen.\n\nDas ist nicht so schwer, wie es klingt, {name}. Die Schwarzschlundfurbolgs machen einen starken Kräutertee. Durch seine Dämpfe wird man in eine Art Trance versetzt, in der man beginnt, in Zungen zu reden. Genauer gesagt in der Zunge der Schwarzschlund. Geht zur Schwarzschlundfeste südwestlich von hier und besorgt mir einige Proben von diesem Strauchwurzelgebräu!", sourceObjective = "Sammelt 10 Proben Strauchwurzelgebräu außerhalb der Schwarzschlundfeste.", progress = "Was macht die Jagd? Ich habe das Strauchwurzelzeugs selbst einmal probiert, aber es war zu bitter, sogar für einen alten Kiesfresser wie mich.", completion = "Ah gut, das ist reichlich. Wir kochen das Zeug jetzt auf und Ihr könnt eine Weile die Dämpfe einatmen. Es wird nicht lange dauern, dann sprecht Ihr wie ein Furbolg. Unser Plan nimmt allmählich Gestalt an...", sourceObjectiveStatus = "unverified-source-field" }
quests[14433] = { id = 14433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diplomatie mal anders", description = "Um die Verhandlungen mit den Schwarzschlundfurbolgs zu unterwandern und zu stören, müssen wir wissen, wo sie stattfinden. Ich vermute, Ihr werdet in der Schwarzschlundfeste im Südwesten Botschafter der Nachtelfen vorfinden, die dort geschäftig umherlaufen und Vorbereitungen treffen.\n\n<Haggrum spuckt auf den Boden.>\n\nTötet sie nach Belieben und durchsucht die Gegend nach wichtigen Dokumenten. Oh, und wenn Ihr schon da seid - bringt doch eine Botschafterrobe mit... wir werden sie benötigen.", sourceObjective = "Bringt eine Versammlungsagenda des Schwarzschlunds in der Schwarzschlundfeste an Euch und tötet eine Botschafterin der Talrendisspitze, um eine Botschafterrobe in Euren Besitz zu bringen.", progress = "Habt Ihr die Robe? Andorel hat ein bisschen Magie für uns auf die Schnelle bereitgestellt, die wir benutzen können.", completion = "Ihr habt vorzügliche Arbeit geleistet! Lasst mich diese Dokumente einmal sehen. Hmm. Jetzt wissen wir genau, wann und wo die abschließenden Verhandlungen stattfinden werden. Macht Euch keine Sorgen, wenn Euch die Robe nicht passt - ich habe schon alles geplant.", sourceObjectiveStatus = "unverified-source-field" }
quests[14434] = { id = 14434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rut'theran", sourceObjective = "Seid Ihr bereit, die Segel zu setzen, {name}? Euer Volk hat im Land der Kaldorei eine Zuflucht gefunden.\n\nSeid unbesorgt, {race}. Euer Volk wird die Chance haben, wieder für Gilneas zu kämpfen. Dieses Mal mit der ganzen Macht der Allianz.", sourceObjectiveStatus = "unverified-source-field" }
quests[14435] = { id = 14435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doppeltes Spiel bei den Schwarzschlund", description = "Andorel hat ein bisschen Magie für mich bereitgestellt. Kommt, stellt Euch neben mein Feuer und taucht in die Dämpfe des Tees ein. Legt die Robe an und Ihr werdet für die Schwarzschlundfurbolgs wie ein Botschafter der Nachtelfen aussehen.\n\nLegt Eure Verkleidung an und sprecht mit Andorel hier im Lager. Er wird Euch in das Herz der Schwarzschlundfeste teleportieren, wo die Verhandlungen stattfinden werden. Sprecht mit Häuptling Ungarl und sabotiert das Abkommen. Dann tötet auf Eurem Rückweg so viele Schwarzschlundfurbolgs wie möglich!", sourceObjective = "Tragt die Verkleidung als Botschafter und sprecht mit Andorel Sonnenschwur, damit er Euch in die Schwarzschlundfeste teleportiert. Sprecht mit Ungarl, um die Verhandlungen zunichtezumachen, dann tötet 4 Krieger des Schwarzschlunds und 4 Schamanen des Schwarzschlunds auf dem Weg nach draußen.", progress = "Wenn unsere List aufgeht, {name}, werden wir für immer einen Keil zwischen die Allianz und die Schwarzschlundfurbolgs treiben.", completion = "Sieg! Die Schwarzschlundfurbolgs wissen jetzt nicht mehr, wem sie trauen sollen.\n\nJetzt, da wir dieses heikle Geschäft erledigt haben, kann ich einen Frontalangriff auf diese Ungeheuer organisieren, ohne dass ich mir Sorgen darüber machen muss, dass sie sich mit der Allianz zusammenschließen.\n\nIhr leistet gute Arbeit, {name}. Vielleicht sollten wir Euch eine Stelle im diplomatischen Corps der Horde verschaffen? Har-har!", sourceObjectiveStatus = "unverified-source-field" }
quests[14436] = { id = 14436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwergenbuddelei", description = "Im Nordwesten bereiten Zwerge eine Grabungsstätte vor. Sie glauben, dass Geheimnisse in der Erde verborgen seien, und das stimmt auch; dies ist jedoch kein Grund, das Land bei der Suche nach diesen Lehren auszuhöhlen und zu besudeln.\n\nSammelt die Grabwerkzeuge der Zwerge ein, zerstört sie und kehrt mit den zerbrochenen Werkzeugen der Zwerge zu mir zurück.\n\nIhr könnt die Werkzeuge in einer Schmiede zerschlagen. Ihr findet eine in Donnerfels, aber jede Schmiede, sogar eine Schmiede im Zwergenlager, eignet sich dazu.", sourceObjective = "Sammelt 5 Ausgrabungsleiterhacken ein.\n\nZerschlagt die Ausgrabungsleiterhacken in einer Schmiede, um zerbrochene Werkzeuge zu erhalten.\n\nBringt Ahmo Donnerhuf im Dorf der Bluthufe 5 zerbrochene Werkzeuge.", sourceObjectiveStatus = "unverified-source-field" }
quests[14437] = { id = 14437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riten der Erdenmutter", description = "Damit Ihr die Riten der Erdenmutter fortsetzen könnt, müsst Ihr noch zwei weitere Prüfungen bestehen. Es ist an der Zeit, Eure Erfahrungen zu erweitern, {name}.\n\nReist ins Dorf der Bluthufe und sprecht mit Ahmo Donnerhuf. Dort könnt Ihr Eure Reise fortsetzen und Euch die Anerkennung der Ältesten von Donnerfels verdienen.\n\nBringt Ahmo dieses Totem. Er wird meine Schnitzereien erkennen und Euch helfen.\n\nFolgt der Straße, die aus dem Camp Narache herausführt, und beeilt Euch. Schweift nicht von der Straße ab, Ihr könntet Euch sonst verirren.", sourceObjective = "Bringt Ahmo Donnerhuf im Dorf der Bluthufe Falkenwinds Totem. Folgt der Straße, die aus dem Camp Narache herausführt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14438] = { id = 14438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gemeinsame Nutzung des Landes", description = "Viele Konflikte verwunden dieses Land, {name}. Ich hoffe, dass Ihr nicht so viele wie ich ertragen müsst. Es gibt nur einen, bei dem ich um Eure Mithilfe bitten möchte. Er wird Euch deutlich machen, wie schrecklich sogar eine kleine Bedrohung für das Land sein kann, wenn man sie ignoriert.\n\nBleichmähnengnolle haben sich südlich vom Dorf der Bluthufe und in einer Höhle im Westen niedergelassen. Sie missachten unsere Versuche, mit ihnen zu kommunizieren, und vernichten ungezügelt die Tierwelt Mulgores.\n\nWorte allein genügen nicht mehr als Antwort.", sourceObjective = "Tötet 15 Gnolle der Bleichmähnen und kehrt dann zu Ahmo Donnerhorn ins Dorf der Bluthufe zurück.", completion = "Es ist gut, dass Ihr meine Aufgabe so ernst genommen habt, {name}. Respekt vor dem Land und seinen Kreaturen ist wichtig. Tod und Leben bilden einen Kreis... eine Notwendigkeit. Das eine kann nicht ohne das andere existieren. Nehmt Euch einen Moment Zeit, um darüber nachzudenken, und vergesst es niemals.", sourceObjectiveStatus = "unverified-source-field" }
quests[14439] = { id = 14439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Donnerfels", description = "Jetzt wird man Euch in unserer großen Stadt mit Respekt gegenübertreten. <Ein/Eine:r> {race}, <der/die:r> würdig ist, die Riten der Erdenmutter abzuschließen, hat diese Ehre verdient.\n\nSucht unseren jungen Anführer Baine Bluthuf auf, um Eure letzte Aufgabe zu erhalten. Er residiert auf der höchsten Anhöhe in Donnerfels.", sourceObjective = "Sprecht mit Baine Bluthuf in Donnerfels.", sourceObjectiveStatus = "unverified-source-field" }
quests[14440] = { id = 14440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riten der Erdenmutter", description = "Ihr habt die Riten der Erdenmutter absolviert und Euch einen Platz in Donnerfels verdient.\n\nUm den Platz zu verteidigen, den Ihr Euch so hart erarbeitet habt, müsst Ihr allerdings auch weiterhin Euren Wert für unser Volk beweisen.\n\nWir sind Jäger, {name}. Unten in Mulgore gibt es einen mächtigen Kodo namens Arra'chea. Zeigt mir Euer Können im Fährtenlesen und Jagen, indem Ihr mir das Horn von Arra'chea bringt.", sourceObjective = "Baine Bluthuf in Donnerfels möchte, dass Ihr ihm das Horn von Arra'chea bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14441] = { id = 14441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garroshs Autogramm", description = "Man sagt, dass Garrosh Höllschrei einer der größten Helden der Horde ist! Wenn ich einmal groß bin, will ich auch so ein Held sein!\n\nKennt Ihr Garrosh, {name}? Könntet Ihr mir einen Gefallen tun, bitte? Könnt Ihr sein Autogramm für mich bekommen? Ich weiß nicht, wie ich ihn fragen soll, und wahrscheinlich würde er jemandem wie mir gar nicht zuhören... aber Ihr! Ihr seid ein Abenteurer wie er! Ich wette, dass er Euch mir nichts, dir nichts ein Autogramm geben wird!\n\nBitte?", sourceObjective = "Reist zur Feste Grommash im Herzen des Tals der Stärke in Orgrimmar und kümmert Euch darum, für Euren Schützling ein Autogramm von Garrosh Höllschrei zu bekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14442] = { id = 14442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Lieblingsversuchsobjekt", description = "Ich weiß nicht, ob Ihr es bemerkt habt, {name}, aber dieser ganze Laborkomplex ist jenseits von Gut und Böse! Mir ist es ja egal, diese ganzen Hippogryphen abzuschreiben, aber mein wertvollstes Experiment ist abhandengekommen: Versuchsobjekt neun!\n\nVersuchsobjekt neun ist ein weiblicher Raptor, den wir aus dem Brachland importiert haben. Ich frage mich, ob sie noch am Leben ist? Versucht einmal, oberhalb des Hauptgebäudes westlich von hier nachzusehen, in der Nähe der riesigen, streng geheimen Rakete. Ihr könnt sie nicht übersehen.", sourceObjective = "Findet Versuchsobjekt neun irgendwo in der Nähe des Geheimlabors in Azshara.", completion = "Seid Ihr gekommen, um mir bei meiner Arbeit zu helfen? Meine Klauen sind recht geschickt, aber ich muss widerwillig zugeben, dass meine Arme extrem kurz und deswegen hinderlich sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[14443] = { id = 14443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der ramponierte Schwertgriff", description = "Dieser ramponierte alte Schwertgriff hat schon bessere Tage gesehen. Bevor er von der Klinge gebrochen wurde, muss es sich dabei um ein wunderschönes Beispiel der Schmiedekunst gehandelt haben.\n\nDie eleganten Symbole und exotischen Edelsteine, die den Griff schmücken, lassen darauf schließen, dass die Waffe womöglich einer mächtigen Person gehörte. Der Silberbund wäre sicherlich am Fund eines solchen Artefakts interessiert. Sucht ihren Repräsentanten in Quel'Delars Ruh südlich des Argentumturnierplatzes auf.", sourceObjective = "Bringt den ramponierten Schwertgriff zu Caladis Prunkspeer in Quel'Delars Ruh südlich des Argentumturnierplatzes.", progress = "Was habt Ihr denn da?", completion = "<Caladis nimmt Euch den Schwertgriff ab und begutachtet ihn langsam drehend in seiner Hand.>\n\nDer kommt mir irgendwie bekannt vor, als müsste ich wissen, woher er kommt. Ihr habt ihn in der Zitadelle gefunden? Äußerst interessant.\n\nEs gibt nur wenige, welche die Fähigkeit besitzen, solch eine Klinge herzustellen. Vielleicht können sie uns etwas über Euren Fund sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14444] = { id = 14444, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wissen der Drachen", description = "Es gibt keinen Zweifel: Dieser Schwertgriff stammt von einer mächtigen, uralten Waffe - aber welcher? Ich kann mich nicht daran erinnern, ein Schwert mit solchen Markierungen gesehen oder davon gehört zu haben, was jedoch nicht heißt, dass wir in einer Sackgasse gelandet sind.\n\nKorialstrasz, besser bekannt als Krasus, ist schon seit Langem ein Freund der Quel'dorei und der Kirin Tor. Seinem immensen Wissen und seinen gewaltigen Ressourcen nach zu urteilen wird er mit Sicherheit etwas wissen. Reist zur Spitze des Wyrmruhtempels und ersucht ihn um Rat. Meldet Euch anschließend bei Arkanist Tybalin im Inneren der Silbernen Enklave in Dalaran.", sourceObjective = "Sprecht mit Krasus in der Spitze des Wyrmruhtempels.", completion = "Wir dürfen das Buch nicht in den Händen der Sonnenhäscher belassen. Wenn wir das Schwert identifizieren und zu unserem Vorteil nutzen wollen, müssen wir einen Weg finden, an das Buch heranzukommen, das Krasus ihnen geliehen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[14445] = { id = 14445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschied auf Zeit", description = "Unsere Schicksale sind bis auf alle Ewigkeit miteinander verwoben. Es geschehen Dinge, die unsere Welt verändern und schließlich zerstören werden. Wir müssen ihnen ein Ende setzen, bevor es zu spät ist.\n\nVergesst nicht, Ihr könnt Euch immer auf mich verlassen, <Bruder/Schwester>! Wir werden uns auf der größeren Insel erneut sehen. Möget Ihr bis dahin Frieden finden, {name}.", sourceObjective = "Sprecht mit Sassy Hartzang an der Wilden Aussicht auf den Verlorenen Inseln.", completion = "Kann ich meinen Augen trauen? Seid Ihr das wirklich?\n\nIhr habt Thrall, den Kriegshäuptling der Horde gerettet?!\n\n<Sassy wirft Euch einen anerkennenden Blick zu.>\n\nNun, dann schauen wir mal, wie wir zu der größeren Insel gelangen. Bei all den Haien da unten habe ich wirklich keine Lust zu schwimmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[14446] = { id = 14446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kataklysmus!", description = "Hört mich an, {class}!\n\nDie Winde das Wandels haben sich zu einem gewaltigen Sturm vereint, der über ganz Azeroth hinwegfegt.\n\nSeid Ihr kühn genug, Euch dem wahren Grund für unser Elend zu stellen?\n\nNehmt Euren ganzen Mut zusammen, {race}, und betet, dass Stärke und Glück Euch bei den bevorstehenden Prüfungen helfen werden.\n\nEin unerwarteter Verbündeter hat einen Ruf an alle ausgestoßen, die ihn hören. Schaut in das Wasser der Weitsicht und erhascht einen Blick auf das Schicksal der Welt!", sourceObjective = "Nambria möchte, dass Ihr in das Wasser der Weitsicht blickt.", sourceObjectiveStatus = "unverified-source-field" }
quests[14447] = { id = 14447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Insider", description = "Wir sollten zwar keine Gelegenheit verpassen, der Allianz einen Schlag zu versetzen, aber wir dürfen die Geißel nicht außer Acht lassen.\n\nWir werden hier einige Wochen lang nicht zahlreich genug sein, um im Gletscher einen richtigen Angriff zu starten, aber das wird uns nicht davon abhalten, so viel wie möglich über ihre Verteidigung herauszufinden.\n\nIch habe unseren ansässigen Todesritter gebeten, Euch dabei zu beraten. Wer kennt den Feind besser als er sich selbst?\n\nErlaubt mir, Euch Koltira Todesweber vorzustellen.", sourceObjective = "Himmelshäscher Korm möchte, dass Ihr mit Koltira Todesweber auf der Orgrims Hammer sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[14448] = { id = 14448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Insider", description = "Wir sollten zwar keine Gelegenheit verpassen, der Allianz einen Schlag zu versetzen, aber wir dürfen die Geißel nicht außer Acht lassen.\n\nWir werden hier einige Wochen lang nicht zahlreich genug sein, um im Gletscher einen richtigen Angriff zu starten, aber das wird uns nicht davon abhalten, so viel wie möglich über ihre Verteidigung herauszufinden.\n\nIch habe unseren ansässigen Todesritter gebeten, Euch dabei zu beraten. Wer kennt den Feind besser als er sich selbst?\n\nErlaubt mir, Euch Koltira Todesweber vorzustellen.", sourceObjective = "Himmelshäscher Korm möchte, dass Ihr mit Koltira Todesweber auf der Orgrims Hammer sprecht.", sourceObjectiveStatus = "unverified-source-field" }
